export const MIGRATIONS: { name: string; sql: string }[] = [{"name":"0001_baseline.sql","sql":"-- ============================================================\r\n-- 0001 BASELINE — authoritative reconstruction of the LIVE schema\r\n--\r\n-- This file documents the production database AS IT ACTUALLY EXISTS\r\n-- (Supabase project uasnihapkcrgibnpqdyi), confirmed column-by-column\r\n-- against the live PostgREST API. It supersedes the previous scattered\r\n-- sources (database_schema.sql, database_setup.sql, database_migrations/,\r\n-- and the old supabase/migrations/001-004), which had drifted from prod.\r\n--\r\n-- Every CREATE is IF NOT EXISTS, so running this against the existing prod\r\n-- DB is a no-op; it exists to (a) document reality and (b) rebuild a fresh\r\n-- environment to match prod. Subsequent migrations (0002+) move the schema\r\n-- forward to what the application code requires.\r\n--\r\n-- PROVENANCE / CONFIDENCE:\r\n--   * Column PRESENCE: confirmed against live prod (high confidence).\r\n--   * Column TYPES for tables that never had a committed CREATE\r\n--     (employees, attendance_logs, employee_fingerprints, payroll_summary)\r\n--     are reconstructed from application code and marked [type inferred].\r\n--     To verify exact types, run in the SQL Editor:\r\n--       SELECT table_name, column_name, data_type FROM information_schema.columns\r\n--       WHERE table_schema='public' ORDER BY table_name, ordinal_position;\r\n--\r\n-- Row-Level Security is intentionally NOT configured here — it is addressed\r\n-- as a dedicated migration in a later phase. Today prod has RLS effectively\r\n-- open on all tables.\r\n-- ============================================================\r\n\r\n-- ─── users ───────────────────────────────────────────────────\r\n-- NOTE: prod has NO last_login / avatar_url / updated_at columns.\r\nCREATE TABLE IF NOT EXISTS users (\r\n  id                TEXT PRIMARY KEY,\r\n  name              TEXT NOT NULL,\r\n  employment_number TEXT UNIQUE NOT NULL,\r\n  role              TEXT NOT NULL CHECK (role IN\r\n                      ('admin','cashier','waiter','kitchen','hr','juice','staff','accounting')),\r\n  pin               TEXT NOT NULL,\r\n  email             TEXT UNIQUE NOT NULL,\r\n  status            TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','inactive')),\r\n  branch_id         TEXT NOT NULL,\r\n  hire_date         DATE,\r\n  hourly_rate       DECIMAL(10,2) DEFAULT 0,\r\n  job_role          TEXT,\r\n  created_at        TIMESTAMPTZ DEFAULT NOW()\r\n);\r\n\r\n-- ─── categories ──────────────────────────────────────────────\r\nCREATE TABLE IF NOT EXISTS categories (\r\n  id            TEXT PRIMARY KEY,\r\n  name          TEXT NOT NULL,\r\n  description   TEXT,\r\n  color         TEXT DEFAULT '#3B82F6',\r\n  icon          TEXT,\r\n  display_order INTEGER DEFAULT 0,\r\n  is_active     BOOLEAN DEFAULT true,\r\n  branch_id     TEXT NOT NULL,\r\n  created_at    TIMESTAMPTZ DEFAULT NOW()\r\n);\r\n\r\n-- ─── products ────────────────────────────────────────────────\r\n-- NOTE: station + availability_status confirmed present in prod\r\n-- (the previous schema files omitted them).\r\nCREATE TABLE IF NOT EXISTS products (\r\n  id                  TEXT PRIMARY KEY,\r\n  name                TEXT NOT NULL,\r\n  category_id         TEXT REFERENCES categories(id),\r\n  category            TEXT NOT NULL,\r\n  price               DECIMAL(10,2) NOT NULL,\r\n  stock               INTEGER DEFAULT 0,\r\n  image               TEXT,\r\n  sku                 TEXT UNIQUE,\r\n  tax_rate            DECIMAL(5,2) DEFAULT 0,\r\n  reorder_point       INTEGER DEFAULT 0,\r\n  branch_id           TEXT NOT NULL,\r\n  station             TEXT DEFAULT 'kitchen',                         -- [type inferred]\r\n  kitchen_status      TEXT DEFAULT 'available'\r\n                        CHECK (kitchen_status IN ('available','out-of-stock','finished')),\r\n  availability_status TEXT DEFAULT 'available'                        -- [type inferred]\r\n                        CHECK (availability_status IN ('available','out-of-stock','finished')),\r\n  is_active           BOOLEAN DEFAULT true,\r\n  created_at          TIMESTAMPTZ DEFAULT NOW()\r\n);\r\n\r\n-- ─── tables ──────────────────────────────────────────────────\r\nCREATE TABLE IF NOT EXISTS tables (\r\n  id                  TEXT PRIMARY KEY,\r\n  number              INTEGER NOT NULL,\r\n  capacity            INTEGER NOT NULL,\r\n  status              TEXT DEFAULT 'available'\r\n                        CHECK (status IN ('available','occupied','reserved')),\r\n  branch_id           TEXT NOT NULL,\r\n  current_order_id    TEXT,\r\n  assigned_cashier_id TEXT,\r\n  needs_waiter        BOOLEAN DEFAULT false,\r\n  created_at          TIMESTAMPTZ DEFAULT NOW(),\r\n  UNIQUE (branch_id, number)\r\n);\r\n\r\n-- ─── orders ──────────────────────────────────────────────────\r\n-- NOTE: waiters / cashier_id / cashier_name / bill_number confirmed\r\n-- present in prod (the previous schema files omitted all four).\r\nCREATE TABLE IF NOT EXISTS orders (\r\n  id             TEXT PRIMARY KEY,\r\n  table_id       TEXT REFERENCES tables(id),\r\n  table_number   INTEGER NOT NULL,\r\n  subtotal       DECIMAL(10,2) DEFAULT 0,\r\n  tax            DECIMAL(10,2) DEFAULT 0,\r\n  discount       DECIMAL(10,2) DEFAULT 0,\r\n  total          DECIMAL(10,2) DEFAULT 0,\r\n  status         TEXT DEFAULT 'open' CHECK (status IN ('open','completed','cancelled')),\r\n  payment_status TEXT DEFAULT 'unpaid' CHECK (payment_status IN ('unpaid','paid')),\r\n  payment_method TEXT,\r\n  order_type     TEXT DEFAULT 'dine-in' CHECK (order_type IN ('dine-in','takeaway')),\r\n  waiters        JSONB DEFAULT '[]'::jsonb,   -- string[] of user ids   [type inferred]\r\n  cashier_id     TEXT,                        -- [type inferred]\r\n  cashier_name   TEXT,                        -- [type inferred]\r\n  bill_number    TEXT,                        -- [type inferred]\r\n  branch_id      TEXT NOT NULL,\r\n  created_at     TIMESTAMPTZ DEFAULT NOW(),\r\n  completed_at   TIMESTAMPTZ\r\n);\r\n\r\n-- ─── order_items ─────────────────────────────────────────────\r\n-- NOTE: station + branch_id confirmed present in prod. The realtime\r\n-- sync filter on order_items.branch_id therefore works as written.\r\nCREATE TABLE IF NOT EXISTS order_items (\r\n  id              TEXT PRIMARY KEY,\r\n  order_id        TEXT REFERENCES orders(id) ON DELETE CASCADE,\r\n  product_id      TEXT REFERENCES products(id),\r\n  product_name    TEXT NOT NULL,\r\n  quantity        INTEGER NOT NULL,\r\n  price           DECIMAL(10,2) NOT NULL,\r\n  subtotal        DECIMAL(10,2) NOT NULL,\r\n  added_by        TEXT NOT NULL,\r\n  added_by_name   TEXT NOT NULL,\r\n  status          TEXT DEFAULT 'pending'\r\n                    CHECK (status IN ('pending','preparing','ready','served')),\r\n  notes           TEXT,\r\n  sent_to_kitchen BOOLEAN DEFAULT true,\r\n  station         TEXT,                        -- [type inferred]\r\n  branch_id       TEXT,                        -- [type inferred]\r\n  created_at      TIMESTAMPTZ DEFAULT NOW()\r\n);\r\n\r\n-- ─── qr_sessions ─────────────────────────────────────────────\r\nCREATE TABLE IF NOT EXISTS qr_sessions (\r\n  id               TEXT PRIMARY KEY,\r\n  table_id         TEXT REFERENCES tables(id) ON DELETE CASCADE,\r\n  active           BOOLEAN DEFAULT true,\r\n  started_at       TIMESTAMPTZ DEFAULT NOW(),\r\n  last_activity_at TIMESTAMPTZ DEFAULT NOW(),\r\n  branch_id        TEXT NOT NULL,\r\n  created_at       TIMESTAMPTZ DEFAULT NOW(),\r\n  UNIQUE (table_id)\r\n);\r\n\r\n-- ─── expenses ────────────────────────────────────────────────\r\nCREATE TABLE IF NOT EXISTS expenses (\r\n  id              TEXT PRIMARY KEY,\r\n  branch_id       TEXT NOT NULL,\r\n  category        TEXT NOT NULL DEFAULT 'other',\r\n  description     TEXT NOT NULL,\r\n  amount          DECIMAL(10,2) NOT NULL,\r\n  date            DATE NOT NULL DEFAULT CURRENT_DATE,\r\n  created_by      TEXT NOT NULL,\r\n  created_by_name TEXT NOT NULL,\r\n  status          TEXT NOT NULL DEFAULT 'approved',\r\n  receipt         TEXT,\r\n  created_at      TIMESTAMPTZ DEFAULT NOW()\r\n);\r\n\r\n-- ─── customers (loyalty) ─────────────────────────────────────  [types inferred]\r\n-- NOTE: the app inserts without an id, so id carries a DB-side default.\r\nCREATE TABLE IF NOT EXISTS customers (\r\n  id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  name           TEXT NOT NULL,\r\n  phone          TEXT NOT NULL,\r\n  email          TEXT,\r\n  points_balance INTEGER DEFAULT 0,\r\n  total_spent    DECIMAL(10,2) DEFAULT 0,\r\n  total_visits   INTEGER DEFAULT 0,\r\n  branch_id      TEXT NOT NULL,\r\n  created_at     TIMESTAMPTZ DEFAULT NOW()\r\n);\r\n\r\n-- ─── loyalty_transactions ────────────────────────────────────  [types inferred]\r\nCREATE TABLE IF NOT EXISTS loyalty_transactions (\r\n  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  customer_id UUID REFERENCES customers(id) ON DELETE CASCADE,\r\n  order_id    TEXT REFERENCES orders(id),\r\n  type        TEXT NOT NULL CHECK (type IN ('earn','redeem','adjust')),\r\n  points      INTEGER NOT NULL,\r\n  description TEXT,\r\n  branch_id   TEXT NOT NULL,\r\n  created_at  TIMESTAMPTZ DEFAULT NOW()\r\n);\r\n\r\n-- ─── ingredient_orders (kitchen → owner via WhatsApp) ────────  [types inferred]\r\nCREATE TABLE IF NOT EXISTS ingredient_orders (\r\n  id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  requested_by      TEXT NOT NULL,\r\n  requested_by_name TEXT NOT NULL,\r\n  role              TEXT,\r\n  items             JSONB NOT NULL DEFAULT '[]'::jsonb,\r\n  notes             TEXT,\r\n  status            TEXT DEFAULT 'pending',\r\n  branch_id         TEXT NOT NULL,\r\n  created_at        TIMESTAMPTZ DEFAULT NOW()\r\n);\r\n\r\n-- ─── employees ───────────────────────────────────────────────\r\n-- Base table as it exists in prod TODAY. The columns the application\r\n-- also needs (employee_number, email, phone, department, hire_date,\r\n-- avatar_url, notes) are MISSING in prod and added in 0002. [types inferred]\r\nCREATE TABLE IF NOT EXISTS employees (\r\n  id                    TEXT PRIMARY KEY,\r\n  user_id               TEXT,\r\n  employee_id           TEXT UNIQUE NOT NULL,\r\n  full_name             TEXT NOT NULL,\r\n  role                  TEXT NOT NULL,\r\n  monthly_salary        DECIMAL(10,2) DEFAULT 0,\r\n  shift_start           TEXT,\r\n  shift_end             TEXT,\r\n  early_checkin_minutes INTEGER DEFAULT 5,\r\n  late_checkout_minutes INTEGER DEFAULT 5,\r\n  status                TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','inactive')),\r\n  branch_id             TEXT NOT NULL,\r\n  created_at            TIMESTAMPTZ DEFAULT NOW(),\r\n  updated_at            TIMESTAMPTZ DEFAULT NOW()\r\n);\r\n\r\n-- ─── attendance_logs ─────────────────────────────────────────  [types inferred]\r\nCREATE TABLE IF NOT EXISTS attendance_logs (\r\n  id                  TEXT PRIMARY KEY,\r\n  employee_id         TEXT NOT NULL,\r\n  full_name           TEXT NOT NULL,\r\n  log_date            DATE NOT NULL,\r\n  check_in_time       TIMESTAMPTZ,\r\n  check_out_time      TIMESTAMPTZ,\r\n  scheduled_start     TEXT,\r\n  scheduled_end       TEXT,\r\n  late_minutes        INTEGER DEFAULT 0,\r\n  early_leave_minutes INTEGER DEFAULT 0,\r\n  overtime_minutes    INTEGER DEFAULT 0,\r\n  status              TEXT,\r\n  check_in_method     TEXT,\r\n  check_out_method    TEXT,\r\n  notes               TEXT,\r\n  branch_id           TEXT NOT NULL,\r\n  created_at          TIMESTAMPTZ DEFAULT NOW()\r\n);\r\n\r\n-- ─── employee_fingerprints ───────────────────────────────────  [types inferred]\r\n-- NOTE: prod has NO created_at column on this table.\r\nCREATE TABLE IF NOT EXISTS employee_fingerprints (\r\n  id            TEXT PRIMARY KEY,\r\n  employee_id   TEXT NOT NULL,\r\n  template_data TEXT NOT NULL,\r\n  template_hash TEXT NOT NULL,\r\n  finger_index  INTEGER NOT NULL,\r\n  quality_score INTEGER DEFAULT 0,\r\n  is_active     BOOLEAN DEFAULT true,\r\n  enrolled_by   TEXT,\r\n  enrolled_at   TIMESTAMPTZ DEFAULT NOW()\r\n);\r\n\r\n-- ─── payroll_summary ─────────────────────────────────────────  [types inferred]\r\nCREATE TABLE IF NOT EXISTS payroll_summary (\r\n  id                     TEXT PRIMARY KEY,\r\n  employee_id            TEXT NOT NULL,\r\n  full_name              TEXT NOT NULL,\r\n  month                  INTEGER NOT NULL,\r\n  year                   INTEGER NOT NULL,\r\n  monthly_salary         DECIMAL(10,2) DEFAULT 0,\r\n  working_days           INTEGER DEFAULT 0,\r\n  present_days           INTEGER DEFAULT 0,\r\n  absent_days            INTEGER DEFAULT 0,\r\n  total_late_minutes     INTEGER DEFAULT 0,\r\n  total_overtime_minutes INTEGER DEFAULT 0,\r\n  late_deduction         DECIMAL(10,2) DEFAULT 0,\r\n  overtime_bonus         DECIMAL(10,2) DEFAULT 0,\r\n  net_salary             DECIMAL(10,2) DEFAULT 0,\r\n  status                 TEXT DEFAULT 'draft' CHECK (status IN ('draft','approved','paid')),\r\n  approved_by            TEXT,\r\n  approved_at            TIMESTAMPTZ,\r\n  branch_id              TEXT NOT NULL,\r\n  created_at             TIMESTAMPTZ DEFAULT NOW(),\r\n  UNIQUE (employee_id, month, year)\r\n);\r\n\r\n-- ─── indexes ─────────────────────────────────────────────────\r\nCREATE INDEX IF NOT EXISTS idx_emp_user_id  ON employees(user_id);\r\nCREATE INDEX IF NOT EXISTS idx_emp_status   ON employees(status);\r\nCREATE INDEX IF NOT EXISTS idx_emp_branch   ON employees(branch_id);\r\nCREATE INDEX IF NOT EXISTS idx_emp_role     ON employees(role);\r\nCREATE INDEX IF NOT EXISTS idx_att_employee ON attendance_logs(employee_id);\r\nCREATE INDEX IF NOT EXISTS idx_att_date     ON attendance_logs(log_date);\r\nCREATE INDEX IF NOT EXISTS idx_att_branch   ON attendance_logs(branch_id);\r\nCREATE INDEX IF NOT EXISTS idx_fp_employee  ON employee_fingerprints(employee_id);\r\nCREATE INDEX IF NOT EXISTS idx_fp_active    ON employee_fingerprints(is_active);\r\nCREATE INDEX IF NOT EXISTS idx_pay_employee ON payroll_summary(employee_id);\r\nCREATE INDEX IF NOT EXISTS idx_pay_period   ON payroll_summary(month, year);\r\nCREATE INDEX IF NOT EXISTS idx_orders_branch_status ON orders(branch_id, status);\r\nCREATE INDEX IF NOT EXISTS idx_order_items_order    ON order_items(order_id);\r\nCREATE INDEX IF NOT EXISTS idx_customers_branch     ON customers(branch_id);\r\nCREATE INDEX IF NOT EXISTS idx_loyalty_customer     ON loyalty_transactions(customer_id);\r\nCREATE INDEX IF NOT EXISTS idx_ingredient_branch    ON ingredient_orders(branch_id);\r\n"},{"name":"0002_workforce_reconcile.sql","sql":"-- ============================================================\r\n-- 0002 WORKFORCE RECONCILE — make prod match the application code\r\n--\r\n-- Phase-0 probing confirmed three runtime-breaking gaps in production:\r\n--   1. employees is MISSING 7 columns the app reads/writes, so\r\n--      WorkforceController.createEmployee() fails with a 400.\r\n--   2. leave_requests does NOT EXIST, so every leave call 404s.\r\n--   3. users.role CHECK does not include manager/supervisor/staff,\r\n--      so creating those roles is rejected.\r\n--\r\n-- This migration is idempotent (IF NOT EXISTS / DROP IF EXISTS) and safe\r\n-- to run multiple times. APPLY THIS to prod via the Supabase SQL Editor —\r\n-- without it, the employee-create and leave features remain broken and\r\n-- types.ts references columns prod lacks.\r\n-- ============================================================\r\n\r\n-- ─── 1. users: Rename 'position' to 'job_role' ───────────────\r\n-- This fixes the reserved keyword conflict.\r\nDO $$ \r\nBEGIN\r\n  IF EXISTS (SELECT 1 FROM information_schema.columns \r\n             WHERE table_name = 'users' AND column_name = 'position') THEN\r\n    ALTER TABLE users RENAME COLUMN \"position\" TO job_role;\r\n  END IF;\r\nEND $$;\r\n\r\n-- ─── 2. employees: add the columns the application requires ──\r\nALTER TABLE employees\r\n  ADD COLUMN IF NOT EXISTS employee_number TEXT,\r\n  ADD COLUMN IF NOT EXISTS email           TEXT,\r\n  ADD COLUMN IF NOT EXISTS phone           TEXT,\r\n  ADD COLUMN IF NOT EXISTS department      TEXT DEFAULT 'Operations',\r\n  ADD COLUMN IF NOT EXISTS hire_date       DATE DEFAULT CURRENT_DATE,\r\n  ADD COLUMN IF NOT EXISTS avatar_url      TEXT,\r\n  ADD COLUMN IF NOT EXISTS notes           TEXT;\r\n\r\n-- Back-fill employee_number from employee_id for any existing rows,\r\n-- then enforce NOT NULL to match the application contract.\r\nUPDATE employees SET employee_number = employee_id WHERE employee_number IS NULL;\r\nALTER TABLE employees ALTER COLUMN employee_number SET NOT NULL;\r\n\r\n-- An admin must never be an employee (the app guards this in code too).\r\nALTER TABLE employees DROP CONSTRAINT IF EXISTS employees_no_admin;\r\nALTER TABLE employees ADD  CONSTRAINT employees_no_admin CHECK (role <> 'admin');\r\n\r\n-- ─── 3. users: extend the role CHECK to the full role set ────\r\n-- UserRole in types.ts defines 11 roles. Includes 'swaiter' (Super Waiter) so\r\n-- this constraint does not reject an existing swaiter row when re-applied to a\r\n-- database that already carries app data (0006 also adds swaiter — same set).\r\nALTER TABLE users DROP CONSTRAINT IF EXISTS users_role_check;\r\nALTER TABLE users ADD  CONSTRAINT users_role_check CHECK (role IN\r\n  ('admin','cashier','waiter','swaiter','kitchen','hr','juice','staff','accounting','manager','supervisor'));\r\n\r\n-- ─── 4. leave_requests: create the missing table ─────────────\r\nCREATE TABLE IF NOT EXISTS leave_requests (\r\n  id          TEXT PRIMARY KEY,\r\n  employee_id TEXT NOT NULL,\r\n  leave_type  TEXT NOT NULL CHECK (leave_type IN ('annual','sick','emergency','unpaid','other')),\r\n  start_date  DATE NOT NULL,\r\n  end_date    DATE NOT NULL,\r\n  days_count  INTEGER NOT NULL,\r\n  reason      TEXT,\r\n  status      TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected')),\r\n  reviewed_by TEXT,\r\n  reviewed_at TIMESTAMPTZ,\r\n  branch_id   TEXT NOT NULL,\r\n  created_at  TIMESTAMPTZ DEFAULT NOW()\r\n);\r\n\r\nCREATE INDEX IF NOT EXISTS idx_leave_employee ON leave_requests(employee_id);\r\nCREATE INDEX IF NOT EXISTS idx_leave_status   ON leave_requests(status);\r\nCREATE INDEX IF NOT EXISTS idx_leave_branch   ON leave_requests(branch_id);\r\n\r\n-- Reload PostgREST's schema cache so the new columns/table are visible.\r\nNOTIFY pgrst, 'reload schema';\r\n"},{"name":"0003_backfill_employees_from_users.sql","sql":"-- ============================================================\r\n-- 0003 BACKFILL employees ← users   (DATA migration — OPTIONAL)\r\n--\r\n-- Salvaged from the old migration 002, which could never succeed because\r\n-- the target columns did not exist until 0002. Run AFTER 0002.\r\n--\r\n-- This INSERTS one employee row per non-admin user that does not already\r\n-- have one, so the (currently empty) employees table reflects existing\r\n-- staff. It writes data — review before running. Idempotent: re-running\r\n-- inserts nothing new (guarded by NOT EXISTS + ON CONFLICT).\r\n-- ============================================================\r\n\r\nINSERT INTO employees (\r\n  id, user_id, employee_id, employee_number, full_name, email, role,\r\n  department, hire_date, monthly_salary, shift_start, shift_end,\r\n  early_checkin_minutes, late_checkout_minutes, status, branch_id,\r\n  created_at, updated_at\r\n)\r\nSELECT\r\n  'emp-migrated-' || u.id,\r\n  u.id,\r\n  u.employment_number,\r\n  u.employment_number,\r\n  u.name,\r\n  u.email,\r\n  u.role,\r\n  CASE\r\n    WHEN u.role IN ('kitchen','juice') THEN 'Kitchen'\r\n    WHEN u.role = 'cashier'            THEN 'Cashier'\r\n    WHEN u.role = 'waiter'             THEN 'Service'\r\n    WHEN u.role = 'hr'                 THEN 'HR'\r\n    WHEN u.role = 'accounting'         THEN 'Finance'\r\n    WHEN u.role IN ('manager','supervisor') THEN 'Management'\r\n    ELSE 'Operations'\r\n  END,\r\n  COALESCE(u.hire_date::DATE, u.created_at::DATE),\r\n  COALESCE(u.hourly_rate * 160, 0),\r\n  '09:00',\r\n  '18:00',\r\n  5,\r\n  5,\r\n  u.status,\r\n  u.branch_id,\r\n  u.created_at,\r\n  NOW()\r\nFROM users u\r\nWHERE u.role <> 'admin'\r\n  AND NOT EXISTS (SELECT 1 FROM employees e WHERE e.user_id = u.id)\r\nON CONFLICT (employee_id) DO NOTHING;\r\n"},{"name":"0004_pin_auth.sql","sql":"-- ============================================================\r\n-- 0004 PIN AUTH — hash PINs + verify them server-side\r\n--\r\n-- Closes the worst part of the auth hole: today the client downloads the\r\n-- full users list (including plaintext `pin`) and compares PINs in the\r\n-- browser. After this migration, login can verify a PIN through a\r\n-- SECURITY DEFINER function that returns only safe columns — the client\r\n-- never receives any PIN.\r\n--\r\n-- SAFE TO APPLY: this migration does NOT enable RLS and does NOT drop the\r\n-- `pin` column, so the existing app keeps working. A BEFORE trigger keeps\r\n-- `pin_hash` in sync with any code path that still writes plaintext `pin`,\r\n-- so newly created staff authenticate correctly.\r\n--\r\n-- Full lock-down (drop plaintext `pin`, enable RLS) is 0005 — read SECURITY.md\r\n-- first; it requires an auth-model decision and will break the anon-key app\r\n-- as currently architected.\r\n-- ============================================================\r\n\r\nCREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA extensions;\r\n\r\n-- 1. Hashed-PIN column + backfill from existing plaintext PINs (bcrypt).\r\nALTER TABLE users ADD COLUMN IF NOT EXISTS pin_hash TEXT;\r\n\r\nUPDATE users\r\nSET pin_hash = extensions.crypt(pin, extensions.gen_salt('bf'))\r\nWHERE pin_hash IS NULL AND pin IS NOT NULL;\r\n\r\n-- 2. Keep pin_hash in sync for any writer that still sets plaintext `pin`\r\n--    (StaffController.addStaff / WorkforceController.createEmployee / updateStaff).\r\nCREATE OR REPLACE FUNCTION public.users_sync_pin_hash()\r\nRETURNS TRIGGER\r\nLANGUAGE plpgsql\r\nSECURITY DEFINER\r\nSET search_path = public, extensions\r\nAS $$\r\nBEGIN\r\n  IF NEW.pin IS NOT NULL\r\n     AND (TG_OP = 'INSERT' OR NEW.pin IS DISTINCT FROM OLD.pin) THEN\r\n    NEW.pin_hash := extensions.crypt(NEW.pin, extensions.gen_salt('bf'));\r\n  END IF;\r\n  RETURN NEW;\r\nEND;\r\n$$;\r\n\r\nDROP TRIGGER IF EXISTS trg_users_sync_pin_hash ON users;\r\nCREATE TRIGGER trg_users_sync_pin_hash\r\n  BEFORE INSERT OR UPDATE ON users\r\n  FOR EACH ROW EXECUTE FUNCTION public.users_sync_pin_hash();\r\n\r\n-- 3. Verify a PIN server-side. Returns the matching active user's SAFE\r\n--    columns only — never a PIN. SECURITY DEFINER so it works regardless of\r\n--    RLS, and is the ONLY way the client should resolve a PIN.\r\nCREATE OR REPLACE FUNCTION public.verify_staff_pin(p_pin TEXT)\r\nRETURNS TABLE (\r\n  id TEXT, name TEXT, employment_number TEXT, role TEXT, email TEXT,\r\n  status TEXT, branch_id TEXT, created_at TIMESTAMPTZ,\r\n  hire_date DATE, hourly_rate NUMERIC, job_role TEXT\r\n)\r\nLANGUAGE sql\r\nSECURITY DEFINER\r\nSET search_path = public, extensions\r\nAS $$\r\n  SELECT u.id, u.name, u.employment_number, u.role, u.email, u.status,\r\n         u.branch_id, u.created_at, u.hire_date, u.hourly_rate, u.job_role\r\n  FROM users u\r\n  WHERE u.status = 'active'\r\n    AND u.pin_hash IS NOT NULL\r\n    AND u.pin_hash = extensions.crypt(p_pin, u.pin_hash)\r\n  LIMIT 1;\r\n$$;\r\n\r\nREVOKE ALL ON FUNCTION public.verify_staff_pin(TEXT) FROM PUBLIC;\r\nGRANT EXECUTE ON FUNCTION public.verify_staff_pin(TEXT) TO anon, authenticated;\r\n\r\n-- 4. Set a PIN without ever exposing it (for the eventual hardening in 0005,\r\n--    where the `pin` column is dropped and writers call this instead).\r\nCREATE OR REPLACE FUNCTION public.set_staff_pin(p_user_id TEXT, p_pin TEXT)\r\nRETURNS VOID\r\nLANGUAGE sql\r\nSECURITY DEFINER\r\nSET search_path = public, extensions\r\nAS $$\r\n  UPDATE users SET pin_hash = extensions.crypt(p_pin, extensions.gen_salt('bf'))\r\n  WHERE id = p_user_id;\r\n$$;\r\n\r\nREVOKE ALL ON FUNCTION public.set_staff_pin(TEXT, TEXT) FROM PUBLIC;\r\nGRANT EXECUTE ON FUNCTION public.set_staff_pin(TEXT, TEXT) TO anon, authenticated;\r\n\r\nNOTIFY pgrst, 'reload schema';\r\n"},{"name":"0005_secure_qr_tokens.sql","sql":"-- ============================================================\r\n-- 0005_secure_qr_tokens.sql\r\n--\r\n-- Adds cryptographic token support to qr_sessions so that\r\n-- customer-facing QR URLs never expose the real table UUID.\r\n--\r\n-- Changes:\r\n--   1. Add `token` column (64-char hex, unique) to qr_sessions.\r\n--   2. Add `expires_at` column for automatic TTL enforcement.\r\n--   3. Add an index on `token` for fast lookups.\r\n--   4. Add a partial index to enforce one active session per table.\r\n--\r\n-- Run this in the Supabase SQL Editor.\r\n-- ============================================================\r\n\r\n-- 1. Add token column (nullable first so existing rows don't break)\r\nALTER TABLE qr_sessions\r\n  ADD COLUMN IF NOT EXISTS token TEXT UNIQUE,\r\n  ADD COLUMN IF NOT EXISTS expires_at TIMESTAMPTZ;\r\n\r\n-- 2. Backfill existing rows with a placeholder token so the UNIQUE\r\n--    constraint doesn't reject them. They will be replaced the next\r\n--    time the admin regenerates a QR code.\r\nUPDATE qr_sessions\r\nSET token = 'legacy-' || id,\r\n    expires_at = NOW() -- mark existing sessions as immediately expired\r\nWHERE token IS NULL;\r\n\r\n-- 3. Index for fast token lookups (the hot path on every QR scan)\r\nCREATE INDEX IF NOT EXISTS idx_qr_sessions_token ON qr_sessions(token);\r\n\r\n-- 4. Index to enforce one active session per table\r\nCREATE UNIQUE INDEX IF NOT EXISTS idx_qr_sessions_active_table\r\n  ON qr_sessions(table_id)\r\n  WHERE active = true;\r\n\r\n-- Done. Reload PostgREST schema cache.\r\nNOTIFY pgrst, 'reload schema';\r\n"},{"name":"0006_add_swaiter_role.sql","sql":"-- 0006_add_swaiter_role.sql\r\n-- Adds the 'swaiter' (Super Waiter) role — a normal waiter that can ALSO manage\r\n-- invoices & quotations. The only schema change needed is to widen the\r\n-- users.role CHECK constraint so the new role can be saved.\r\n--\r\n-- Apply to prod: YES (required before any Super Waiter can be created).\r\n-- Safe & idempotent: drops and re-adds the named constraint.\r\n\r\nALTER TABLE users DROP CONSTRAINT IF EXISTS users_role_check;\r\nALTER TABLE users ADD  CONSTRAINT users_role_check CHECK (role IN\r\n  ('admin','cashier','waiter','swaiter','kitchen','hr','juice','staff','accounting','manager','supervisor'));\r\n\r\n-- employees.role only has the employees_no_admin CHECK (role <> 'admin'),\r\n-- which 'swaiter' already satisfies, so no change is required there.\r\n"},{"name":"0007_pickup_orders.sql","sql":"-- ============================================================\r\n-- 0007_pickup_orders.sql\r\n--\r\n-- Adds the \"Pickup Order\" feature: secure single-use customer links,\r\n-- pickup-specific order fields, online-payment verification states,\r\n-- and an audit log. Pickup orders are normal `orders` rows\r\n-- (order_type = 'pickup') so they flow through the existing cashier,\r\n-- kitchen, dashboard, reporting and accounting logic unchanged.\r\n--\r\n-- Run in the Supabase SQL Editor.\r\n-- ============================================================\r\n\r\n-- 1. orders.order_type — allow 'pickup'\r\nALTER TABLE orders DROP CONSTRAINT IF EXISTS orders_order_type_check;\r\nALTER TABLE orders ADD  CONSTRAINT orders_order_type_check\r\n  CHECK (order_type IN ('dine-in','takeaway','pickup'));\r\n\r\n-- 2. orders.payment_status — allow online-payment verification states\r\nALTER TABLE orders DROP CONSTRAINT IF EXISTS orders_payment_status_check;\r\nALTER TABLE orders ADD  CONSTRAINT orders_payment_status_check\r\n  CHECK (payment_status IN ('unpaid','paid','pending_verification','rejected'));\r\n\r\n-- 3. Pickup-specific columns on orders (all nullable; only used by pickup orders)\r\nALTER TABLE orders\r\n  ADD COLUMN IF NOT EXISTS pickup_method      TEXT,   -- 'grab' | 'lalamove' | 'self'\r\n  ADD COLUMN IF NOT EXISTS pickup_status      TEXT,   -- 'preparing' | 'ready' | 'picked'\r\n  ADD COLUMN IF NOT EXISTS pickup_pay_type    TEXT,   -- 'cash' | 'online'\r\n  ADD COLUMN IF NOT EXISTS customer_name      TEXT,\r\n  ADD COLUMN IF NOT EXISTS customer_phone     TEXT,\r\n  ADD COLUMN IF NOT EXISTS customer_email     TEXT,\r\n  ADD COLUMN IF NOT EXISTS payment_receipt_url TEXT;\r\n\r\n-- 4. Secure pickup link tokens (one per created pickup order)\r\nCREATE TABLE IF NOT EXISTS pickup_tokens (\r\n  id             TEXT PRIMARY KEY,\r\n  token          TEXT UNIQUE NOT NULL,\r\n  branch_id      TEXT NOT NULL,\r\n  created_by     TEXT,\r\n  created_by_name TEXT,\r\n  order_id       TEXT REFERENCES orders(id) ON DELETE SET NULL,\r\n  status         TEXT NOT NULL DEFAULT 'new'\r\n                   CHECK (status IN ('new','ordered','completed','expired')),\r\n  active         BOOLEAN NOT NULL DEFAULT true,\r\n  expires_at     TIMESTAMPTZ,\r\n  created_at     TIMESTAMPTZ DEFAULT NOW()\r\n);\r\nCREATE INDEX IF NOT EXISTS idx_pickup_tokens_token ON pickup_tokens(token);\r\nCREATE INDEX IF NOT EXISTS idx_pickup_tokens_branch ON pickup_tokens(branch_id);\r\n\r\n-- 5. Audit log (full audit trail for pickup lifecycle + payment decisions)\r\nCREATE TABLE IF NOT EXISTS audit_logs (\r\n  id          TEXT PRIMARY KEY,\r\n  action      TEXT NOT NULL,          -- e.g. 'pickup.link_created', 'pickup.order_submitted'\r\n  entity      TEXT,                   -- e.g. 'pickup_token', 'order'\r\n  entity_id   TEXT,\r\n  user_id     TEXT,\r\n  user_name   TEXT,\r\n  branch_id   TEXT,\r\n  details     JSONB DEFAULT '{}'::jsonb,\r\n  created_at  TIMESTAMPTZ DEFAULT NOW()\r\n);\r\nCREATE INDEX IF NOT EXISTS idx_audit_logs_branch ON audit_logs(branch_id);\r\nCREATE INDEX IF NOT EXISTS idx_audit_logs_entity ON audit_logs(entity, entity_id);\r\n\r\n-- 6. Storage buckets for payment receipts and the merchant payment QR.\r\n--    Public read so the customer page and staff can display them; writes are\r\n--    open (matches the project's current open-RLS posture — tighten later).\r\nINSERT INTO storage.buckets (id, name, public)\r\n  VALUES ('pickup-receipts','pickup-receipts', true)\r\n  ON CONFLICT (id) DO NOTHING;\r\nINSERT INTO storage.buckets (id, name, public)\r\n  VALUES ('merchant-qr','merchant-qr', true)\r\n  ON CONFLICT (id) DO NOTHING;\r\n\r\nDO $$\r\nBEGIN\r\n  -- pickup-receipts: anyone can upload a receipt and read it back\r\n  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'pickup_receipts_insert') THEN\r\n    CREATE POLICY \"pickup_receipts_insert\" ON storage.objects\r\n      FOR INSERT TO anon, authenticated WITH CHECK (bucket_id = 'pickup-receipts');\r\n  END IF;\r\n  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'pickup_receipts_read') THEN\r\n    CREATE POLICY \"pickup_receipts_read\" ON storage.objects\r\n      FOR SELECT TO anon, authenticated USING (bucket_id = 'pickup-receipts');\r\n  END IF;\r\n  -- merchant-qr: staff upload, everyone reads\r\n  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'merchant_qr_write') THEN\r\n    CREATE POLICY \"merchant_qr_write\" ON storage.objects\r\n      FOR INSERT TO anon, authenticated WITH CHECK (bucket_id = 'merchant-qr');\r\n  END IF;\r\n  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'merchant_qr_update') THEN\r\n    CREATE POLICY \"merchant_qr_update\" ON storage.objects\r\n      FOR UPDATE TO anon, authenticated USING (bucket_id = 'merchant-qr');\r\n  END IF;\r\n  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'merchant_qr_read') THEN\r\n    CREATE POLICY \"merchant_qr_read\" ON storage.objects\r\n      FOR SELECT TO anon, authenticated USING (bucket_id = 'merchant-qr');\r\n  END IF;\r\nEND $$;\r\n\r\n-- Reload PostgREST schema cache so the new columns/tables are visible.\r\nNOTIFY pgrst, 'reload schema';\r\n"},{"name":"0008_group_ordering.sql","sql":"-- ============================================================\r\n-- 0008_group_ordering.sql\r\n--\r\n-- Secure multi-device GROUP ordering for table QR codes.\r\n--\r\n--   * tables.qr_token  — a STABLE, cryptographically-random token printed in the\r\n--     QR. It identifies the table only (never the raw UUID) and is reusable\r\n--     forever across many dining groups.\r\n--   * order_groups     — one ACTIVE group per table = the current dining party.\r\n--   * guest_sessions   — one per customer device that scans; all sessions of a\r\n--     party share the same group. Each has its own random token + UUIDv7 id.\r\n--\r\n-- Closing a table closes the group + all its guest sessions, which invalidates\r\n-- every token. The next scan of the (still valid) table QR starts a fresh group.\r\n--\r\n-- Run in the Supabase SQL Editor.  (pgcrypto provides gen_random_bytes.)\r\n-- ============================================================\r\nCREATE EXTENSION IF NOT EXISTS pgcrypto;\r\n\r\n-- 1. Stable per-table QR token (identifies the table; never exposes the UUID)\r\nALTER TABLE tables ADD COLUMN IF NOT EXISTS qr_token TEXT UNIQUE;\r\nUPDATE tables SET qr_token = encode(gen_random_bytes(32), 'hex') WHERE qr_token IS NULL;\r\nCREATE INDEX IF NOT EXISTS idx_tables_qr_token ON tables(qr_token);\r\n\r\n-- 2. Order groups — the dining party currently at a table\r\nCREATE TABLE IF NOT EXISTS order_groups (\r\n  id          TEXT PRIMARY KEY,                 -- UUIDv7 (generated client-side)\r\n  table_id    TEXT NOT NULL REFERENCES tables(id),\r\n  branch_id   TEXT NOT NULL,\r\n  order_id    TEXT,                             -- the table's aggregate order\r\n  status      TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','closed')),\r\n  created_at  TIMESTAMPTZ DEFAULT NOW(),\r\n  closed_at   TIMESTAMPTZ\r\n);\r\nCREATE INDEX IF NOT EXISTS idx_order_groups_table ON order_groups(table_id);\r\n-- At most one ACTIVE group per table.\r\nCREATE UNIQUE INDEX IF NOT EXISTS idx_order_groups_active_table\r\n  ON order_groups(table_id) WHERE status = 'active';\r\n\r\n-- 3. Guest sessions — one per scanning device, all sharing the group\r\nCREATE TABLE IF NOT EXISTS guest_sessions (\r\n  id           TEXT PRIMARY KEY,                -- UUIDv7 (generated client-side)\r\n  group_id     TEXT NOT NULL REFERENCES order_groups(id),\r\n  table_id     TEXT NOT NULL REFERENCES tables(id),\r\n  branch_id    TEXT NOT NULL,\r\n  token        TEXT UNIQUE NOT NULL,            -- random 64-hex session token\r\n  guest_label  TEXT,                            -- 'Guest 1', 'Guest 2', …\r\n  status       TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','closed')),\r\n  created_at   TIMESTAMPTZ DEFAULT NOW(),\r\n  last_seen    TIMESTAMPTZ DEFAULT NOW()\r\n);\r\nCREATE INDEX IF NOT EXISTS idx_guest_sessions_token ON guest_sessions(token);\r\nCREATE INDEX IF NOT EXISTS idx_guest_sessions_group ON guest_sessions(group_id);\r\n\r\n-- 4. Atomic \"join the table's group\": returns the single active group + its\r\n--    single shared order, creating both on the first scan. The partial unique\r\n--    index on order_groups serialises concurrent first-scanners so the whole\r\n--    party always shares ONE group and ONE order (one bill to kitchen+cashier).\r\nCREATE OR REPLACE FUNCTION join_table_group(p_table_id text, p_branch_id text, p_table_number int)\r\nRETURNS TABLE(group_id text, order_id text)\r\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\nDECLARE\r\n  v_group_id text;\r\n  v_order_id text;\r\nBEGIN\r\n  SELECT og.id, og.order_id INTO v_group_id, v_order_id\r\n    FROM order_groups og\r\n    WHERE og.table_id = p_table_id AND og.status = 'active'\r\n    LIMIT 1;\r\n\r\n  IF v_group_id IS NULL THEN\r\n    v_order_id := 'order-' || (extract(epoch from clock_timestamp()) * 1000)::bigint;\r\n    v_group_id := gen_random_uuid()::text;\r\n    INSERT INTO orders(id, table_id, table_number, status, order_type, branch_id, waiters, subtotal, tax, total)\r\n      VALUES (v_order_id, p_table_id, COALESCE(p_table_number, 0), 'open', 'dine-in', p_branch_id, '[]'::jsonb, 0, 0, 0);\r\n    BEGIN\r\n      INSERT INTO order_groups(id, table_id, branch_id, order_id, status)\r\n        VALUES (v_group_id, p_table_id, p_branch_id, v_order_id, 'active');\r\n    EXCEPTION WHEN unique_violation THEN\r\n      DELETE FROM orders WHERE id = v_order_id;     -- lost the race — drop our order\r\n      SELECT og.id, og.order_id INTO v_group_id, v_order_id\r\n        FROM order_groups og WHERE og.table_id = p_table_id AND og.status = 'active' LIMIT 1;\r\n    END;\r\n    UPDATE tables SET status = 'occupied', current_order_id = v_order_id WHERE id = p_table_id;\r\n  ELSIF v_order_id IS NULL THEN\r\n    v_order_id := 'order-' || (extract(epoch from clock_timestamp()) * 1000)::bigint;\r\n    INSERT INTO orders(id, table_id, table_number, status, order_type, branch_id, waiters, subtotal, tax, total)\r\n      VALUES (v_order_id, p_table_id, COALESCE(p_table_number, 0), 'open', 'dine-in', p_branch_id, '[]'::jsonb, 0, 0, 0);\r\n    UPDATE order_groups SET order_id = v_order_id WHERE id = v_group_id;\r\n    UPDATE tables SET status = 'occupied', current_order_id = v_order_id WHERE id = p_table_id;\r\n  END IF;\r\n\r\n  group_id := v_group_id;\r\n  order_id := v_order_id;\r\n  RETURN NEXT;\r\nEND;\r\n$$;\r\n\r\nGRANT EXECUTE ON FUNCTION join_table_group(text, text, int) TO anon, authenticated;\r\n\r\nNOTIFY pgrst, 'reload schema';\r\n"},{"name":"0009_modifiers.sql","sql":"-- ============================================================\r\n-- 0009_modifiers.sql\r\n--\r\n-- Adds \"Modifier Groups\" — reusable sets of options (e.g. a \"Chicken\"\r\n-- group with \"Leg\" / \"Chest\") that are linked to products. When a linked\r\n-- product is ordered, its options are offered to the customer/staff; the\r\n-- chosen options (and any add-on price) attach to the order line.\r\n--\r\n--   modifier_groups          one row per group (name + single/multiple type)\r\n--   modifier_options         the options inside a group (name + add-on price)\r\n--   product_modifier_groups  many-to-many: which groups apply to which products\r\n--   order_items.modifiers    JSONB snapshot of the options chosen on a line\r\n--\r\n-- RLS is left open, consistent with the rest of the schema (see 0001).\r\n-- Run in the Supabase SQL Editor (or via `supabase db push`).\r\n-- ============================================================\r\n\r\n-- ─── modifier_groups ─────────────────────────────────────────\r\nCREATE TABLE IF NOT EXISTS modifier_groups (\r\n  id            TEXT PRIMARY KEY,\r\n  name          TEXT NOT NULL,\r\n  type          TEXT NOT NULL DEFAULT 'single'\r\n                  CHECK (type IN ('single','multiple')),\r\n  branch_id     TEXT NOT NULL,\r\n  is_active     BOOLEAN DEFAULT true,\r\n  created_at    TIMESTAMPTZ DEFAULT NOW()\r\n);\r\nCREATE INDEX IF NOT EXISTS idx_modifier_groups_branch ON modifier_groups(branch_id);\r\n\r\n-- ─── modifier_options ────────────────────────────────────────\r\nCREATE TABLE IF NOT EXISTS modifier_options (\r\n  id            TEXT PRIMARY KEY,\r\n  group_id      TEXT NOT NULL REFERENCES modifier_groups(id) ON DELETE CASCADE,\r\n  name          TEXT NOT NULL,\r\n  add_on_price  DECIMAL(10,2) NOT NULL DEFAULT 0,\r\n  is_default    BOOLEAN DEFAULT false,\r\n  display_order INTEGER DEFAULT 0,\r\n  created_at    TIMESTAMPTZ DEFAULT NOW()\r\n);\r\nCREATE INDEX IF NOT EXISTS idx_modifier_options_group ON modifier_options(group_id);\r\n\r\n-- ─── product_modifier_groups (link table) ────────────────────\r\nCREATE TABLE IF NOT EXISTS product_modifier_groups (\r\n  product_id    TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE,\r\n  group_id      TEXT NOT NULL REFERENCES modifier_groups(id) ON DELETE CASCADE,\r\n  display_order INTEGER DEFAULT 0,\r\n  PRIMARY KEY (product_id, group_id)\r\n);\r\nCREATE INDEX IF NOT EXISTS idx_pmg_product ON product_modifier_groups(product_id);\r\nCREATE INDEX IF NOT EXISTS idx_pmg_group   ON product_modifier_groups(group_id);\r\n\r\n-- ─── order_items.modifiers ───────────────────────────────────\r\n-- JSONB array snapshot, e.g.\r\n--   [{ \"groupId\":\"mg-1\",\"groupName\":\"Chicken\",\"optionId\":\"mo-1\",\r\n--      \"optionName\":\"Leg\",\"price\":2.00 }]\r\n-- A snapshot (not a FK) so historical orders stay correct even if a\r\n-- group/option is later edited or deleted. The line's `price` already\r\n-- includes the selected add-ons; this column is for display/breakdown.\r\nALTER TABLE order_items\r\n  ADD COLUMN IF NOT EXISTS modifiers JSONB DEFAULT '[]'::jsonb;\r\n\r\n-- Reload PostgREST schema cache so the new columns/tables are visible.\r\nNOTIFY pgrst, 'reload schema';\r\n"},{"name":"0010_product_images.sql","sql":"-- ============================================================\r\n-- 0010_product_images.sql\r\n--\r\n-- Adds a public Storage bucket for product (menu item) images.\r\n-- Staff upload one photo per product from Product Management; the\r\n-- returned public URL is stored in products.image (existing TEXT\r\n-- column) and rendered on the customer menu / ordering screens.\r\n--\r\n-- Mirrors the open-RLS posture of 0007 (pickup-receipts / merchant-qr):\r\n-- public read, open writes (tighten later if auth is added).\r\n-- ============================================================\r\n\r\n-- 1. Public bucket for product images.\r\nINSERT INTO storage.buckets (id, name, public)\r\n  VALUES ('product-images','product-images', true)\r\n  ON CONFLICT (id) DO NOTHING;\r\n\r\n-- 2. RLS policies: anyone may upload/replace/remove and read product images.\r\nDO $$\r\nBEGIN\r\n  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'product_images_insert') THEN\r\n    CREATE POLICY \"product_images_insert\" ON storage.objects\r\n      FOR INSERT TO anon, authenticated WITH CHECK (bucket_id = 'product-images');\r\n  END IF;\r\n  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'product_images_update') THEN\r\n    CREATE POLICY \"product_images_update\" ON storage.objects\r\n      FOR UPDATE TO anon, authenticated USING (bucket_id = 'product-images');\r\n  END IF;\r\n  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'product_images_delete') THEN\r\n    CREATE POLICY \"product_images_delete\" ON storage.objects\r\n      FOR DELETE TO anon, authenticated USING (bucket_id = 'product-images');\r\n  END IF;\r\n  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'product_images_read') THEN\r\n    CREATE POLICY \"product_images_read\" ON storage.objects\r\n      FOR SELECT TO anon, authenticated USING (bucket_id = 'product-images');\r\n  END IF;\r\nEND $$;\r\n\r\n-- Reload PostgREST schema cache.\r\nNOTIFY pgrst, 'reload schema';\r\n"},{"name":"0011_catalog_indexes.sql","sql":"-- ============================================================\r\n-- 0011_catalog_indexes.sql\r\n--\r\n-- Proactive performance: index the columns the menu queries filter on.\r\n-- Every catalog load (staff login + every public QR/pickup scan) runs:\r\n--   SELECT * FROM products   WHERE branch_id = ? AND is_active = true ORDER BY name\r\n--   SELECT * FROM categories WHERE branch_id = ?\r\n-- Without these indexes Postgres sequentially scans the whole table on each\r\n-- call. Cheap insurance so the menu stays fast as products and traffic grow.\r\n--\r\n-- Run in the Supabase SQL Editor (or `supabase db push`).\r\n-- ============================================================\r\n\r\nCREATE INDEX IF NOT EXISTS idx_products_branch_active\r\n  ON products(branch_id, is_active);\r\n\r\nCREATE INDEX IF NOT EXISTS idx_categories_branch\r\n  ON categories(branch_id);\r\n\r\nNOTIFY pgrst, 'reload schema';\r\n"},{"name":"0012_storage_hardening.sql","sql":"-- ============================================================\r\n-- 0012_storage_hardening.sql\r\n--\r\n-- Hardens the three public Storage buckets (product-images, merchant-qr,\r\n-- pickup-receipts) WITHOUT introducing auth (that is Phase 1). It:\r\n--   1. Enforces file TYPE + SIZE at the bucket level. The Storage API applies\r\n--      these server-side on every upload regardless of the client, so arbitrary\r\n--      / oversized / non-image (e.g. HTML/SVG/JS) uploads are rejected.\r\n--   2. Removes anon UPDATE/DELETE so existing objects (menu photos, the payment\r\n--      QR) can no longer be overwritten or deleted with the public anon key —\r\n--      closing the menu-defacement and payment-QR-overwrite (fraud) paths.\r\n--   3. Keeps anon INSERT + public SELECT, because the app currently writes as\r\n--      the anon role and the menu / receipts / QR must remain publicly readable.\r\n--      Phase 1 (Supabase Auth + RLS) will tighten INSERT to authenticated staff.\r\n--\r\n-- SAFE & REVERSIBLE: no object data is touched; limits only affect NEW uploads;\r\n-- dropped policies can be recreated. Idempotent (DROP IF EXISTS / UPDATE).\r\n--\r\n-- OPERATIONAL NOTE: after this runs, the payment QR can no longer be REPLACED\r\n-- from the app (overwrite is blocked). First-time upload still works; to replace\r\n-- an existing QR, remove the old object in the Supabase Storage dashboard first\r\n-- (an authenticated action). Phase 1 restores in-app replace for staff only.\r\n-- ============================================================\r\n\r\n-- 1. Server-enforced type + size limits per bucket.\r\nUPDATE storage.buckets\r\n  SET file_size_limit    = 5242880,  -- 5 MB\r\n      allowed_mime_types = ARRAY['image/png','image/jpeg','image/jpg','image/webp']\r\n  WHERE id IN ('product-images', 'merchant-qr');\r\n\r\nUPDATE storage.buckets\r\n  SET file_size_limit    = 15728640, -- 15 MB (receipts may be full-res phone photos or PDFs)\r\n      allowed_mime_types = ARRAY['image/png','image/jpeg','image/jpg','image/webp','application/pdf']\r\n  WHERE id = 'pickup-receipts';\r\n\r\n-- 2. product-images: no overwrite / delete of existing menu photos.\r\nDROP POLICY IF EXISTS \"product_images_update\" ON storage.objects;\r\nDROP POLICY IF EXISTS \"product_images_delete\" ON storage.objects;\r\n\r\n-- 3. merchant-qr: lock against overwrite / delete (close the payment-QR fraud path).\r\nDROP POLICY IF EXISTS \"merchant_qr_update\" ON storage.objects;\r\nDROP POLICY IF EXISTS \"merchant_qr_delete\" ON storage.objects;\r\n\r\n-- pickup-receipts already had only INSERT + SELECT for anon — nothing to drop.\r\n\r\nNOTIFY pgrst, 'reload schema';\r\n"},{"name":"0013_loyalty_rpcs.sql","sql":"-- ============================================================\r\n-- 0013_loyalty_rpcs.sql   (Phase 1 — server-authoritative loyalty)\r\n--\r\n-- Replaces the client-side read-modify-write loyalty logic (which double-awards\r\n-- on retry and can double-spend / go negative under concurrency) with atomic,\r\n-- transactional SECURITY DEFINER functions:\r\n--\r\n--   earn_loyalty_points   — adds points + accumulates spend/visits atomically,\r\n--                           idempotent per order (one 'earn' per order+customer).\r\n--   redeem_loyalty_points — guarded atomic deduction; returns FALSE if the\r\n--                           balance is insufficient (never goes negative).\r\n--   adjust_loyalty_points — manual +/- with a 0 floor; the ledger records the\r\n--                           ACTUAL applied delta so balance and ledger reconcile.\r\n--\r\n-- SAFE TO APPLY: additive only (creates functions; no table/RLS/data changes),\r\n-- so it cannot break login or the running app. It works today under the open-anon\r\n-- setup and remains correct once RLS is enabled later in Phase 1 (SECURITY\r\n-- DEFINER). EXECUTE is granted to anon now (the app is anon); Phase 1 RLS will\r\n-- narrow this to authenticated staff.\r\n--\r\n-- Reference schema: customers(id UUID, points_balance INT, total_spent NUMERIC,\r\n-- total_visits INT), loyalty_transactions(type IN earn|redeem|adjust,...).\r\n-- ============================================================\r\n\r\n-- ── Earn ─────────────────────────────────────────────────────\r\nCREATE OR REPLACE FUNCTION public.earn_loyalty_points(\r\n  p_customer_id UUID,\r\n  p_order_id    TEXT,\r\n  p_points      INT,\r\n  p_amount      NUMERIC,\r\n  p_branch_id   TEXT\r\n) RETURNS VOID\r\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\nBEGIN\r\n  IF p_points IS NULL OR p_points <= 0 THEN RETURN; END IF;\r\n\r\n  -- Idempotency: never award twice for the same order (guards the retry path).\r\n  IF EXISTS (\r\n    SELECT 1 FROM loyalty_transactions\r\n    WHERE order_id = p_order_id AND customer_id = p_customer_id AND type = 'earn'\r\n  ) THEN\r\n    RETURN;\r\n  END IF;\r\n\r\n  INSERT INTO loyalty_transactions (id, customer_id, order_id, type, points, description, branch_id)\r\n  VALUES (gen_random_uuid(), p_customer_id, p_order_id, 'earn', p_points,\r\n          'Earned ' || p_points || ' points on order', p_branch_id);\r\n\r\n  UPDATE customers\r\n    SET points_balance = points_balance + p_points,\r\n        total_spent    = total_spent + COALESCE(p_amount, 0),\r\n        total_visits   = total_visits + 1\r\n    WHERE id = p_customer_id;\r\nEND; $$;\r\n\r\n-- ── Redeem ───────────────────────────────────────────────────\r\nCREATE OR REPLACE FUNCTION public.redeem_loyalty_points(\r\n  p_customer_id UUID,\r\n  p_order_id    TEXT,\r\n  p_points      INT,\r\n  p_branch_id   TEXT\r\n) RETURNS BOOLEAN\r\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\nDECLARE v_updated INT;\r\nBEGIN\r\n  IF p_points IS NULL OR p_points <= 0 THEN RETURN FALSE; END IF;\r\n\r\n  -- Atomic guarded deduction: only succeeds if the balance is sufficient, so two\r\n  -- concurrent redemptions can never both pass or drive the balance negative.\r\n  UPDATE customers SET points_balance = points_balance - p_points\r\n    WHERE id = p_customer_id AND points_balance >= p_points;\r\n  GET DIAGNOSTICS v_updated = ROW_COUNT;\r\n  IF v_updated = 0 THEN RETURN FALSE; END IF;\r\n\r\n  INSERT INTO loyalty_transactions (id, customer_id, order_id, type, points, description, branch_id)\r\n  VALUES (gen_random_uuid(), p_customer_id, p_order_id, 'redeem', -p_points,\r\n          'Redeemed ' || p_points || ' points for discount', p_branch_id);\r\n  RETURN TRUE;\r\nEND; $$;\r\n\r\n-- ── Adjust (manual) ──────────────────────────────────────────\r\nCREATE OR REPLACE FUNCTION public.adjust_loyalty_points(\r\n  p_customer_id UUID,\r\n  p_points      INT,\r\n  p_description TEXT,\r\n  p_branch_id   TEXT\r\n) RETURNS INT\r\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\nDECLARE v_old INT; v_new INT; v_delta INT;\r\nBEGIN\r\n  SELECT points_balance INTO v_old FROM customers WHERE id = p_customer_id FOR UPDATE;\r\n  IF v_old IS NULL THEN RAISE EXCEPTION 'Customer % not found', p_customer_id; END IF;\r\n\r\n  v_new   := GREATEST(0, v_old + COALESCE(p_points, 0));\r\n  v_delta := v_new - v_old;  -- the ACTUAL applied change (ledger must match balance)\r\n\r\n  UPDATE customers SET points_balance = v_new WHERE id = p_customer_id;\r\n\r\n  INSERT INTO loyalty_transactions (id, customer_id, order_id, type, points, description, branch_id)\r\n  VALUES (gen_random_uuid(), p_customer_id, NULL, 'adjust', v_delta,\r\n          COALESCE(p_description, 'Manual adjustment'), p_branch_id);\r\n  RETURN v_new;\r\nEND; $$;\r\n\r\n-- Least privilege: no implicit PUBLIC execute; grant explicitly (narrow to\r\n-- authenticated once Supabase Auth + RLS land).\r\nREVOKE ALL ON FUNCTION public.earn_loyalty_points(UUID, TEXT, INT, NUMERIC, TEXT) FROM PUBLIC;\r\nREVOKE ALL ON FUNCTION public.redeem_loyalty_points(UUID, TEXT, INT, TEXT) FROM PUBLIC;\r\nREVOKE ALL ON FUNCTION public.adjust_loyalty_points(UUID, INT, TEXT, TEXT) FROM PUBLIC;\r\nGRANT EXECUTE ON FUNCTION public.earn_loyalty_points(UUID, TEXT, INT, NUMERIC, TEXT) TO anon, authenticated;\r\nGRANT EXECUTE ON FUNCTION public.redeem_loyalty_points(UUID, TEXT, INT, TEXT) TO anon, authenticated;\r\nGRANT EXECUTE ON FUNCTION public.adjust_loyalty_points(UUID, INT, TEXT, TEXT) TO anon, authenticated;\r\n\r\nNOTIFY pgrst, 'reload schema';\r\n"},{"name":"0014_table_ordering_toggle.sql","sql":"-- ============================================================\r\n-- 0014_table_ordering_toggle.sql\r\n--\r\n-- Lets a waiter explicitly turn customer self-ordering (QR / group QR) on or\r\n-- off per table, instead of it always being available the moment a table QR\r\n-- is scanned. Workflow: waiter seats a party -> turns ordering ON for that\r\n-- table -> customers can order from their phones. The moment the table's\r\n-- bill is paid, the app flips this back to OFF automatically (see\r\n-- TablesView.handlePaid), so the next party can't order until a waiter\r\n-- allows it again.\r\n--\r\n-- Defaults to false so existing tables require an explicit opt-in from\r\n-- staff before self-ordering starts working after this migration lands.\r\n-- ============================================================\r\n\r\nALTER TABLE tables\r\n  ADD COLUMN IF NOT EXISTS ordering_enabled BOOLEAN NOT NULL DEFAULT false;\r\n\r\nNOTIFY pgrst, 'reload schema';\r\n"},{"name":"0015_void_order_items.sql","sql":"-- ============================================================\r\n-- 0015_void_order_items.sql\r\n--\r\n-- Lets an authorized staff member void a single item that's already been\r\n-- sent to the kitchen (e.g. the guest changed their mind, or it was a\r\n-- mis-order). The kitchen needs to see it was cancelled, not just have it\r\n-- silently vanish, and the cancellation needs an audit trail (who / when /\r\n-- why) since it removes money from an otherwise-already-fired ticket.\r\n-- ============================================================\r\n\r\nALTER TABLE order_items DROP CONSTRAINT IF EXISTS order_items_status_check;\r\nALTER TABLE order_items ADD CONSTRAINT order_items_status_check\r\n  CHECK (status IN ('pending','preparing','ready','served','cancelled'));\r\n\r\nALTER TABLE order_items\r\n  ADD COLUMN IF NOT EXISTS cancelled_by      TEXT,\r\n  ADD COLUMN IF NOT EXISTS cancelled_by_name TEXT,\r\n  ADD COLUMN IF NOT EXISTS cancel_reason      TEXT,\r\n  ADD COLUMN IF NOT EXISTS cancelled_at        TIMESTAMPTZ;\r\n\r\nNOTIFY pgrst, 'reload schema';\r\n"},{"name":"0016_product_sales_report.sql","sql":"-- ============================================================\r\n-- 0016_product_sales_report.sql\r\n--\r\n-- Per-product sales aggregation for the Reports screen (\"how many times did\r\n-- I sell this specific product, and how much revenue did it bring in\").\r\n-- Aggregated server-side rather than pulled row-by-row into the browser —\r\n-- cheap to add now, avoids redoing this once order history grows.\r\n--\r\n-- Cancelled items (see 0015) are excluded: a voided item was never actually\r\n-- sold, so it shouldn't count toward units or revenue.\r\n-- ============================================================\r\n\r\nCREATE OR REPLACE FUNCTION public.get_product_sales(\r\n  p_branch_id TEXT,\r\n  p_date_from TIMESTAMPTZ,\r\n  p_date_to   TIMESTAMPTZ\r\n) RETURNS TABLE (\r\n  product_id   TEXT,\r\n  product_name TEXT,\r\n  units_sold   BIGINT,\r\n  revenue      NUMERIC\r\n)\r\nLANGUAGE sql SECURITY DEFINER SET search_path = public AS $$\r\n  SELECT\r\n    oi.product_id,\r\n    oi.product_name,\r\n    SUM(oi.quantity)::BIGINT AS units_sold,\r\n    SUM(oi.subtotal)::NUMERIC AS revenue\r\n  FROM order_items oi\r\n  JOIN orders o ON o.id = oi.order_id\r\n  WHERE o.branch_id = p_branch_id\r\n    AND o.status = 'completed'\r\n    AND o.created_at >= p_date_from\r\n    AND o.created_at <  p_date_to\r\n    AND oi.status IS DISTINCT FROM 'cancelled'\r\n  GROUP BY oi.product_id, oi.product_name\r\n  ORDER BY units_sold DESC;\r\n$$;\r\n\r\nREVOKE ALL ON FUNCTION public.get_product_sales(TEXT, TIMESTAMPTZ, TIMESTAMPTZ) FROM PUBLIC;\r\nGRANT EXECUTE ON FUNCTION public.get_product_sales(TEXT, TIMESTAMPTZ, TIMESTAMPTZ) TO anon, authenticated;\r\n\r\nNOTIFY pgrst, 'reload schema';\r\n"},{"name":"0017_split_payments.sql","sql":"-- ============================================================\r\n-- 0017_split_payments.sql\r\n--\r\n-- Lets a table's bill be paid off by item instead of only as one whole-order\r\n-- payment (\"everyone pays for what they ate\"). A single order can now be\r\n-- settled across several calls to pay_order_items, each covering a subset of\r\n-- its items; the order only flips to completed once every (non-cancelled)\r\n-- item has been paid.\r\n--\r\n-- pay_order_items() is written server-side-first rather than client-trusted:\r\n-- it re-reads the named items' prices from the DB itself (never trusts a\r\n-- client-computed subtotal) and is the audit trail of record for every\r\n-- partial settlement via order_payments.\r\n-- ============================================================\r\n\r\nALTER TABLE order_items\r\n  ADD COLUMN IF NOT EXISTS paid       BOOLEAN NOT NULL DEFAULT false,\r\n  ADD COLUMN IF NOT EXISTS paid_at    TIMESTAMPTZ,\r\n  ADD COLUMN IF NOT EXISTS payment_id TEXT;\r\n\r\nCREATE TABLE IF NOT EXISTS order_payments (\r\n  id           TEXT PRIMARY KEY,\r\n  order_id     TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,\r\n  amount       DECIMAL(10,2) NOT NULL,\r\n  method       TEXT NOT NULL,\r\n  item_ids     JSONB NOT NULL DEFAULT '[]'::jsonb,\r\n  cashier_id   TEXT,\r\n  cashier_name TEXT,\r\n  branch_id    TEXT NOT NULL,\r\n  created_at   TIMESTAMPTZ DEFAULT NOW()\r\n);\r\nCREATE INDEX IF NOT EXISTS idx_order_payments_order ON order_payments(order_id);\r\n\r\nCREATE OR REPLACE FUNCTION public.pay_order_items(\r\n  p_order_id         TEXT,\r\n  p_item_ids         TEXT[],\r\n  p_method           TEXT,\r\n  p_amount_received  NUMERIC,\r\n  p_cashier_id       TEXT,\r\n  p_cashier_name     TEXT,\r\n  p_branch_id        TEXT\r\n) RETURNS TABLE (payment_id TEXT, amount NUMERIC, order_completed BOOLEAN, bill_number TEXT)\r\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\nDECLARE\r\n  v_order       orders%ROWTYPE;\r\n  v_amount      NUMERIC;\r\n  v_matched     INT;\r\n  v_remaining   INT;\r\n  v_payment_id  TEXT;\r\n  v_next_num    INT;\r\n  v_bill_number TEXT := NULL;\r\n  v_group_id    TEXT;\r\nBEGIN\r\n  -- Row-lock the order so two cashiers can't settle overlapping items, or\r\n  -- both trigger the \"last split closes the order\" branch, at the same time.\r\n  SELECT * INTO v_order FROM orders WHERE id = p_order_id AND branch_id = p_branch_id FOR UPDATE;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Order not found';\r\n  END IF;\r\n  IF v_order.status <> 'open' THEN\r\n    RAISE EXCEPTION 'This bill has already been paid';\r\n  END IF;\r\n  IF p_item_ids IS NULL OR array_length(p_item_ids, 1) IS NULL THEN\r\n    RAISE EXCEPTION 'No items selected';\r\n  END IF;\r\n\r\n  -- Sum the DB's own price for exactly the requested items — never trust a\r\n  -- client-computed total. Only matches items that are still unpaid and not\r\n  -- voided; a mismatch below means the selection is stale.\r\n  SELECT COALESCE(SUM(subtotal), 0), COUNT(*)\r\n    INTO v_amount, v_matched\r\n    FROM order_items\r\n    WHERE order_id = p_order_id AND id = ANY(p_item_ids)\r\n      AND paid = false AND status IS DISTINCT FROM 'cancelled';\r\n\r\n  IF v_matched <> array_length(p_item_ids, 1) THEN\r\n    RAISE EXCEPTION 'One or more selected items are no longer available to pay (already paid, voided, or not on this order)';\r\n  END IF;\r\n  IF v_amount <= 0 THEN\r\n    RAISE EXCEPTION 'Nothing to pay';\r\n  END IF;\r\n  IF p_method = 'cash' AND p_amount_received IS NOT NULL AND p_amount_received < v_amount THEN\r\n    RAISE EXCEPTION 'Amount received is less than the amount due';\r\n  END IF;\r\n\r\n  v_payment_id := 'opay-' || substr(md5(random()::text || clock_timestamp()::text), 1, 20);\r\n\r\n  UPDATE order_items\r\n    SET paid = true, paid_at = NOW(), payment_id = v_payment_id\r\n    WHERE order_id = p_order_id AND id = ANY(p_item_ids);\r\n\r\n  INSERT INTO order_payments (id, order_id, amount, method, item_ids, cashier_id, cashier_name, branch_id)\r\n    VALUES (v_payment_id, p_order_id, v_amount, p_method, to_jsonb(p_item_ids), p_cashier_id, p_cashier_name, p_branch_id);\r\n\r\n  SELECT COUNT(*) INTO v_remaining\r\n    FROM order_items\r\n    WHERE order_id = p_order_id AND paid = false AND status IS DISTINCT FROM 'cancelled';\r\n\r\n  IF v_remaining = 0 THEN\r\n    -- Last split settles the bill. Dine-in orders don't get a bill number\r\n    -- until payment (same as the existing whole-order path) — assign one now\r\n    -- if this order doesn't already have one.\r\n    IF v_order.bill_number IS NULL THEN\r\n      SELECT COALESCE(MAX(bill_number::int), 0) + 1 INTO v_next_num\r\n        FROM orders WHERE branch_id = p_branch_id AND order_type = v_order.order_type AND bill_number IS NOT NULL;\r\n      v_bill_number := lpad(v_next_num::text, 4, '0');\r\n    ELSE\r\n      v_bill_number := v_order.bill_number;\r\n    END IF;\r\n\r\n    UPDATE orders\r\n      SET status = 'completed', completed_at = NOW(), payment_status = 'paid',\r\n          payment_method = 'split', bill_number = v_bill_number\r\n      WHERE id = p_order_id;\r\n\r\n    -- Free the table and close out QR/group ordering exactly like a normal\r\n    -- whole-order payment does (see PaymentModal.handlePayment / TablesView).\r\n    IF v_order.table_id IS NOT NULL THEN\r\n      UPDATE tables SET status = 'available', current_order_id = NULL, ordering_enabled = false\r\n        WHERE id = v_order.table_id;\r\n\r\n      SELECT id INTO v_group_id FROM order_groups WHERE table_id = v_order.table_id AND status = 'active';\r\n      IF v_group_id IS NOT NULL THEN\r\n        UPDATE guest_sessions SET status = 'closed' WHERE group_id = v_group_id;\r\n        UPDATE order_groups SET status = 'closed', closed_at = NOW() WHERE id = v_group_id;\r\n      END IF;\r\n      UPDATE qr_sessions SET active = false, last_activity_at = NOW() WHERE table_id = v_order.table_id;\r\n    END IF;\r\n  END IF;\r\n\r\n  RETURN QUERY SELECT v_payment_id, v_amount, (v_remaining = 0), v_bill_number;\r\nEND;\r\n$$;\r\n\r\nREVOKE ALL ON FUNCTION public.pay_order_items(TEXT, TEXT[], TEXT, NUMERIC, TEXT, TEXT, TEXT) FROM PUBLIC;\r\nGRANT EXECUTE ON FUNCTION public.pay_order_items(TEXT, TEXT[], TEXT, NUMERIC, TEXT, TEXT, TEXT) TO anon, authenticated;\r\n\r\nNOTIFY pgrst, 'reload schema';\r\n"},{"name":"0018_organizations_branches.sql","sql":"-- ============================================================\r\n-- 0018_organizations_branches.sql   (Feature 1A — tenant foundation)\r\n--\r\n-- Turns the loose, unvalidated `branch_id` TEXT column (repeated on every\r\n-- table with no registry behind it) into a real, owned entity so the system\r\n-- can serve many restaurant customers (\"tenants\") from one deployment\r\n-- instead of copying the whole project per client.\r\n--\r\n--   organizations  — a tenant (the customer being sold to). Owns >=1 branch.\r\n--   branches       — the billable unit (one restaurant location). Its `id` IS\r\n--                    the value that every existing table's `branch_id` already\r\n--                    points at, so nothing else has to change to adopt it.\r\n--\r\n-- Only the super-admin (Feature 1B) ever creates a branch — a tenant never\r\n-- self-serves one, because a branch is the thing being sold.\r\n--\r\n-- This migration is ADDITIVE and SAFE: it adds two tables and backfills them\r\n-- from the branch_id values already in use. It does NOT enable RLS, drop\r\n-- anything, or change how the running app reads/writes — the app keeps working\r\n-- unchanged. RLS-based isolation is a later, separate step (Feature 1D), which\r\n-- must not be applied until staff login is migrated to real Supabase Auth\r\n-- sessions (see SECURITY.md — enabling RLS before that = total outage).\r\n-- ============================================================\r\n\r\n-- ─── organizations ───────────────────────────────────────────\r\nCREATE TABLE IF NOT EXISTS organizations (\r\n  id          TEXT PRIMARY KEY,\r\n  name        TEXT NOT NULL,\r\n  owner_name  TEXT,\r\n  owner_email TEXT,\r\n  owner_phone TEXT,\r\n  status      TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','suspended')),\r\n  created_at  TIMESTAMPTZ DEFAULT NOW()\r\n);\r\n\r\n-- ─── branches ────────────────────────────────────────────────\r\n-- `enabled_features` is a JSONB map of module -> bool. Absent/true means the\r\n-- module is visible for that branch; false hides it (Feature 1C). Keys match\r\n-- the confirmed module list.\r\nCREATE TABLE IF NOT EXISTS branches (\r\n  id               TEXT PRIMARY KEY,          -- == branch_id used across all tables\r\n  org_id           TEXT NOT NULL REFERENCES organizations(id),\r\n  name             TEXT NOT NULL,\r\n  contract_start   DATE,\r\n  contract_end     DATE,\r\n  status           TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','suspended','expired')),\r\n  enabled_features JSONB NOT NULL DEFAULT jsonb_build_object(\r\n                     'loyalty', true, 'workforce', true, 'biometrics', true,\r\n                     'invoices', true, 'pickup', true, 'groupOrdering', true,\r\n                     'reports', true, 'accounting', true\r\n                   ),\r\n  created_at       TIMESTAMPTZ DEFAULT NOW()\r\n);\r\nCREATE INDEX IF NOT EXISTS idx_branches_org ON branches(org_id);\r\nCREATE INDEX IF NOT EXISTS idx_branches_contract_end ON branches(contract_end);\r\n\r\n-- ─── Backfill from existing data ─────────────────────────────\r\n-- Create a single default organization to own everything that already exists,\r\n-- then one branch row per DISTINCT branch_id actually in use across the core\r\n-- tables — so the current restaurant keeps running with a real registry entry\r\n-- and nothing points at a branch that doesn't exist. Idempotent.\r\nINSERT INTO organizations (id, name, status)\r\n  SELECT 'org-default', 'Alnawras Restaurant Group', 'active'\r\n  WHERE NOT EXISTS (SELECT 1 FROM organizations WHERE id = 'org-default');\r\n\r\nINSERT INTO branches (id, org_id, name, status, contract_start)\r\n  SELECT bid, 'org-default', 'Main Branch', 'active', CURRENT_DATE\r\n  FROM (\r\n    SELECT branch_id AS bid FROM users     WHERE branch_id IS NOT NULL\r\n    UNION SELECT branch_id FROM products    WHERE branch_id IS NOT NULL\r\n    UNION SELECT branch_id FROM tables      WHERE branch_id IS NOT NULL\r\n    UNION SELECT branch_id FROM orders      WHERE branch_id IS NOT NULL\r\n  ) d\r\n  WHERE bid IS NOT NULL\r\n    AND NOT EXISTS (SELECT 1 FROM branches b WHERE b.id = d.bid);\r\n\r\n-- Safety net: if the tables above are all empty (fresh environment), still\r\n-- guarantee the default 'branch-1' the app falls back to exists.\r\nINSERT INTO branches (id, org_id, name, status, contract_start)\r\n  SELECT 'branch-1', 'org-default', 'Main Branch', 'active', CURRENT_DATE\r\n  WHERE NOT EXISTS (SELECT 1 FROM branches);\r\n\r\nNOTIFY pgrst, 'reload schema';\r\n"},{"name":"0019_super_admin.sql","sql":"-- ============================================================\r\n-- 0019_super_admin.sql   (Feature 1B — super-admin identity)\r\n--\r\n-- The super-admin (the person selling the system to restaurants) is NOT a\r\n-- staff role in the PIN-based `users` table. They get their own real Supabase\r\n-- Auth login (email + password), because the super-admin panel must keep\r\n-- working even when a tenant's branch is locked out — it's the tool used to\r\n-- renew/suspend that very branch.\r\n--\r\n-- `super_admins` maps a Supabase Auth user id to super-admin rights. A given\r\n-- authenticated session is a super-admin IFF it has a row here. Small number\r\n-- of accounts, so full Supabase Auth here is cheap and stays on the free plan\r\n-- (Auth is included, up to 50k MAU).\r\n--\r\n-- Additive & safe: adds one table + two read helpers. Nothing existing changes.\r\n-- ============================================================\r\n\r\nCREATE TABLE IF NOT EXISTS super_admins (\r\n  auth_uid   TEXT PRIMARY KEY,   -- auth.users.id (UUID as text)\r\n  email      TEXT,\r\n  name       TEXT,\r\n  created_at TIMESTAMPTZ DEFAULT NOW()\r\n);\r\n\r\n-- Is the CURRENT authenticated caller a super-admin? SECURITY DEFINER so the\r\n-- client can call it right after signing in to decide whether to show the\r\n-- panel, without needing direct read access to the table.\r\nCREATE OR REPLACE FUNCTION public.is_current_user_super_admin()\r\nRETURNS BOOLEAN\r\nLANGUAGE sql SECURITY DEFINER SET search_path = public AS $$\r\n  SELECT EXISTS (SELECT 1 FROM super_admins WHERE auth_uid = auth.uid()::text);\r\n$$;\r\n\r\nREVOKE ALL ON FUNCTION public.is_current_user_super_admin() FROM PUBLIC;\r\nGRANT EXECUTE ON FUNCTION public.is_current_user_super_admin() TO anon, authenticated;\r\n\r\n-- ─── PROVISIONING THE FIRST SUPER-ADMIN (manual, one time) ───\r\n-- 1. In the Supabase dashboard: Authentication -> Users -> Add user, create the\r\n--    super-admin's email + password (confirm the email).\r\n-- 2. Copy that user's UID, then run (replacing the placeholders):\r\n--       INSERT INTO super_admins (auth_uid, email, name)\r\n--       VALUES ('<auth-user-uid>', 'you@example.com', 'Owner');\r\n-- After that, signing into the app's /superadmin login with those credentials\r\n-- unlocks the tenant-management panel.\r\n\r\nNOTIFY pgrst, 'reload schema';\r\n"},{"name":"0020_branch_settings_tax_discounts.sql","sql":"-- ============================================================\r\n-- 0020_branch_settings_tax_discounts.sql\r\n--\r\n-- Per-branch business settings the TENANT's own admin (role='admin') controls\r\n-- — currently: tax and quick-discount presets. These must be consistent across\r\n-- every device at a branch (a waiter tablet and the cashier can't disagree on\r\n-- the tax rate), so they live in the DB per branch, not in per-device\r\n-- localStorage like the older settings.\r\n--\r\n--   tax_enabled / tax_rate / tax_label / tax_inclusive\r\n--       tax_rate is a percentage (e.g. 6 = 6%). tax_inclusive=false adds tax on\r\n--       top of the subtotal (a visible tax line); tax_inclusive=true means menu\r\n--       prices already include tax (backed out for the receipt breakdown).\r\n--   discount_presets  JSONB array of one-tap discounts the cashier can apply,\r\n--       e.g. [{\"id\":\"d1\",\"label\":\"Student\",\"type\":\"percentage\",\"value\":10}].\r\n--\r\n-- Also updates pay_order_items (from 0017) so a split-by-item bill charges the\r\n-- same tax as a whole-order bill — otherwise splitting would dodge tax.\r\n--\r\n-- Additive & safe. Run AFTER 0017 and 0018.\r\n-- ============================================================\r\n\r\nCREATE TABLE IF NOT EXISTS branch_settings (\r\n  branch_id        TEXT PRIMARY KEY,\r\n  tax_enabled      BOOLEAN NOT NULL DEFAULT false,\r\n  tax_rate         NUMERIC NOT NULL DEFAULT 0,       -- percent\r\n  tax_label        TEXT NOT NULL DEFAULT 'Tax',\r\n  tax_inclusive    BOOLEAN NOT NULL DEFAULT false,\r\n  discount_presets JSONB NOT NULL DEFAULT '[]'::jsonb,\r\n  updated_at       TIMESTAMPTZ DEFAULT NOW()\r\n);\r\n\r\n-- ── Tax-aware split payment ──────────────────────────────────\r\n-- Re-declare pay_order_items so the per-item amount includes the branch's\r\n-- exclusive tax (inclusive tax is already in the item price, so it isn't\r\n-- added again). Everything else matches 0017.\r\nCREATE OR REPLACE FUNCTION public.pay_order_items(\r\n  p_order_id         TEXT,\r\n  p_item_ids         TEXT[],\r\n  p_method           TEXT,\r\n  p_amount_received  NUMERIC,\r\n  p_cashier_id       TEXT,\r\n  p_cashier_name     TEXT,\r\n  p_branch_id        TEXT\r\n) RETURNS TABLE (payment_id TEXT, amount NUMERIC, order_completed BOOLEAN, bill_number TEXT)\r\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\nDECLARE\r\n  v_order       orders%ROWTYPE;\r\n  v_amount      NUMERIC;\r\n  v_matched     INT;\r\n  v_remaining   INT;\r\n  v_payment_id  TEXT;\r\n  v_next_num    INT;\r\n  v_bill_number TEXT := NULL;\r\n  v_group_id    TEXT;\r\n  v_tax_enabled BOOLEAN := false;\r\n  v_tax_rate    NUMERIC := 0;\r\n  v_tax_incl    BOOLEAN := false;\r\n  v_full_sub    NUMERIC := 0;\r\n  v_full_tax    NUMERIC := 0;\r\nBEGIN\r\n  SELECT * INTO v_order FROM orders WHERE id = p_order_id AND branch_id = p_branch_id FOR UPDATE;\r\n  IF NOT FOUND THEN RAISE EXCEPTION 'Order not found'; END IF;\r\n  IF v_order.status <> 'open' THEN RAISE EXCEPTION 'This bill has already been paid'; END IF;\r\n  IF p_item_ids IS NULL OR array_length(p_item_ids, 1) IS NULL THEN RAISE EXCEPTION 'No items selected'; END IF;\r\n\r\n  SELECT COALESCE(SUM(subtotal), 0), COUNT(*)\r\n    INTO v_amount, v_matched\r\n    FROM order_items\r\n    WHERE order_id = p_order_id AND id = ANY(p_item_ids)\r\n      AND paid = false AND status IS DISTINCT FROM 'cancelled';\r\n\r\n  IF v_matched <> array_length(p_item_ids, 1) THEN\r\n    RAISE EXCEPTION 'One or more selected items are no longer available to pay (already paid, voided, or not on this order)';\r\n  END IF;\r\n  IF v_amount <= 0 THEN RAISE EXCEPTION 'Nothing to pay'; END IF;\r\n\r\n  -- Add this branch's exclusive tax so a split share matches a whole-order bill.\r\n  SELECT tax_enabled, tax_rate, tax_inclusive INTO v_tax_enabled, v_tax_rate, v_tax_incl\r\n    FROM branch_settings WHERE branch_id = p_branch_id;\r\n  IF v_tax_enabled AND v_tax_rate > 0 AND NOT v_tax_incl THEN\r\n    v_amount := round(v_amount * (1 + v_tax_rate / 100), 2);\r\n  END IF;\r\n\r\n  IF p_method = 'cash' AND p_amount_received IS NOT NULL AND p_amount_received < v_amount THEN\r\n    RAISE EXCEPTION 'Amount received is less than the amount due';\r\n  END IF;\r\n\r\n  v_payment_id := 'opay-' || substr(md5(random()::text || clock_timestamp()::text), 1, 20);\r\n\r\n  UPDATE order_items SET paid = true, paid_at = NOW(), payment_id = v_payment_id\r\n    WHERE order_id = p_order_id AND id = ANY(p_item_ids);\r\n\r\n  INSERT INTO order_payments (id, order_id, amount, method, item_ids, cashier_id, cashier_name, branch_id)\r\n    VALUES (v_payment_id, p_order_id, v_amount, p_method, to_jsonb(p_item_ids), p_cashier_id, p_cashier_name, p_branch_id);\r\n\r\n  SELECT COUNT(*) INTO v_remaining\r\n    FROM order_items WHERE order_id = p_order_id AND paid = false AND status IS DISTINCT FROM 'cancelled';\r\n\r\n  IF v_remaining = 0 THEN\r\n    IF v_order.bill_number IS NULL THEN\r\n      SELECT COALESCE(MAX(bill_number::int), 0) + 1 INTO v_next_num\r\n        FROM orders WHERE branch_id = p_branch_id AND order_type = v_order.order_type AND bill_number IS NOT NULL;\r\n      v_bill_number := lpad(v_next_num::text, 4, '0');\r\n    ELSE\r\n      v_bill_number := v_order.bill_number;\r\n    END IF;\r\n\r\n    -- Persist the final money breakdown so reports/receipts include split tax.\r\n    SELECT COALESCE(SUM(subtotal), 0) INTO v_full_sub\r\n      FROM order_items WHERE order_id = p_order_id AND status IS DISTINCT FROM 'cancelled';\r\n    IF v_tax_enabled AND v_tax_rate > 0 THEN\r\n      v_full_tax := CASE WHEN v_tax_incl\r\n        THEN round(v_full_sub - v_full_sub / (1 + v_tax_rate / 100), 2)\r\n        ELSE round(v_full_sub * v_tax_rate / 100, 2) END;\r\n    END IF;\r\n\r\n    UPDATE orders\r\n      SET status = 'completed', completed_at = NOW(), payment_status = 'paid',\r\n          payment_method = 'split', bill_number = v_bill_number,\r\n          subtotal = v_full_sub, tax = v_full_tax,\r\n          total = CASE WHEN v_tax_incl THEN v_full_sub ELSE v_full_sub + v_full_tax END\r\n      WHERE id = p_order_id;\r\n\r\n    IF v_order.table_id IS NOT NULL THEN\r\n      UPDATE tables SET status = 'available', current_order_id = NULL, ordering_enabled = false\r\n        WHERE id = v_order.table_id;\r\n      SELECT id INTO v_group_id FROM order_groups WHERE table_id = v_order.table_id AND status = 'active';\r\n      IF v_group_id IS NOT NULL THEN\r\n        UPDATE guest_sessions SET status = 'closed' WHERE group_id = v_group_id;\r\n        UPDATE order_groups SET status = 'closed', closed_at = NOW() WHERE id = v_group_id;\r\n      END IF;\r\n      UPDATE qr_sessions SET active = false, last_activity_at = NOW() WHERE table_id = v_order.table_id;\r\n    END IF;\r\n  END IF;\r\n\r\n  RETURN QUERY SELECT v_payment_id, v_amount, (v_remaining = 0), v_bill_number;\r\nEND;\r\n$$;\r\n\r\nREVOKE ALL ON FUNCTION public.pay_order_items(TEXT, TEXT[], TEXT, NUMERIC, TEXT, TEXT, TEXT) FROM PUBLIC;\r\nGRANT EXECUTE ON FUNCTION public.pay_order_items(TEXT, TEXT[], TEXT, NUMERIC, TEXT, TEXT, TEXT) TO anon, authenticated;\r\n\r\nNOTIFY pgrst, 'reload schema';\r\n"},{"name":"0021_order_payment_integrity.sql","sql":"-- ============================================================\r\n-- 0021_order_payment_integrity.sql   (Batch 1 — audit fixes H4/H5/M2)\r\n--\r\n-- Three related correctness fixes for the order/table/payment path:\r\n--\r\n--   H5  next_bill_number()  — bill numbers from an atomic per-(branch,type)\r\n--       counter instead of MAX(bill_number)+1, which raced (two checkouts could\r\n--       read the same MAX and mint duplicate numbers). Seeded from existing data.\r\n--   H4  move_order_to_table() — moving an open order to another table becomes one\r\n--       locked transaction (was four unsequenced client writes with a\r\n--       target-table race). Derives the source table from the order, so a wrong\r\n--       from-table argument can't free the wrong table.\r\n--   M2  pay_order_items()   — on completion the order's total is set to what was\r\n--       ACTUALLY collected (sum of order_payments), so a split-paid bill always\r\n--       reconciles with its payment rows instead of drifting a cent from\r\n--       independently-rounded per-split tax. Also switched to next_bill_number.\r\n--\r\n-- Additive & safe. Run AFTER 0020.\r\n-- ============================================================\r\n\r\n-- ── H5: atomic bill-number counter ───────────────────────────\r\nCREATE TABLE IF NOT EXISTS bill_counters (\r\n  branch_id   TEXT NOT NULL,\r\n  order_type  TEXT NOT NULL,\r\n  last_number INT  NOT NULL DEFAULT 0,\r\n  PRIMARY KEY (branch_id, order_type)\r\n);\r\n\r\n-- Seed from the highest numeric bill number already issued per branch+type so\r\n-- the counter continues the sequence instead of colliding with existing bills.\r\nINSERT INTO bill_counters (branch_id, order_type, last_number)\r\n  SELECT branch_id, COALESCE(order_type, 'dine-in'), MAX(bill_number::int)\r\n  FROM orders\r\n  WHERE bill_number IS NOT NULL AND bill_number ~ '^\\d+$'\r\n  GROUP BY branch_id, COALESCE(order_type, 'dine-in')\r\nON CONFLICT (branch_id, order_type)\r\n  DO UPDATE SET last_number = GREATEST(bill_counters.last_number, EXCLUDED.last_number);\r\n\r\nCREATE OR REPLACE FUNCTION public.next_bill_number(p_branch_id TEXT, p_order_type TEXT)\r\nRETURNS TEXT\r\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\nDECLARE v_num INT;\r\nBEGIN\r\n  -- Atomic increment: the row is locked for the duration of the upsert, so two\r\n  -- concurrent callers can never receive the same number.\r\n  INSERT INTO bill_counters (branch_id, order_type, last_number)\r\n    VALUES (p_branch_id, COALESCE(p_order_type, 'dine-in'), 1)\r\n  ON CONFLICT (branch_id, order_type)\r\n    DO UPDATE SET last_number = bill_counters.last_number + 1\r\n  RETURNING last_number INTO v_num;\r\n  RETURN lpad(v_num::text, 4, '0');\r\nEND; $$;\r\n\r\nREVOKE ALL ON FUNCTION public.next_bill_number(TEXT, TEXT) FROM PUBLIC;\r\nGRANT EXECUTE ON FUNCTION public.next_bill_number(TEXT, TEXT) TO anon, authenticated;\r\n\r\n-- OPTIONAL hardening (run manually AFTER confirming no existing duplicates):\r\n--   SELECT branch_id, order_type, bill_number, COUNT(*)\r\n--     FROM orders WHERE bill_number IS NOT NULL\r\n--     GROUP BY 1,2,3 HAVING COUNT(*) > 1;\r\n--   -- if that returns 0 rows:\r\n--   CREATE UNIQUE INDEX idx_orders_bill_unique\r\n--     ON orders(branch_id, order_type, bill_number) WHERE bill_number IS NOT NULL;\r\n\r\n-- ── H4: atomic table move ────────────────────────────────────\r\nCREATE OR REPLACE FUNCTION public.move_order_to_table(\r\n  p_order_id    TEXT,\r\n  p_to_table_id TEXT,\r\n  p_branch_id   TEXT\r\n) RETURNS TABLE(from_table_id TEXT, to_table_number INT)\r\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\nDECLARE\r\n  v_order  orders%ROWTYPE;\r\n  v_to     tables%ROWTYPE;\r\n  v_from   TEXT;\r\n  v_group  TEXT;\r\nBEGIN\r\n  -- Lock the target table first and verify it's free — serialises two staff\r\n  -- moving different orders onto the same table at once.\r\n  SELECT * INTO v_to FROM tables WHERE id = p_to_table_id AND branch_id = p_branch_id FOR UPDATE;\r\n  IF NOT FOUND THEN RAISE EXCEPTION 'Target table not found'; END IF;\r\n  IF v_to.status <> 'available' THEN RAISE EXCEPTION 'Target table is not available'; END IF;\r\n\r\n  SELECT * INTO v_order FROM orders WHERE id = p_order_id AND branch_id = p_branch_id FOR UPDATE;\r\n  IF NOT FOUND THEN RAISE EXCEPTION 'Order not found'; END IF;\r\n  IF v_order.status <> 'open' THEN RAISE EXCEPTION 'Only an open order can be moved'; END IF;\r\n\r\n  v_from := v_order.table_id;  -- the real source, not a caller-supplied one\r\n  IF v_from = p_to_table_id THEN RAISE EXCEPTION 'Order is already at that table'; END IF;\r\n\r\n  UPDATE orders SET table_id = p_to_table_id, table_number = v_to.number WHERE id = p_order_id;\r\n  UPDATE tables SET status = 'occupied', current_order_id = p_order_id WHERE id = p_to_table_id;\r\n\r\n  IF v_from IS NOT NULL THEN\r\n    UPDATE tables SET status = 'available', current_order_id = NULL\r\n      WHERE id = v_from AND branch_id = p_branch_id;\r\n    -- Move any active group-ordering session with the order.\r\n    SELECT id INTO v_group FROM order_groups WHERE table_id = v_from AND status = 'active';\r\n    IF v_group IS NOT NULL THEN\r\n      UPDATE order_groups   SET table_id = p_to_table_id WHERE id = v_group;\r\n      UPDATE guest_sessions SET table_id = p_to_table_id WHERE group_id = v_group AND status = 'active';\r\n    END IF;\r\n  END IF;\r\n\r\n  from_table_id := v_from;\r\n  to_table_number := v_to.number;\r\n  RETURN NEXT;\r\nEND; $$;\r\n\r\nREVOKE ALL ON FUNCTION public.move_order_to_table(TEXT, TEXT, TEXT) FROM PUBLIC;\r\nGRANT EXECUTE ON FUNCTION public.move_order_to_table(TEXT, TEXT, TEXT) TO anon, authenticated;\r\n\r\n-- ── H5 + M2: pay_order_items uses next_bill_number and reconciles totals ──\r\nCREATE OR REPLACE FUNCTION public.pay_order_items(\r\n  p_order_id         TEXT,\r\n  p_item_ids         TEXT[],\r\n  p_method           TEXT,\r\n  p_amount_received  NUMERIC,\r\n  p_cashier_id       TEXT,\r\n  p_cashier_name     TEXT,\r\n  p_branch_id        TEXT\r\n) RETURNS TABLE (payment_id TEXT, amount NUMERIC, order_completed BOOLEAN, bill_number TEXT)\r\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\nDECLARE\r\n  v_order       orders%ROWTYPE;\r\n  v_amount      NUMERIC;\r\n  v_matched     INT;\r\n  v_remaining   INT;\r\n  v_payment_id  TEXT;\r\n  v_bill_number TEXT := NULL;\r\n  v_group_id    TEXT;\r\n  v_tax_enabled BOOLEAN := false;\r\n  v_tax_rate    NUMERIC := 0;\r\n  v_tax_incl    BOOLEAN := false;\r\n  v_full_sub    NUMERIC := 0;\r\n  v_collected   NUMERIC := 0;\r\n  v_pretax      NUMERIC := 0;\r\nBEGIN\r\n  SELECT * INTO v_order FROM orders WHERE id = p_order_id AND branch_id = p_branch_id FOR UPDATE;\r\n  IF NOT FOUND THEN RAISE EXCEPTION 'Order not found'; END IF;\r\n  IF v_order.status <> 'open' THEN RAISE EXCEPTION 'This bill has already been paid'; END IF;\r\n  IF p_item_ids IS NULL OR array_length(p_item_ids, 1) IS NULL THEN RAISE EXCEPTION 'No items selected'; END IF;\r\n\r\n  SELECT COALESCE(SUM(subtotal), 0), COUNT(*)\r\n    INTO v_amount, v_matched\r\n    FROM order_items\r\n    WHERE order_id = p_order_id AND id = ANY(p_item_ids)\r\n      AND paid = false AND status IS DISTINCT FROM 'cancelled';\r\n\r\n  IF v_matched <> array_length(p_item_ids, 1) THEN\r\n    RAISE EXCEPTION 'One or more selected items are no longer available to pay (already paid, voided, or not on this order)';\r\n  END IF;\r\n  IF v_amount <= 0 THEN RAISE EXCEPTION 'Nothing to pay'; END IF;\r\n\r\n  SELECT tax_enabled, tax_rate, tax_inclusive INTO v_tax_enabled, v_tax_rate, v_tax_incl\r\n    FROM branch_settings WHERE branch_id = p_branch_id;\r\n  IF v_tax_enabled AND v_tax_rate > 0 AND NOT v_tax_incl THEN\r\n    v_amount := round(v_amount * (1 + v_tax_rate / 100), 2);\r\n  END IF;\r\n\r\n  IF p_method = 'cash' AND p_amount_received IS NOT NULL AND p_amount_received < v_amount THEN\r\n    RAISE EXCEPTION 'Amount received is less than the amount due';\r\n  END IF;\r\n\r\n  v_payment_id := 'opay-' || substr(md5(random()::text || clock_timestamp()::text), 1, 20);\r\n\r\n  UPDATE order_items SET paid = true, paid_at = NOW(), payment_id = v_payment_id\r\n    WHERE order_id = p_order_id AND id = ANY(p_item_ids);\r\n\r\n  INSERT INTO order_payments (id, order_id, amount, method, item_ids, cashier_id, cashier_name, branch_id)\r\n    VALUES (v_payment_id, p_order_id, v_amount, p_method, to_jsonb(p_item_ids), p_cashier_id, p_cashier_name, p_branch_id);\r\n\r\n  SELECT COUNT(*) INTO v_remaining\r\n    FROM order_items WHERE order_id = p_order_id AND paid = false AND status IS DISTINCT FROM 'cancelled';\r\n\r\n  IF v_remaining = 0 THEN\r\n    IF v_order.bill_number IS NULL THEN\r\n      v_bill_number := public.next_bill_number(p_branch_id, v_order.order_type);\r\n    ELSE\r\n      v_bill_number := v_order.bill_number;\r\n    END IF;\r\n\r\n    -- M2: the order total is exactly what was collected across all splits, so\r\n    -- it always reconciles with order_payments (no per-split rounding drift).\r\n    SELECT COALESCE(SUM(amount), 0)   INTO v_collected FROM order_payments WHERE order_id = p_order_id;\r\n    SELECT COALESCE(SUM(subtotal), 0) INTO v_full_sub  FROM order_items\r\n      WHERE order_id = p_order_id AND status IS DISTINCT FROM 'cancelled';\r\n\r\n    IF v_tax_enabled AND v_tax_rate > 0 AND v_tax_incl THEN\r\n      v_pretax := round(v_collected / (1 + v_tax_rate / 100), 2);\r\n      UPDATE orders SET status='completed', completed_at=NOW(), payment_status='paid',\r\n        payment_method='split', bill_number=v_bill_number,\r\n        subtotal=v_pretax, tax=(v_collected - v_pretax), total=v_collected\r\n        WHERE id = p_order_id;\r\n    ELSE\r\n      UPDATE orders SET status='completed', completed_at=NOW(), payment_status='paid',\r\n        payment_method='split', bill_number=v_bill_number,\r\n        subtotal=v_full_sub, tax=round(v_collected - v_full_sub, 2), total=v_collected\r\n        WHERE id = p_order_id;\r\n    END IF;\r\n\r\n    IF v_order.table_id IS NOT NULL THEN\r\n      UPDATE tables SET status='available', current_order_id=NULL, ordering_enabled=false\r\n        WHERE id = v_order.table_id;\r\n      SELECT id INTO v_group_id FROM order_groups WHERE table_id = v_order.table_id AND status = 'active';\r\n      IF v_group_id IS NOT NULL THEN\r\n        UPDATE guest_sessions SET status='closed' WHERE group_id = v_group_id;\r\n        UPDATE order_groups   SET status='closed', closed_at=NOW() WHERE id = v_group_id;\r\n      END IF;\r\n      UPDATE qr_sessions SET active=false, last_activity_at=NOW() WHERE table_id = v_order.table_id;\r\n    END IF;\r\n  END IF;\r\n\r\n  RETURN QUERY SELECT v_payment_id, v_amount, (v_remaining = 0), v_bill_number;\r\nEND; $$;\r\n\r\nREVOKE ALL ON FUNCTION public.pay_order_items(TEXT, TEXT[], TEXT, NUMERIC, TEXT, TEXT, TEXT) FROM PUBLIC;\r\nGRANT EXECUTE ON FUNCTION public.pay_order_items(TEXT, TEXT[], TEXT, NUMERIC, TEXT, TEXT, TEXT) TO anon, authenticated;\r\n\r\nNOTIFY pgrst, 'reload schema';\r\n"},{"name":"0022_server_side_pricing.sql","sql":"-- ============================================================\r\n-- 0022_server_side_pricing.sql   (Batch 2 — audit fix CR-5 / C4)\r\n--\r\n-- Moves ORDER-ITEM PRICING off the client. Until now order_items were inserted\r\n-- with whatever `price` the browser sent, and the order total was the sum of\r\n-- those client numbers — so a customer on the public QR/pickup page could post\r\n-- an item at price 0.01 (or negative) straight through PostgREST. This closes\r\n-- that: submit_order_items() looks every line's price up from `products`, every\r\n-- modifier add-on up from `modifier_options`, rebuilds the modifier snapshot\r\n-- from the DB, inserts the items with those authoritative values, and rewrites\r\n-- the order subtotal/total itself. The client's price is never trusted.\r\n--\r\n-- Tax stays 0 on an OPEN order (it is finalised at the till in the payment\r\n-- flow, unchanged) — this function only governs item prices + subtotal.\r\n--\r\n-- Input p_items: [{ \"product_id\": \"...\", \"quantity\": 2, \"notes\": \"...\",\r\n--                    \"option_ids\": [\"mo-1\",\"mo-2\"] }, ...]\r\n--\r\n-- Additive & safe. Run AFTER 0017 (needs order_items.paid) and 0009 (modifiers).\r\n-- ============================================================\r\n\r\nCREATE OR REPLACE FUNCTION public.submit_order_items(\r\n  p_order_id      TEXT,\r\n  p_branch_id     TEXT,\r\n  p_added_by      TEXT,\r\n  p_added_by_name TEXT,\r\n  p_items         JSONB\r\n) RETURNS TABLE (\r\n  id TEXT, product_id TEXT, product_name TEXT, quantity INT,\r\n  price NUMERIC, subtotal NUMERIC, station TEXT, status TEXT,\r\n  notes TEXT, modifiers JSONB, added_by_name TEXT\r\n)\r\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\nDECLARE\r\n  v_order   orders%ROWTYPE;\r\n  v_item    JSONB;\r\n  v_pid     TEXT;\r\n  v_qty     INT;\r\n  v_notes   TEXT;\r\n  v_opts    TEXT[];\r\n  v_base    NUMERIC;\r\n  v_pname   TEXT;\r\n  v_station TEXT;\r\n  v_addons  NUMERIC;\r\n  v_mods    JSONB;\r\n  v_price   NUMERIC;\r\n  v_sub     NUMERIC;\r\n  v_new_id  TEXT;\r\n  v_subtotal NUMERIC;\r\nBEGIN\r\n  SELECT * INTO v_order FROM orders WHERE id = p_order_id AND branch_id = p_branch_id FOR UPDATE;\r\n  IF NOT FOUND THEN RAISE EXCEPTION 'Order not found'; END IF;\r\n  IF v_order.status <> 'open' THEN RAISE EXCEPTION 'Cannot add items to a bill that is not open'; END IF;\r\n  IF p_items IS NULL OR jsonb_array_length(p_items) = 0 THEN RAISE EXCEPTION 'No items to add'; END IF;\r\n\r\n  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP\r\n    v_pid   := v_item->>'product_id';\r\n    v_qty   := GREATEST(1, COALESCE((v_item->>'quantity')::int, 1));\r\n    v_notes := NULLIF(v_item->>'notes', '');\r\n\r\n    SELECT COALESCE(array_agg(val), '{}') INTO v_opts\r\n      FROM jsonb_array_elements_text(COALESCE(v_item->'option_ids', '[]'::jsonb)) AS t(val);\r\n\r\n    -- Authoritative product price / name / station (active products only).\r\n    SELECT price, name, COALESCE(NULLIF(station, ''), 'kitchen')\r\n      INTO v_base, v_pname, v_station\r\n      FROM products WHERE id = v_pid AND branch_id = p_branch_id AND is_active = true;\r\n    IF NOT FOUND THEN RAISE EXCEPTION 'Product % is not available', v_pid; END IF;\r\n\r\n    -- Authoritative modifier add-ons + snapshot. Unknown option ids simply\r\n    -- contribute nothing (never trusted from the client).\r\n    v_addons := 0;\r\n    v_mods   := '[]'::jsonb;\r\n    IF array_length(v_opts, 1) IS NOT NULL THEN\r\n      SELECT COALESCE(SUM(mo.add_on_price), 0),\r\n             COALESCE(jsonb_agg(jsonb_build_object(\r\n               'groupId', mo.group_id, 'groupName', mg.name,\r\n               'optionId', mo.id, 'optionName', mo.name, 'price', mo.add_on_price)), '[]'::jsonb)\r\n        INTO v_addons, v_mods\r\n        FROM modifier_options mo\r\n        JOIN modifier_groups mg ON mg.id = mo.group_id\r\n        WHERE mo.id = ANY(v_opts);\r\n    END IF;\r\n\r\n    v_price  := v_base + v_addons;\r\n    v_sub    := v_price * v_qty;\r\n    v_new_id := 'item-' || substr(md5(random()::text || clock_timestamp()::text), 1, 16);\r\n\r\n    INSERT INTO order_items(\r\n      id, order_id, product_id, product_name, quantity, price, subtotal,\r\n      notes, modifiers, status, added_by, added_by_name, station, branch_id, paid)\r\n    VALUES (\r\n      v_new_id, p_order_id, v_pid, v_pname, v_qty, v_price, v_sub,\r\n      v_notes, v_mods, 'pending', p_added_by, p_added_by_name, v_station, p_branch_id, false);\r\n\r\n    RETURN QUERY SELECT v_new_id, v_pid, v_pname, v_qty, v_price, v_sub,\r\n                        v_station, 'pending'::text, v_notes, v_mods, p_added_by_name;\r\n  END LOOP;\r\n\r\n  -- Rewrite the order subtotal/total from the server-priced items. Tax stays 0\r\n  -- on the open order (applied at payment), matching existing behaviour.\r\n  SELECT COALESCE(SUM(subtotal), 0) INTO v_subtotal\r\n    FROM order_items WHERE order_id = p_order_id AND status IS DISTINCT FROM 'cancelled';\r\n  UPDATE orders SET subtotal = v_subtotal, tax = 0, total = v_subtotal WHERE id = p_order_id;\r\nEND; $$;\r\n\r\nREVOKE ALL ON FUNCTION public.submit_order_items(TEXT, TEXT, TEXT, TEXT, JSONB) FROM PUBLIC;\r\nGRANT EXECUTE ON FUNCTION public.submit_order_items(TEXT, TEXT, TEXT, TEXT, JSONB) TO anon, authenticated;\r\n\r\nNOTIFY pgrst, 'reload schema';\r\n"},{"name":"0023_branch_loyalty_settings.sql","sql":"-- ============================================================\r\n-- 0023_branch_loyalty_settings.sql   (Batch 5 — audit M6, partial)\r\n--\r\n-- Moves the loyalty program settings (enabled, points-per-currency, redemption\r\n-- rate, minimum redemption, label) off per-device localStorage and into the\r\n-- per-branch `branch_settings` row, alongside tax + discounts. Same reason as\r\n-- tax: a waiter tablet and the cashier must not disagree on how many points a\r\n-- purchase earns. Loyalty MATH is unchanged — only where the 5 settings live.\r\n--\r\n-- Additive & safe. Run AFTER 0020 (which created branch_settings).\r\n-- ============================================================\r\n\r\nALTER TABLE branch_settings\r\n  ADD COLUMN IF NOT EXISTS loyalty JSONB NOT NULL DEFAULT jsonb_build_object(\r\n    'enabled', true,\r\n    'pointsPerDollar', 1,\r\n    'redemptionRate', 100,\r\n    'minimumRedemption', 100,\r\n    'pointsLabel', 'Points'\r\n  );\r\n\r\nNOTIFY pgrst, 'reload schema';\r\n"},{"name":"0024_branch_device_logins.sql","sql":"-- ============================================================\r\n-- 0024_branch_device_logins.sql   (Device / terminal login — front half of 1D)\r\n--\r\n-- A device (cashier tablet / browser) signs in ONCE with a branch email+password\r\n-- Supabase Auth account; staff then PIN in on top of that session. The device\r\n-- stays bound to the branch account until an admin signs it out. This table maps\r\n-- an Auth user -> the branch it operates. Mirrors `super_admins` (0019).\r\n--\r\n-- SAFE + DORMANT BY DESIGN: with ZERO rows here, device_login_required() returns\r\n-- false and the app skips the whole email+password gate — behaviour is exactly\r\n-- as today (PIN only). The gate turns on the moment the first row is inserted,\r\n-- and turns back off if the rows are deleted. No lockout risk from deploying.\r\n--\r\n-- RLS stays OFF. This only establishes a real authenticated session now; the\r\n-- database-level tenant isolation (RLS keyed on the branch) is the later 1D step.\r\n-- ============================================================\r\n\r\nCREATE TABLE IF NOT EXISTS branch_logins (\r\n  auth_uid   TEXT PRIMARY KEY,      -- auth.users.id (UUID as text)\r\n  branch_id  TEXT NOT NULL,         -- which branch this device account runs\r\n  email      TEXT,\r\n  label      TEXT,                  -- optional human note: \"Front cashier\", \"Bar tablet\"\r\n  created_at TIMESTAMPTZ DEFAULT NOW()\r\n);\r\n\r\n-- Is the device-login gate active at all? True once >=1 device account exists.\r\n-- Callable by anon so the app can decide whether to show the email+password\r\n-- screen BEFORE anyone signs in. Fail-safe: no rows -> false -> gate dormant.\r\nCREATE OR REPLACE FUNCTION public.device_login_required()\r\nRETURNS BOOLEAN\r\nLANGUAGE sql SECURITY DEFINER SET search_path = public AS $$\r\n  SELECT EXISTS (SELECT 1 FROM branch_logins);\r\n$$;\r\n\r\n-- Which branch does the CURRENTLY signed-in device account operate? Returns NULL\r\n-- if the current session isn't a registered device login (e.g. no session, or a\r\n-- super-admin session), which the app treats as \"device not unlocked\".\r\nCREATE OR REPLACE FUNCTION public.current_device_branch()\r\nRETURNS TEXT\r\nLANGUAGE sql SECURITY DEFINER SET search_path = public AS $$\r\n  SELECT branch_id FROM branch_logins WHERE auth_uid = auth.uid()::text;\r\n$$;\r\n\r\nREVOKE ALL ON FUNCTION public.device_login_required() FROM PUBLIC;\r\nREVOKE ALL ON FUNCTION public.current_device_branch() FROM PUBLIC;\r\nGRANT EXECUTE ON FUNCTION public.device_login_required() TO anon, authenticated;\r\nGRANT EXECUTE ON FUNCTION public.current_device_branch() TO anon, authenticated;\r\n\r\n-- ─── PROVISIONING A BRANCH DEVICE LOGIN (manual, one time per branch) ───\r\n-- 1. Supabase dashboard: Authentication -> Users -> Add user. Set the branch's\r\n--    email + password, tick \"Auto Confirm User\".\r\n-- 2. Copy that user's UID; get the branch id:  SELECT id, name FROM branches;\r\n-- 3. Run (replace the placeholders):\r\n--       INSERT INTO branch_logins (auth_uid, branch_id, email, label)\r\n--       VALUES ('<auth-user-uid>', '<branch-id>', 'branch@example.com', 'Main');\r\n-- The moment the first row exists, every device is asked for the email+password\r\n-- once, then stays signed in until an admin signs the device out.\r\n--\r\n-- To DISABLE the gate again (revert to PIN-only, no lockout):  DELETE FROM branch_logins;\r\n\r\nNOTIFY pgrst, 'reload schema';\r\n"},{"name":"0025_tenant_invites.sql","sql":"-- ============================================================\r\n-- 0025_tenant_invites.sql   (Tenant onboarding — set-password links)\r\n--\r\n-- When the super-admin adds a tenant, the admin-invite-tenant Edge Function\r\n-- creates the org + branch + a login account + a branch_logins mapping, and\r\n-- drops a single-use token here. The emailed link points at /#/set-password?\r\n-- token=..., and the set-tenant-password Edge Function validates the token and\r\n-- sets the account's password.\r\n--\r\n-- Only the Edge Functions (service role) ever touch this table. RLS is turned ON\r\n-- with NO policies so the tokens are NOT readable through the public anon key\r\n-- (service role bypasses RLS). The app never selects from this table directly,\r\n-- so enabling RLS here is safe and does not affect anything else.\r\n-- ============================================================\r\n\r\nCREATE TABLE IF NOT EXISTS tenant_invites (\r\n  token       TEXT PRIMARY KEY,\r\n  auth_uid    TEXT NOT NULL,\r\n  email       TEXT,\r\n  branch_id   TEXT,\r\n  expires_at  TIMESTAMPTZ NOT NULL,\r\n  used_at     TIMESTAMPTZ,\r\n  created_at  TIMESTAMPTZ DEFAULT NOW()\r\n);\r\n\r\nALTER TABLE tenant_invites ENABLE ROW LEVEL SECURITY;\r\n-- No policies on purpose: anon/authenticated get nothing; the service-role key\r\n-- used by the Edge Functions bypasses RLS.\r\n\r\nNOTIFY pgrst, 'reload schema';\r\n"},{"name":"0026_employee_performance.sql","sql":"-- ============================================================\r\n-- 0026_employee_performance.sql   (AI-assisted performance observations)\r\n--\r\n-- EXTENDS the existing HR system. It does NOT create a second employee store:\r\n-- every observation points at an EXISTING row in `employees` through the same\r\n-- business key the rest of HR uses (`employees.employee_id`, e.g. \"EMP-007\") —\r\n-- exactly like attendance_logs.employee_id and payroll_summary.employee_id.\r\n--\r\n-- What is NOT stored here (it is computed live from existing tables instead,\r\n-- so there is no duplicated data to drift):\r\n--   * attendance / punctuality   → attendance_logs (unchanged)\r\n--   * orders handled / tables    → order_items.added_by → employees.user_id\r\n--   * payments processed         → order_payments.cashier_id → employees.user_id\r\n--\r\n-- What IS stored here: discrete events that have no existing home —\r\n--   * AI CCTV observations (service response, table attendance, table\r\n--     cleaning turnaround), which ALWAYS arrive as 'pending' manager review;\r\n--   * customer complaints / compliments logged by a manager;\r\n--   * manager evaluations.\r\n--\r\n-- Guarantees enforced IN THE DATABASE (not just the UI), by trigger/CHECK:\r\n--   1. An observation can only name an employee that exists in `employees`\r\n--      AND belongs to the same branch. Unknown/foreign ids are rejected.\r\n--      AI events with no reliable identification stay unattributed (NULL).\r\n--   2. AI CCTV observations are forced to review_status='pending' on insert,\r\n--      whatever the caller sends — they never count until a human verifies.\r\n--   3. AI observations must carry evidence (camera/clip reference etc.), and\r\n--      evidence is immutable after insert (audit integrity).\r\n--   4. A manager correcting the employee keeps the AI's original attribution\r\n--      in original_employee_id (audit trail).\r\n--   5. Verified/corrected rows must name an employee and a reviewer.\r\n--\r\n-- Nothing in this table is read by payroll (HRController.computePayroll) —\r\n-- observations are advisory and never drive salary or disciplinary action.\r\n--\r\n-- Safety: purely additive. No existing table, column, constraint or row is\r\n-- touched. No FK to employees on purpose: employees.employee_id's UNIQUE\r\n-- constraint is \"[type inferred]\" in 0001 and unverified on prod, and an FK\r\n-- would fail to create without it — the trigger enforces existence instead.\r\n-- RLS: left OFF to match every other app table until Phase 1D (see TODO_1D.md);\r\n-- the app's anon-key PIN sessions would otherwise be locked out.\r\n--\r\n-- Reversible: see the ROLLBACK block at the bottom.\r\n-- ============================================================\r\n\r\nCREATE TABLE IF NOT EXISTS employee_performance_observations (\r\n  id                   TEXT PRIMARY KEY,\r\n  employee_id          TEXT,                 -- employees.employee_id; NULL = unattributed\r\n  original_employee_id TEXT,                 -- AI's attribution before a manager correction\r\n  branch_id            TEXT NOT NULL,\r\n  source               TEXT NOT NULL CHECK (source IN ('ai_cctv','manager','customer')),\r\n  category             TEXT NOT NULL CHECK (category IN (\r\n                         'service_response',     -- seconds from guest signal to staff arrival\r\n                         'table_attendance',     -- a table visit / check-back\r\n                         'table_cleaning',       -- minutes from guest leaving to table reset\r\n                         'customer_complaint',\r\n                         'customer_compliment',\r\n                         'manager_evaluation',   -- metric_value = rating 1..5\r\n                         'other')),\r\n  observed_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),\r\n  metric_value         NUMERIC,\r\n  metric_unit          TEXT CHECK (metric_unit IS NULL OR metric_unit IN ('seconds','minutes','rating','count')),\r\n  summary              TEXT NOT NULL,\r\n  evidence             JSONB,                -- e.g. {\"camera_id\":\"cam-3\",\"clip_ref\":\"...\",\"table_id\":\"t-4\"}\r\n  confidence           NUMERIC CHECK (confidence IS NULL OR (confidence >= 0 AND confidence <= 1)),\r\n  review_status        TEXT NOT NULL DEFAULT 'pending'\r\n                         CHECK (review_status IN ('pending','verified','corrected','dismissed')),\r\n  reviewed_by          TEXT,                 -- users.id of the reviewing manager/HR\r\n  reviewed_at          TIMESTAMPTZ,\r\n  review_note          TEXT,\r\n  created_by           TEXT,                 -- users.id, or the integration name for AI\r\n  created_at           TIMESTAMPTZ DEFAULT NOW(),\r\n\r\n  CONSTRAINT epo_ai_requires_evidence CHECK (\r\n    source <> 'ai_cctv' OR (evidence IS NOT NULL AND evidence <> '{}'::jsonb)),\r\n  CONSTRAINT epo_reviewed_requires_reviewer CHECK (\r\n    review_status = 'pending' OR reviewed_by IS NOT NULL),\r\n  CONSTRAINT epo_counted_requires_employee CHECK (\r\n    review_status NOT IN ('verified','corrected') OR employee_id IS NOT NULL),\r\n  CONSTRAINT epo_rating_range CHECK (\r\n    category <> 'manager_evaluation' OR (metric_value BETWEEN 1 AND 5))\r\n);\r\n\r\nCREATE INDEX IF NOT EXISTS idx_epo_employee_time ON employee_performance_observations(employee_id, observed_at);\r\nCREATE INDEX IF NOT EXISTS idx_epo_branch_status ON employee_performance_observations(branch_id, review_status);\r\nCREATE INDEX IF NOT EXISTS idx_epo_branch_time   ON employee_performance_observations(branch_id, observed_at);\r\n\r\nCREATE OR REPLACE FUNCTION public.epo_validate()\r\nRETURNS trigger\r\nLANGUAGE plpgsql\r\nAS $$\r\nBEGIN\r\n  -- (1) Employee must exist in the existing HR table, in the same branch.\r\n  IF NEW.employee_id IS NOT NULL AND NOT EXISTS (\r\n       SELECT 1 FROM employees e\r\n        WHERE e.employee_id = NEW.employee_id\r\n          AND e.branch_id   = NEW.branch_id) THEN\r\n    RAISE EXCEPTION 'employee % does not exist in branch %', NEW.employee_id, NEW.branch_id\r\n      USING ERRCODE = 'foreign_key_violation';\r\n  END IF;\r\n\r\n  IF TG_OP = 'INSERT' THEN\r\n    -- (2) AI observations always start in the manager review queue.\r\n    IF NEW.source = 'ai_cctv' THEN\r\n      NEW.review_status        := 'pending';\r\n      NEW.reviewed_by          := NULL;\r\n      NEW.reviewed_at          := NULL;\r\n      NEW.original_employee_id := NULL;\r\n    END IF;\r\n    RETURN NEW;\r\n  END IF;\r\n\r\n  -- UPDATE\r\n  -- (3) Evidence and provenance are immutable.\r\n  IF NEW.evidence IS DISTINCT FROM OLD.evidence\r\n     OR NEW.source IS DISTINCT FROM OLD.source\r\n     OR NEW.branch_id IS DISTINCT FROM OLD.branch_id THEN\r\n    RAISE EXCEPTION 'evidence, source and branch of an observation cannot be changed';\r\n  END IF;\r\n\r\n  -- (4) Keep the original attribution the first time a reviewer changes it.\r\n  IF NEW.employee_id IS DISTINCT FROM OLD.employee_id AND OLD.original_employee_id IS NULL THEN\r\n    NEW.original_employee_id := COALESCE(OLD.employee_id, '(unattributed)');\r\n  ELSE\r\n    NEW.original_employee_id := OLD.original_employee_id;\r\n  END IF;\r\n\r\n  IF NEW.review_status <> OLD.review_status AND NEW.review_status <> 'pending' THEN\r\n    NEW.reviewed_at := COALESCE(NEW.reviewed_at, NOW());\r\n  END IF;\r\n  RETURN NEW;\r\nEND;\r\n$$;\r\n\r\nDROP TRIGGER IF EXISTS trg_epo_validate ON employee_performance_observations;\r\nCREATE TRIGGER trg_epo_validate\r\n  BEFORE INSERT OR UPDATE ON employee_performance_observations\r\n  FOR EACH ROW EXECUTE FUNCTION public.epo_validate();\r\n\r\nNOTIFY pgrst, 'reload schema';\r\n\r\n-- ============================================================\r\n-- ROLLBACK (run manually to fully reverse this migration).\r\n-- Safe: nothing else references this table, and no existing HR data\r\n-- (employees, attendance_logs, payroll_summary, leave_requests) is affected.\r\n--\r\n--   DROP TRIGGER  IF EXISTS trg_epo_validate ON employee_performance_observations;\r\n--   DROP FUNCTION IF EXISTS public.epo_validate();\r\n--   DROP TABLE    IF EXISTS employee_performance_observations;\r\n--   NOTIFY pgrst, 'reload schema';\r\n-- ============================================================\r\n"},{"name":"0027_shifts_and_attendance_hours.sql","sql":"-- ============================================================\n-- 0027_shifts_and_attendance_hours.sql   (audit AUD-16 — schema drift)\n--\n-- Two things the application already reads/writes but that no migration ever\n-- created. Confirmed missing on production (PostgREST 404 / 400):\n--\n--   shifts                       — ShiftController (open / end shift). Without\n--                                  it, Shift Management errors on every action.\n--   attendance_logs.total_hours  — HRController.recordScan writes it on\n--                                  clock-out. Without it, every clock-out fails.\n--\n-- Additive & safe: creates one new table and one nullable column. No existing\n-- row is touched. Idempotent. RLS is left OFF to match the other app tables\n-- until the Auth + RLS cutover (the app would otherwise be locked out).\n--\n-- Run AFTER 0026.\n-- ============================================================\n\nCREATE TABLE IF NOT EXISTS shifts (\n  id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),  -- the app inserts without an id\n  user_id      TEXT NOT NULL,\n  user_name    TEXT,\n  branch_id    TEXT NOT NULL,\n  opened_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  closed_at    TIMESTAMPTZ,\n  opening_cash DECIMAL(10,2) NOT NULL DEFAULT 0,\n  closing_cash DECIMAL(10,2),\n  total_sales  DECIMAL(10,2),\n  status       TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','closed'))\n);\nCREATE INDEX IF NOT EXISTS idx_shifts_branch ON shifts(branch_id, opened_at);\n\n-- One open shift per person per branch. getCurrentShift() expects at most one\n-- row; a double-tap on \"Open shift\" would otherwise create two and break it.\nCREATE UNIQUE INDEX IF NOT EXISTS idx_shifts_one_open\n  ON shifts(user_id, branch_id) WHERE status = 'open';\n\nALTER TABLE attendance_logs\n  ADD COLUMN IF NOT EXISTS total_hours NUMERIC(6,2);\n\nNOTIFY pgrst, 'reload schema';\n\n-- ============================================================\n-- ROLLBACK (manual). Only safe while `shifts` holds nothing you need.\n--\n--   DROP TABLE IF EXISTS shifts;\n--   ALTER TABLE attendance_logs DROP COLUMN IF EXISTS total_hours;\n--   NOTIFY pgrst, 'reload schema';\n-- ============================================================\n"},{"name":"0028_lock_control_plane.sql","sql":"-- ============================================================\n-- 0028_lock_control_plane.sql   (audit AUD-02 — privilege escalation)\n--\n-- The four tables that decide WHO IS WHO were as open as every other table:\n--\n--   super_admins   — a row here makes an account a super-admin\n--   branch_logins  — a row here makes an account a branch's website admin\n--   organizations  — tenants\n--   branches       — contract dates, suspension, enabled (paid) modules\n--\n-- With the public key anyone could insert themselves into the first two, or\n-- extend their own contract in the last. This turns Row-Level Security on for\n-- just these four tables. It is deliberately NOT the full Auth + RLS cutover:\n-- nothing the staff app does day to day touches these tables directly, so this\n-- can ship on its own without locking anyone out.\n--\n-- What still works, and why:\n--   * is_current_user_super_admin(), device_login_required(),\n--     current_device_branch()          — SECURITY DEFINER, run as the table\n--                                        owner, unaffected by RLS.\n--   * admin-invite-tenant / set-tenant-password Edge Functions\n--                                      — service role, bypasses RLS.\n--   * Super-admin panel (list / create / suspend / edit)\n--                                      — signed-in super-admin passes the\n--                                        policies below.\n--   * BranchController.getAccess (staff login + customer pages)\n--                                      — `branches` stays readable.\n--\n-- Safe & reversible: no data is changed. Idempotent. Run AFTER 0024.\n-- ============================================================\n\n-- ── super_admins / branch_logins: no direct access at all ────\n-- No policies on purpose. Everything legitimate goes through the SECURITY\n-- DEFINER functions or the service role. The REVOKE is belt and braces so a\n-- future \"temporarily disable RLS\" does not silently reopen them.\nALTER TABLE super_admins  ENABLE ROW LEVEL SECURITY;\nALTER TABLE branch_logins ENABLE ROW LEVEL SECURITY;\nREVOKE ALL ON super_admins, branch_logins FROM anon, authenticated;\n\n-- ── organizations: super-admin only ──────────────────────────\nALTER TABLE organizations ENABLE ROW LEVEL SECURITY;\n\nDROP POLICY IF EXISTS organizations_super_admin ON organizations;\nCREATE POLICY organizations_super_admin ON organizations\n  FOR ALL TO authenticated\n  USING      ((SELECT public.is_current_user_super_admin()))\n  WITH CHECK ((SELECT public.is_current_user_super_admin()));\n\n-- ── branches: everyone may read, only a super-admin may write ─\n-- Read stays open because the app checks a branch's contract/suspension before\n-- anyone is signed in (PIN screen, customer QR and pickup pages). Narrowing the\n-- read to \"your own branch\" is part of the full cutover.\nALTER TABLE branches ENABLE ROW LEVEL SECURITY;\n\nDROP POLICY IF EXISTS branches_read ON branches;\nCREATE POLICY branches_read ON branches\n  FOR SELECT TO anon, authenticated\n  USING (true);\n\nDROP POLICY IF EXISTS branches_super_admin_write ON branches;\nCREATE POLICY branches_super_admin_write ON branches\n  FOR ALL TO authenticated\n  USING      ((SELECT public.is_current_user_super_admin()))\n  WITH CHECK ((SELECT public.is_current_user_super_admin()));\n\nNOTIFY pgrst, 'reload schema';\n\n-- ============================================================\n-- VERIFY (run after applying; all read-only)\n--\n--   SELECT relname, relrowsecurity FROM pg_class\n--    WHERE relname IN ('super_admins','branch_logins','organizations','branches');\n--   -- expect relrowsecurity = true for all four\n--\n--   SELECT tablename, policyname, cmd, roles FROM pg_policies\n--    WHERE tablename IN ('super_admins','branch_logins','organizations','branches')\n--    ORDER BY 1, 2;\n--   -- expect exactly: branches_read, branches_super_admin_write,\n--   --                 organizations_super_admin\n--\n-- ROLLBACK (manual — reopens the hole, use only if the panel is locked out)\n--\n--   ALTER TABLE super_admins  DISABLE ROW LEVEL SECURITY;\n--   ALTER TABLE branch_logins DISABLE ROW LEVEL SECURITY;\n--   ALTER TABLE organizations DISABLE ROW LEVEL SECURITY;\n--   ALTER TABLE branches      DISABLE ROW LEVEL SECURITY;\n--   GRANT ALL ON super_admins, branch_logins TO anon, authenticated;\n--   NOTIFY pgrst, 'reload schema';\n-- ============================================================\n"},{"name":"0029_customer_rpcs.sql","sql":"-- ============================================================\r\n-- 0029_customer_rpcs.sql   (Batch 2a — customer pages through checked functions)\r\n--\r\n-- Customers (table QR, group ordering, pickup links) have no login. Today their\r\n-- pages read and write tables directly with the public key, and the only thing\r\n-- stopping abuse is the page's own JavaScript. This adds the functions those\r\n-- pages will use instead. Each one is gated by the customer's OWN credential\r\n-- (a table QR token, a guest-session token, or a pickup token) and does every\r\n-- business check on the server:\r\n--\r\n--   guest_join(qr_token, session_token?)  → join the table's party, get a guest token\r\n--   guest_state(session_token)            → table flags + this party's bill, for polling\r\n--   guest_submit(session_token, items)    → add items (ordering on, items available…)\r\n--   guest_call_waiter(session_token)\r\n--   pickup_open(token)                    → is this pickup link usable, for which branch\r\n--   pickup_submit(token, details, items)  → place the ONE order this link allows\r\n--\r\n-- Limits against abuse on a small free database: at most 30 guests per party\r\n-- and 10 new guests per table per minute; at most 40 lines per guest per\r\n-- minute; a waiter call is only written when one isn't already pending.\r\n-- A party (and every guest token in it) closes automatically the moment its\r\n-- bill stops being open — by any payment path — so an old guest can never\r\n-- add to the next party's bill.\r\n--\r\n-- Item pricing/insertion moves into one internal function used by staff AND\r\n-- customers, with checks the old code lacked: product available (not marked\r\n-- finished / out of stock by the kitchen), quantity 1–99, at most 50 lines, and\r\n-- every modifier option must belong to that product. `submit_order_items`\r\n-- keeps its exact signature, so the staff app is unchanged.\r\n--\r\n-- SAFE TO APPLY: additive. RLS stays off; nothing existing stops working.\r\n-- Apply BEFORE deploying the client that calls these. Run AFTER 0028.\r\n-- ============================================================\r\n\r\n-- Random 64-hex token without pgcrypto (two v4 UUIDs ≈ 244 random bits).\r\nCREATE OR REPLACE FUNCTION public._random_token()\r\nRETURNS TEXT LANGUAGE sql VOLATILE AS $$\r\n  SELECT replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');\r\n$$;\r\n\r\n-- Same rule as BranchController.getAccess: unknown branch = open (single-tenant\r\n-- installs), suspended or past contract_end = closed.\r\nCREATE OR REPLACE FUNCTION public._branch_open(p_branch_id TEXT)\r\nRETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$\r\n  SELECT COALESCE((\r\n    SELECT b.status = 'active' AND (b.contract_end IS NULL OR b.contract_end >= CURRENT_DATE)\r\n    FROM branches b WHERE b.id = p_branch_id), true);\r\n$$;\r\n\r\n-- Bill-number counter body (from 0021), kept internal so customer functions can\r\n-- number pickup bills; the public next_bill_number() gets a branch check in 0031.\r\nCREATE OR REPLACE FUNCTION public._next_bill_number(p_branch_id TEXT, p_order_type TEXT)\r\nRETURNS TEXT\r\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\nDECLARE v_num INT;\r\nBEGIN\r\n  INSERT INTO bill_counters (branch_id, order_type, last_number)\r\n    VALUES (p_branch_id, COALESCE(p_order_type, 'dine-in'), 1)\r\n  ON CONFLICT (branch_id, order_type)\r\n    DO UPDATE SET last_number = bill_counters.last_number + 1\r\n  RETURNING last_number INTO v_num;\r\n  RETURN lpad(v_num::text, 4, '0');\r\nEND; $$;\r\nREVOKE ALL ON FUNCTION public._next_bill_number(TEXT, TEXT) FROM PUBLIC, anon, authenticated;\r\n\r\nCREATE OR REPLACE FUNCTION public.next_bill_number(p_branch_id TEXT, p_order_type TEXT)\r\nRETURNS TEXT LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$\r\n  SELECT public._next_bill_number(p_branch_id, p_order_type);\r\n$$;\r\n\r\n-- ── Internal: validate, price and insert order lines ─────────\r\n-- Never granted to anyone: only callable from the functions below.\r\nCREATE OR REPLACE FUNCTION public._add_order_items(\r\n  p_order_id      TEXT,\r\n  p_branch_id     TEXT,\r\n  p_added_by      TEXT,\r\n  p_added_by_name TEXT,\r\n  p_items         JSONB\r\n) RETURNS TABLE (\r\n  id TEXT, product_id TEXT, product_name TEXT, quantity INT,\r\n  price NUMERIC, subtotal NUMERIC, station TEXT, status TEXT,\r\n  notes TEXT, modifiers JSONB, added_by_name TEXT\r\n)\r\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\nDECLARE\r\n  v_order   orders%ROWTYPE;\r\n  v_item    JSONB;\r\n  v_pid     TEXT;\r\n  v_qty     INT;\r\n  v_notes   TEXT;\r\n  v_opts    TEXT[];\r\n  v_base    NUMERIC;\r\n  v_pname   TEXT;\r\n  v_station TEXT;\r\n  v_avail   BOOLEAN;\r\n  v_addons  NUMERIC;\r\n  v_mods    JSONB;\r\n  v_found   INT;\r\n  v_price   NUMERIC;\r\n  v_sub     NUMERIC;\r\n  v_new_id  TEXT;\r\n  v_subtotal NUMERIC;\r\nBEGIN\r\n  SELECT * INTO v_order FROM orders o WHERE o.id = p_order_id AND o.branch_id = p_branch_id FOR UPDATE;\r\n  IF NOT FOUND THEN RAISE EXCEPTION 'Order not found'; END IF;\r\n  IF v_order.status <> 'open' THEN RAISE EXCEPTION 'Cannot add items to a bill that is not open'; END IF;\r\n  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN\r\n    RAISE EXCEPTION 'No items to add';\r\n  END IF;\r\n  IF jsonb_array_length(p_items) > 50 THEN RAISE EXCEPTION 'Too many lines in one order (max 50)'; END IF;\r\n\r\n  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP\r\n    v_pid   := v_item->>'product_id';\r\n    v_qty   := COALESCE((v_item->>'quantity')::int, 1);\r\n    IF v_qty < 1 OR v_qty > 99 THEN RAISE EXCEPTION 'Quantity must be between 1 and 99'; END IF;\r\n    v_notes := NULLIF(left(v_item->>'notes', 300), '');\r\n\r\n    SELECT COALESCE(array_agg(val), '{}') INTO v_opts\r\n      FROM jsonb_array_elements_text(COALESCE(v_item->'option_ids', '[]'::jsonb)) AS t(val);\r\n\r\n    SELECT p.price, p.name, COALESCE(NULLIF(p.station, ''), 'kitchen'),\r\n           COALESCE(p.kitchen_status, 'available') = 'available'\r\n             AND COALESCE(p.availability_status, 'available') = 'available'\r\n      INTO v_base, v_pname, v_station, v_avail\r\n      FROM products p WHERE p.id = v_pid AND p.branch_id = p_branch_id AND p.is_active = true;\r\n    IF NOT FOUND THEN RAISE EXCEPTION 'Product % is not on the menu', v_pid; END IF;\r\n    IF NOT v_avail THEN RAISE EXCEPTION '% is not available right now', v_pname; END IF;\r\n\r\n    v_addons := 0;\r\n    v_mods   := '[]'::jsonb;\r\n    IF array_length(v_opts, 1) IS NOT NULL THEN\r\n      SELECT COUNT(*), COALESCE(SUM(mo.add_on_price), 0),\r\n             COALESCE(jsonb_agg(jsonb_build_object(\r\n               'groupId', mo.group_id, 'groupName', mg.name,\r\n               'optionId', mo.id, 'optionName', mo.name, 'price', mo.add_on_price)), '[]'::jsonb)\r\n        INTO v_found, v_addons, v_mods\r\n        FROM modifier_options mo\r\n        JOIN modifier_groups mg ON mg.id = mo.group_id\r\n        JOIN product_modifier_groups pmg ON pmg.group_id = mo.group_id AND pmg.product_id = v_pid\r\n        WHERE mo.id = ANY(v_opts);\r\n      IF v_found <> (SELECT COUNT(DISTINCT x) FROM unnest(v_opts) x) THEN\r\n        RAISE EXCEPTION 'An option chosen for % is not offered for it', v_pname;\r\n      END IF;\r\n    END IF;\r\n\r\n    v_price  := v_base + v_addons;\r\n    v_sub    := v_price * v_qty;\r\n    v_new_id := 'item-' || substr(public._random_token(), 1, 24);\r\n\r\n    INSERT INTO order_items(\r\n      id, order_id, product_id, product_name, quantity, price, subtotal,\r\n      notes, modifiers, status, added_by, added_by_name, station, branch_id, paid)\r\n    VALUES (\r\n      v_new_id, p_order_id, v_pid, v_pname, v_qty, v_price, v_sub,\r\n      v_notes, v_mods, 'pending', p_added_by, p_added_by_name, v_station, p_branch_id, false);\r\n\r\n    RETURN QUERY SELECT v_new_id, v_pid, v_pname, v_qty, v_price, v_sub,\r\n                        v_station, 'pending'::text, v_notes, v_mods, p_added_by_name;\r\n  END LOOP;\r\n\r\n  -- Tax stays 0 on an open order (applied at payment), as before.\r\n  SELECT COALESCE(SUM(oi.subtotal), 0) INTO v_subtotal\r\n    FROM order_items oi WHERE oi.order_id = p_order_id AND oi.branch_id = p_branch_id\r\n      AND oi.status IS DISTINCT FROM 'cancelled';\r\n  UPDATE orders SET subtotal = v_subtotal, tax = 0, total = v_subtotal WHERE orders.id = p_order_id;\r\nEND; $$;\r\nREVOKE ALL ON FUNCTION public._add_order_items(TEXT, TEXT, TEXT, TEXT, JSONB) FROM PUBLIC, anon, authenticated;\r\n\r\n-- Staff path: same signature as 0022, now with the checks above.\r\nCREATE OR REPLACE FUNCTION public.submit_order_items(\r\n  p_order_id      TEXT,\r\n  p_branch_id     TEXT,\r\n  p_added_by      TEXT,\r\n  p_added_by_name TEXT,\r\n  p_items         JSONB\r\n) RETURNS TABLE (\r\n  id TEXT, product_id TEXT, product_name TEXT, quantity INT,\r\n  price NUMERIC, subtotal NUMERIC, station TEXT, status TEXT,\r\n  notes TEXT, modifiers JSONB, added_by_name TEXT\r\n)\r\nLANGUAGE sql SECURITY DEFINER SET search_path = public AS $$\r\n  SELECT * FROM public._add_order_items(p_order_id, p_branch_id, p_added_by, p_added_by_name, p_items);\r\n$$;\r\n\r\n-- ── Internal: resolve a guest session to its party ───────────\r\nCREATE OR REPLACE FUNCTION public._guest(p_session_token TEXT)\r\nRETURNS TABLE (session_id TEXT, guest_label TEXT, group_id TEXT, order_id TEXT,\r\n               table_id TEXT, table_number INT, branch_id TEXT,\r\n               ordering_enabled BOOLEAN, needs_waiter BOOLEAN)\r\nLANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$\r\n  SELECT gs.id, gs.guest_label, og.id, og.order_id, t.id, t.number, t.branch_id,\r\n         COALESCE(t.ordering_enabled, false), COALESCE(t.needs_waiter, false)\r\n  FROM guest_sessions gs\r\n  JOIN order_groups og ON og.id = gs.group_id\r\n  JOIN tables t ON t.id = og.table_id          -- follows the party if the order was moved\r\n  WHERE gs.token = p_session_token AND length(p_session_token) = 64\r\n    AND gs.status = 'active' AND og.status = 'active'\r\n  LIMIT 1;\r\n$$;\r\nREVOKE ALL ON FUNCTION public._guest(TEXT) FROM PUBLIC, anon, authenticated;\r\n\r\n-- ── guest_join ───────────────────────────────────────────────\r\n-- p_qr_token: the printed table token (tables.qr_token) or an active legacy\r\n-- qr_sessions token. p_session_token: a token this phone saved earlier — reused\r\n-- when it still belongs to the same table's open party.\r\nCREATE OR REPLACE FUNCTION public.guest_join(p_qr_token TEXT, p_session_token TEXT DEFAULT NULL)\r\nRETURNS JSONB\r\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\nDECLARE\r\n  v_table  tables%ROWTYPE;\r\n  v_group  TEXT;\r\n  v_count  INT;\r\n  v_token  TEXT;\r\n  v_label  TEXT;\r\n  v_g      RECORD;\r\nBEGIN\r\n  IF p_qr_token IS NULL OR length(p_qr_token) <> 64 THEN RETURN NULL; END IF;\r\n\r\n  SELECT * INTO v_table FROM tables t WHERE t.qr_token = p_qr_token;\r\n  IF NOT FOUND THEN\r\n    SELECT t.* INTO v_table FROM qr_sessions q JOIN tables t ON t.id = q.table_id\r\n      WHERE q.token = p_qr_token AND q.active AND (q.expires_at IS NULL OR q.expires_at > NOW());\r\n    IF NOT FOUND THEN RETURN NULL; END IF;\r\n  END IF;\r\n  IF NOT public._branch_open(v_table.branch_id) THEN\r\n    RETURN jsonb_build_object('closed', true);\r\n  END IF;\r\n\r\n  -- Resume this phone's session if it is still the same table's open party.\r\n  IF p_session_token IS NOT NULL THEN\r\n    SELECT * INTO v_g FROM public._guest(p_session_token);\r\n    IF FOUND AND v_g.table_id = v_table.id THEN\r\n      UPDATE guest_sessions SET last_seen = NOW() WHERE token = p_session_token;\r\n      RETURN jsonb_build_object('session_token', p_session_token, 'guest_label', v_g.guest_label);\r\n    END IF;\r\n  END IF;\r\n\r\n  -- One active party per table (partial unique index serialises first scans).\r\n  SELECT og.id INTO v_group FROM order_groups og WHERE og.table_id = v_table.id AND og.status = 'active';\r\n  IF v_group IS NULL THEN\r\n    v_group := gen_random_uuid()::text;\r\n    BEGIN\r\n      INSERT INTO order_groups(id, table_id, branch_id, order_id, status)\r\n        VALUES (v_group, v_table.id, v_table.branch_id, NULL, 'active');\r\n    EXCEPTION WHEN unique_violation THEN\r\n      SELECT og.id INTO v_group FROM order_groups og WHERE og.table_id = v_table.id AND og.status = 'active';\r\n    END;\r\n  END IF;\r\n\r\n  SELECT COUNT(*) INTO v_count FROM guest_sessions gs WHERE gs.group_id = v_group;\r\n  IF v_count >= 30 THEN RETURN jsonb_build_object('full', true); END IF;\r\n  IF (SELECT COUNT(*) FROM guest_sessions gs WHERE gs.table_id = v_table.id\r\n        AND gs.created_at > NOW() - interval '1 minute') >= 10 THEN\r\n    RAISE EXCEPTION 'Too many people joined this table just now. Please try again in a minute.';\r\n  END IF;\r\n  v_label := 'Guest ' || (v_count + 1);\r\n  v_token := public._random_token();\r\n  INSERT INTO guest_sessions(id, group_id, table_id, branch_id, token, guest_label, status)\r\n    VALUES (gen_random_uuid()::text, v_group, v_table.id, v_table.branch_id, v_token, v_label, 'active');\r\n\r\n  RETURN jsonb_build_object('session_token', v_token, 'guest_label', v_label);\r\nEND; $$;\r\n\r\n-- ── guest_state (polled every few seconds by the customer page) ──\r\nCREATE OR REPLACE FUNCTION public.guest_state(p_session_token TEXT)\r\nRETURNS JSONB\r\nLANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$\r\nDECLARE v_g RECORD;\r\nBEGIN\r\n  SELECT * INTO v_g FROM public._guest(p_session_token);\r\n  IF NOT FOUND THEN RETURN NULL; END IF;\r\n  RETURN jsonb_build_object(\r\n    'guest_label', v_g.guest_label,\r\n    'table_id', v_g.table_id,\r\n    'table_number', v_g.table_number,\r\n    'branch_id', v_g.branch_id,\r\n    'ordering_enabled', v_g.ordering_enabled AND public._branch_open(v_g.branch_id),\r\n    'needs_waiter', v_g.needs_waiter,\r\n    'order_id', v_g.order_id,\r\n    'items', COALESCE((\r\n      SELECT jsonb_agg(jsonb_build_object(\r\n        'id', oi.id, 'product_id', oi.product_id, 'product_name', oi.product_name,\r\n        'quantity', oi.quantity, 'price', oi.price, 'status', oi.status,\r\n        'added_by_name', oi.added_by_name, 'modifiers', oi.modifiers) ORDER BY oi.created_at)\r\n      FROM order_items oi JOIN orders o ON o.id = oi.order_id\r\n      WHERE oi.order_id = v_g.order_id AND oi.branch_id = v_g.branch_id AND o.status = 'open'\r\n        AND oi.status IS DISTINCT FROM 'cancelled'), '[]'::jsonb),\r\n    -- lets the menu grey out dishes the kitchen just marked finished\r\n    'unavailable_product_ids', COALESCE((\r\n      SELECT jsonb_agg(p.id) FROM products p\r\n      WHERE p.branch_id = v_g.branch_id AND p.is_active\r\n        AND (COALESCE(p.kitchen_status, 'available') <> 'available'\r\n             OR COALESCE(p.availability_status, 'available') <> 'available')), '[]'::jsonb)\r\n  );\r\nEND; $$;\r\n\r\n-- ── guest_submit ─────────────────────────────────────────────\r\nCREATE OR REPLACE FUNCTION public.guest_submit(p_session_token TEXT, p_items JSONB)\r\nRETURNS JSONB\r\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\nDECLARE\r\n  v_g      RECORD;\r\n  v_order  TEXT;\r\n  v_open   BOOLEAN;\r\nBEGIN\r\n  SELECT * INTO v_g FROM public._guest(p_session_token);\r\n  IF NOT FOUND THEN RAISE EXCEPTION 'This table session has ended. Please scan the table QR again.'; END IF;\r\n  IF NOT public._branch_open(v_g.branch_id) THEN RAISE EXCEPTION 'Ordering is not available right now.'; END IF;\r\n  IF NOT v_g.ordering_enabled THEN RAISE EXCEPTION 'Ordering is not switched on for this table yet. Please ask your waiter.'; END IF;\r\n  IF (SELECT COUNT(*) FROM order_items oi WHERE oi.added_by = v_g.session_id\r\n        AND oi.created_at > NOW() - interval '1 minute') >= 40 THEN\r\n    RAISE EXCEPTION 'Please wait a moment before ordering more.';\r\n  END IF;\r\n\r\n  -- Serialise the party's first order so two phones can't open two bills.\r\n  PERFORM 1 FROM order_groups WHERE id = v_g.group_id FOR UPDATE;\r\n  SELECT og.order_id INTO v_order FROM order_groups og WHERE og.id = v_g.group_id;\r\n  SELECT o.status = 'open' INTO v_open FROM orders o WHERE o.id = v_order;\r\n\r\n  IF v_order IS NULL OR NOT COALESCE(v_open, false) THEN\r\n    -- Join the bill staff already opened at this table, else start one.\r\n    SELECT o.id INTO v_order FROM tables t JOIN orders o ON o.id = t.current_order_id\r\n      WHERE t.id = v_g.table_id AND o.status = 'open';\r\n    IF v_order IS NULL THEN\r\n      v_order := 'order-' || substr(public._random_token(), 1, 24);\r\n      INSERT INTO orders(id, table_id, table_number, status, order_type, branch_id, waiters, subtotal, tax, total)\r\n        VALUES (v_order, v_g.table_id, v_g.table_number, 'open', 'dine-in', v_g.branch_id, '[]'::jsonb, 0, 0, 0);\r\n    END IF;\r\n    UPDATE order_groups SET order_id = v_order WHERE id = v_g.group_id;\r\n  END IF;\r\n\r\n  PERFORM public._add_order_items(v_order, v_g.branch_id, v_g.session_id, v_g.guest_label, p_items);\r\n  UPDATE tables SET status = 'occupied', current_order_id = v_order WHERE id = v_g.table_id;\r\n  UPDATE guest_sessions SET last_seen = NOW() WHERE token = p_session_token;\r\n\r\n  RETURN public.guest_state(p_session_token);\r\nEND; $$;\r\n\r\n-- ── guest_call_waiter ────────────────────────────────────────\r\nCREATE OR REPLACE FUNCTION public.guest_call_waiter(p_session_token TEXT)\r\nRETURNS BOOLEAN\r\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\nDECLARE v_g RECORD;\r\nBEGIN\r\n  SELECT * INTO v_g FROM public._guest(p_session_token);\r\n  IF NOT FOUND THEN RETURN false; END IF;\r\n  UPDATE tables SET needs_waiter = true WHERE id = v_g.table_id AND needs_waiter IS NOT TRUE;\r\n  RETURN true;\r\nEND; $$;\r\n\r\n-- ── pickup_open ──────────────────────────────────────────────\r\nCREATE OR REPLACE FUNCTION public.pickup_open(p_token TEXT)\r\nRETURNS JSONB\r\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\nDECLARE v_t pickup_tokens%ROWTYPE;\r\nBEGIN\r\n  IF p_token IS NULL OR length(p_token) <> 64 THEN RETURN NULL; END IF;\r\n  SELECT * INTO v_t FROM pickup_tokens WHERE token = p_token AND active;\r\n  IF NOT FOUND OR v_t.status IN ('completed', 'expired') THEN RETURN NULL; END IF;\r\n  IF v_t.expires_at IS NOT NULL AND v_t.expires_at < NOW() THEN\r\n    UPDATE pickup_tokens SET active = false, status = 'expired' WHERE token = p_token;\r\n    RETURN NULL;\r\n  END IF;\r\n  IF NOT public._branch_open(v_t.branch_id) THEN RETURN NULL; END IF;\r\n  RETURN jsonb_build_object('branch_id', v_t.branch_id, 'status', v_t.status, 'order_id', v_t.order_id,\r\n    'tax', (SELECT jsonb_build_object('enabled', s.tax_enabled, 'rate', s.tax_rate,\r\n                                      'inclusive', s.tax_inclusive, 'label', s.tax_label)\r\n            FROM branch_settings s WHERE s.branch_id = v_t.branch_id));\r\nEND; $$;\r\n\r\n-- ── pickup_submit ────────────────────────────────────────────\r\n-- p_details: {customerName, customerPhone, customerEmail, method, payType, receiptUrl}\r\nCREATE OR REPLACE FUNCTION public.pickup_submit(p_token TEXT, p_details JSONB, p_items JSONB)\r\nRETURNS JSONB\r\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\nDECLARE\r\n  v_t      pickup_tokens%ROWTYPE;\r\n  v_name   TEXT := btrim(p_details->>'customerName');\r\n  v_phone  TEXT := btrim(p_details->>'customerPhone');\r\n  v_email  TEXT := NULLIF(btrim(p_details->>'customerEmail'), '');\r\n  v_method TEXT := p_details->>'method';\r\n  v_pay    TEXT := p_details->>'payType';\r\n  v_rcpt   TEXT := NULLIF(btrim(p_details->>'receiptUrl'), '');\r\n  v_order  TEXT;\r\n  v_bill   TEXT;\r\n  v_total  NUMERIC;\r\n  v_rname  TEXT;\r\nBEGIN\r\n  SELECT * INTO v_t FROM pickup_tokens WHERE token = p_token AND active FOR UPDATE;\r\n  IF NOT FOUND OR (v_t.expires_at IS NOT NULL AND v_t.expires_at < NOW()) THEN\r\n    RAISE EXCEPTION 'This pickup link is no longer valid.';\r\n  END IF;\r\n  IF v_t.status <> 'new' THEN RAISE EXCEPTION 'An order has already been placed with this link.'; END IF;\r\n  IF NOT public._branch_open(v_t.branch_id) THEN RAISE EXCEPTION 'Ordering is not available right now.'; END IF;\r\n\r\n  IF v_name IS NULL OR length(v_name) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Please enter your name.'; END IF;\r\n  IF v_phone IS NULL OR v_phone !~ '^\\+?[0-9 ()-]{6,20}$' THEN RAISE EXCEPTION 'Please enter a valid phone number.'; END IF;\r\n  IF v_email IS NOT NULL AND (length(v_email) > 200 OR v_email !~ '^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$') THEN\r\n    RAISE EXCEPTION 'Please enter a valid email address.';\r\n  END IF;\r\n  IF v_method IS NULL OR v_method NOT IN ('grab', 'lalamove', 'self') THEN RAISE EXCEPTION 'Please choose a pickup method.'; END IF;\r\n  IF v_pay IS NULL OR v_pay NOT IN ('cash', 'online') THEN RAISE EXCEPTION 'Please choose a payment option.'; END IF;\r\n  -- Receipts must be a file uploaded to THIS project's receipts bucket, not any URL.\r\n  IF v_rcpt IS NOT NULL THEN\r\n    v_rname := substring(v_rcpt FROM '^https://[a-z0-9-]+\\.supabase\\.co/storage/v1/object/public/pickup-receipts/([A-Za-z0-9._-]{1,200})$');\r\n    IF v_rname IS NULL OR NOT EXISTS (\r\n         SELECT 1 FROM storage.objects o WHERE o.bucket_id = 'pickup-receipts' AND o.name = v_rname) THEN\r\n      RAISE EXCEPTION 'Invalid receipt file.';\r\n    END IF;\r\n  END IF;\r\n  IF v_pay = 'online' AND v_rcpt IS NULL THEN RAISE EXCEPTION 'Please upload your payment receipt.'; END IF;\r\n\r\n  v_order := 'order-' || substr(public._random_token(), 1, 24);\r\n  v_bill  := public._next_bill_number(v_t.branch_id, 'pickup');\r\n  INSERT INTO orders(\r\n    id, table_id, table_number, status, order_type, branch_id, waiters, bill_number,\r\n    subtotal, tax, total, pickup_method, pickup_status, pickup_pay_type,\r\n    customer_name, customer_phone, customer_email, payment_status, payment_receipt_url)\r\n  VALUES (\r\n    v_order, NULL, 0, 'open', 'pickup', v_t.branch_id, '[]'::jsonb, v_bill,\r\n    0, 0, 0, v_method, 'preparing', v_pay,\r\n    v_name, v_phone, v_email,\r\n    CASE WHEN v_pay = 'online' THEN 'pending_verification' ELSE 'unpaid' END, v_rcpt);\r\n\r\n  PERFORM public._add_order_items(v_order, v_t.branch_id, 'pickup-customer', v_name, p_items);\r\n\r\n  UPDATE pickup_tokens SET order_id = v_order, status = 'ordered' WHERE id = v_t.id;\r\n  INSERT INTO audit_logs(id, action, entity, entity_id, user_id, user_name, branch_id, details)\r\n    VALUES ('aud-' || substr(public._random_token(), 1, 20), 'pickup.order_submitted', 'order', v_order,\r\n            NULL, NULL, v_t.branch_id, jsonb_build_object('method', v_method, 'payType', v_pay, 'customer', v_name));\r\n\r\n  SELECT o.total INTO v_total FROM orders o WHERE o.id = v_order;\r\n  RETURN jsonb_build_object('order_id', v_order, 'bill_number', v_bill, 'total', v_total);\r\nEND; $$;\r\n\r\n-- ── A party closes the moment its bill stops being open ─────\r\n-- Whole-bill payment, split payment, pickup collection, cancellation: whichever\r\n-- path closes the bill, the table's party and all its guest tokens close too.\r\nCREATE OR REPLACE FUNCTION public._close_party_on_bill_close()\r\nRETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\nDECLARE v_groups TEXT[];\r\nBEGIN\r\n  IF OLD.status = 'open' AND NEW.status <> 'open' THEN\r\n    SELECT array_agg(og.id) INTO v_groups FROM order_groups og\r\n      WHERE og.status = 'active'\r\n        AND (og.order_id = NEW.id OR (NEW.table_id IS NOT NULL AND og.table_id = NEW.table_id));\r\n    IF v_groups IS NOT NULL THEN\r\n      UPDATE guest_sessions SET status = 'closed' WHERE group_id = ANY(v_groups);\r\n      UPDATE order_groups SET status = 'closed', closed_at = NOW() WHERE id = ANY(v_groups);\r\n    END IF;\r\n  END IF;\r\n  RETURN NULL;\r\nEND; $$;\r\nREVOKE ALL ON FUNCTION public._close_party_on_bill_close() FROM PUBLIC, anon, authenticated;\r\nDROP TRIGGER IF EXISTS trg_close_party_on_bill_close ON orders;\r\nCREATE TRIGGER trg_close_party_on_bill_close\r\n  AFTER UPDATE OF status ON orders\r\n  FOR EACH ROW EXECUTE FUNCTION public._close_party_on_bill_close();\r\n\r\n-- ── Grants: customer functions are public; internals are not ──\r\nREVOKE ALL ON FUNCTION public._random_token() FROM PUBLIC, anon, authenticated;\r\nREVOKE ALL ON FUNCTION public._branch_open(TEXT) FROM PUBLIC, anon, authenticated;\r\nREVOKE ALL ON FUNCTION public.guest_join(TEXT, TEXT) FROM PUBLIC;\r\nREVOKE ALL ON FUNCTION public.guest_state(TEXT) FROM PUBLIC;\r\nREVOKE ALL ON FUNCTION public.guest_submit(TEXT, JSONB) FROM PUBLIC;\r\nREVOKE ALL ON FUNCTION public.guest_call_waiter(TEXT) FROM PUBLIC;\r\nREVOKE ALL ON FUNCTION public.pickup_open(TEXT) FROM PUBLIC;\r\nREVOKE ALL ON FUNCTION public.pickup_submit(TEXT, JSONB, JSONB) FROM PUBLIC;\r\nGRANT EXECUTE ON FUNCTION public.guest_join(TEXT, TEXT)          TO anon, authenticated;\r\nGRANT EXECUTE ON FUNCTION public.guest_state(TEXT)               TO anon, authenticated;\r\nGRANT EXECUTE ON FUNCTION public.guest_submit(TEXT, JSONB)       TO anon, authenticated;\r\nGRANT EXECUTE ON FUNCTION public.guest_call_waiter(TEXT)         TO anon, authenticated;\r\nGRANT EXECUTE ON FUNCTION public.pickup_open(TEXT)               TO anon, authenticated;\r\nGRANT EXECUTE ON FUNCTION public.pickup_submit(TEXT, JSONB, JSONB) TO anon, authenticated;\r\n\r\nNOTIFY pgrst, 'reload schema';\r\n\r\n-- ============================================================\r\n-- ROLLBACK (manual). Restores 0022's submit_order_items body first.\r\n--   Re-run 0022_server_side_pricing.sql, then:\r\n--   DROP TRIGGER IF EXISTS trg_close_party_on_bill_close ON orders;\r\n--   DROP FUNCTION IF EXISTS public._close_party_on_bill_close();\r\n--   DROP FUNCTION IF EXISTS public.guest_join(TEXT, TEXT), public.guest_state(TEXT),\r\n--     public.guest_submit(TEXT, JSONB), public.guest_call_waiter(TEXT),\r\n--     public.pickup_open(TEXT), public.pickup_submit(TEXT, JSONB, JSONB),\r\n--     public._guest(TEXT), public._add_order_items(TEXT, TEXT, TEXT, TEXT, JSONB),\r\n--     public._branch_open(TEXT), public._random_token();\r\n--   then re-run 0021 for next_bill_number, and DROP FUNCTION public._next_bill_number(TEXT, TEXT);\r\n--   NOTIFY pgrst, 'reload schema';\r\n-- ============================================================\r\n"},{"name":"0030_staff_pin.sql","sql":"-- ============================================================\n-- 0030_staff_pin.sql   (Batch 2b — audit AUD-03)\n--\n-- Today every visitor downloads every staff member of every tenant, with the\n-- plaintext 4-digit PIN; PIN login has no attempt limit and no branch scope, so\n-- two people with the same PIN (likely across tenants) log in as each other.\n--\n--   1. No plaintext PINs stored. The existing hashing trigger now also blanks\n--      `users.pin` after hashing it, and refuses a PIN that someone else in the\n--      same branch already uses. Existing plaintext PINs are blanked here.\n--   2. verify_staff_pin() only matches staff of the branch the DEVICE is signed\n--      in to (current_device_branch(), 0024), and is callable by signed-in\n--      devices only. Wrong tries: 5 per minute per terminal (the app passes its\n--      device id) and 30 per minute for the whole branch login (which all the\n--      branch's terminals share), so one terminal can't lock out the others and\n--      a script can't rotate ids to brute-force. A correct PIN does NOT reset the\n--      count (that would let guesses be interleaved with a known PIN).\n--   3. set_staff_pin() only for staff of the caller's own branch.\n--   4. The `pin` and `pin_hash` columns can no longer be read through the API,\n--      and `pin_hash` can't be written directly either (only the trigger sets\n--      it); signed-in devices may read the other staff columns. Anonymous\n--      visitors cannot read the staff table at all.\n--\n-- REQUIRES: every device that uses the PIN pad is signed in with its branch\n-- email + password (the installed app already asks once a branch login exists).\n-- DATA: blanks plaintext PINs (pin_hash keeps working). Production data was\n-- confirmed disposable on 2026-11-17. Apply BEFORE the matching client.\n-- ============================================================\n\nALTER TABLE users ALTER COLUMN pin DROP NOT NULL;\n\nCREATE OR REPLACE FUNCTION public.users_sync_pin_hash()\nRETURNS TRIGGER\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions\nAS $$\nBEGIN\n  IF NEW.pin IS NOT NULL AND NEW.pin <> '' THEN\n    IF NEW.pin !~ '^\\d{4}$' THEN RAISE EXCEPTION 'PIN must be exactly 4 digits'; END IF;\n    -- One PIN change per branch at a time, so two concurrent saves can't both pass the check.\n    PERFORM pg_advisory_xact_lock(hashtext('pin:' || NEW.branch_id));\n    IF EXISTS (\n      SELECT 1 FROM users u\n      WHERE u.branch_id = NEW.branch_id AND u.id <> NEW.id   -- inactive staff too: they can be reactivated\n        AND u.pin_hash IS NOT NULL AND u.pin_hash = extensions.crypt(NEW.pin, u.pin_hash)\n    ) THEN\n      RAISE EXCEPTION 'That PIN is already used by someone in this branch. Choose another.'\n        USING ERRCODE = 'unique_violation';\n    END IF;\n    NEW.pin_hash := extensions.crypt(NEW.pin, extensions.gen_salt('bf'));\n  END IF;\n  NEW.pin := NULL;   -- never keep the plaintext\n  RETURN NEW;\nEND;\n$$;\n\nDROP TRIGGER IF EXISTS trg_users_sync_pin_hash ON users;\nCREATE TRIGGER trg_users_sync_pin_hash\n  BEFORE INSERT OR UPDATE ON users\n  FOR EACH ROW EXECUTE FUNCTION public.users_sync_pin_hash();\n\nUPDATE users SET pin = NULL WHERE pin IS NOT NULL AND pin_hash IS NOT NULL;\n\n-- ── Attempt throttle ─────────────────────────────────────────\nCREATE TABLE IF NOT EXISTS pin_attempts (\n  device_uid   TEXT NOT NULL,   -- branch login uid, or uid:terminal-id\n  attempted_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\nCREATE INDEX IF NOT EXISTS idx_pin_attempts_device ON pin_attempts(device_uid, attempted_at);\nALTER TABLE pin_attempts ENABLE ROW LEVEL SECURITY;            -- no policies: functions only\nREVOKE ALL ON pin_attempts FROM anon, authenticated;\n\n-- Return type is unchanged from 0004, so the client keeps working.\nDROP FUNCTION IF EXISTS public.verify_staff_pin(TEXT);\nDROP FUNCTION IF EXISTS public.verify_staff_pin(TEXT, TEXT);\nCREATE FUNCTION public.verify_staff_pin(p_pin TEXT, p_device TEXT DEFAULT NULL)\nRETURNS TABLE (\n  id TEXT, name TEXT, employment_number TEXT, role TEXT, email TEXT,\n  status TEXT, branch_id TEXT, created_at TIMESTAMPTZ,\n  hire_date DATE, hourly_rate NUMERIC, job_role TEXT\n)\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions\nAS $$\nDECLARE\n  v_login  TEXT := auth.uid()::text;\n  v_device TEXT;\n  v_branch TEXT := public.current_device_branch();\nBEGIN\n  IF v_login IS NULL OR v_branch IS NULL THEN\n    RAISE EXCEPTION 'This device is not signed in to a branch. Ask an admin to sign it in.';\n  END IF;\n  v_device := v_login || ':' || left(COALESCE(p_device, '?'), 64);\n  PERFORM pg_advisory_xact_lock(hashtext('pinlogin:' || v_login));   -- count + insert as one step\n\n  DELETE FROM pin_attempts WHERE attempted_at < NOW() - interval '1 hour';\n  IF (SELECT COUNT(*) FROM pin_attempts WHERE device_uid = v_device\n        AND attempted_at > NOW() - interval '1 minute') >= 5 THEN\n    RAISE EXCEPTION 'Too many wrong PINs on this terminal. Please wait a minute and try again.';\n  END IF;\n  IF (SELECT COUNT(*) FROM pin_attempts WHERE device_uid LIKE v_login || ':%'\n        AND attempted_at > NOW() - interval '1 minute') >= 30 THEN\n    RAISE EXCEPTION 'Too many wrong PINs at this branch. Please wait a minute and try again.';\n  END IF;\n\n  RETURN QUERY\n    SELECT u.id, u.name, u.employment_number, u.role, u.email, u.status,\n           u.branch_id, u.created_at, u.hire_date, u.hourly_rate::numeric, u.job_role\n    FROM users u\n    WHERE u.branch_id = v_branch AND u.status = 'active'\n      AND u.pin_hash IS NOT NULL AND u.pin_hash = extensions.crypt(p_pin, u.pin_hash)\n    LIMIT 1;\n\n  IF NOT FOUND THEN\n    INSERT INTO pin_attempts(device_uid) VALUES (v_device);\n  END IF;\nEND;\n$$;\nREVOKE ALL ON FUNCTION public.verify_staff_pin(TEXT, TEXT) FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION public.verify_staff_pin(TEXT, TEXT) TO authenticated;\n\nCREATE OR REPLACE FUNCTION public.set_staff_pin(p_user_id TEXT, p_pin TEXT)\nRETURNS VOID\nLANGUAGE sql SECURITY DEFINER SET search_path = public\nAS $$\n  -- The trigger validates, de-duplicates and hashes.\n  UPDATE users SET pin = p_pin WHERE id = p_user_id AND branch_id = public.current_device_branch();\n$$;\nREVOKE ALL ON FUNCTION public.set_staff_pin(TEXT, TEXT) FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION public.set_staff_pin(TEXT, TEXT) TO authenticated;\n\n-- ── Hide pin / pin_hash from the API ─────────────────────────\n-- Column grants: reads (and RETURNING) may only name these columns.\nREVOKE SELECT, INSERT, UPDATE ON users FROM anon, authenticated;\nGRANT SELECT (id, name, employment_number, role, email, status, branch_id,\n              hire_date, hourly_rate, job_role, created_at) ON users TO authenticated;\n-- Writes may set `pin` (hashed + blanked by the trigger) but never `pin_hash` itself.\nGRANT INSERT (id, name, employment_number, role, pin, email, status, branch_id,\n              hire_date, hourly_rate, job_role, created_at) ON users TO authenticated;\nGRANT UPDATE (name, employment_number, role, pin, email, status, branch_id,\n              hire_date, hourly_rate, job_role) ON users TO authenticated;\n\nNOTIFY pgrst, 'reload schema';\n\n-- ============================================================\n-- VERIFY (read-only)\n--   SELECT count(*) FROM users WHERE pin IS NOT NULL;        -- expect 0\n--   SELECT has_column_privilege('authenticated', 'users', 'pin_hash', 'SELECT');  -- expect false\n--   SELECT has_column_privilege('authenticated', 'users', 'pin_hash', 'UPDATE');  -- expect false\n--\n-- ROLLBACK (manual — plaintext PINs blanked by this file cannot come back;\n-- staff keep logging in through pin_hash, and new PINs can be set again):\n--   ⚠ Do NOT re-grant SELECT on users: pin_hash of a 4-digit PIN cracks in seconds.\n--   Re-run 0004_pin_auth.sql to restore the unscoped verify_staff_pin(TEXT) (and its anon grant), then:\n--   DROP FUNCTION IF EXISTS public.verify_staff_pin(TEXT, TEXT);\n--   GRANT INSERT, UPDATE ON users TO anon, authenticated;\n--   DROP TABLE IF EXISTS pin_attempts;\n--   NOTIFY pgrst, 'reload schema';\n-- ============================================================\n"},{"name":"0031_money_rpcs_branch_check.sql","sql":"-- ============================================================\r\n-- 0031_money_rpcs_branch_check.sql   (Batch 2c — audit AUD-04)\r\n--\r\n-- The order / payment / loyalty / report functions were callable by anyone with\r\n-- the public key, and trusted the branch id the browser passed in. Now each one:\r\n--   * is callable by signed-in devices only (not anon), and\r\n--   * refuses unless the branch it is asked to act on is the branch the device\r\n--     is signed in to (current_device_branch(), 0024).\r\n-- Loyalty calls also refuse a customer that belongs to another branch.\r\n-- Also FIXES split payments: the last split of a bill always failed (see below).\r\n--\r\n-- How: the existing function bodies are kept unchanged under an internal name\r\n-- (_..._impl, never granted), and the public name becomes a thin wrapper with\r\n-- the same signature, so the app needs no change. Customer pages use the 0029\r\n-- functions instead and are unaffected.\r\n--\r\n-- REQUIRES: 0029. Staff devices signed in with a branch login (the website\r\n-- already is; the installed app asks once a branch login exists).\r\n-- Idempotent: re-running does not re-rename.\r\n-- ============================================================\r\n\r\nCREATE OR REPLACE FUNCTION public._assert_device_branch(p_branch_id TEXT)\r\nRETURNS VOID LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$\r\nBEGIN\r\n  IF p_branch_id IS NULL OR p_branch_id IS DISTINCT FROM public.current_device_branch() THEN\r\n    RAISE EXCEPTION 'This device is not signed in to that branch.' USING ERRCODE = 'insufficient_privilege';\r\n  END IF;\r\nEND; $$;\r\nREVOKE ALL ON FUNCTION public._assert_device_branch(TEXT) FROM PUBLIC, anon, authenticated;\r\n\r\nCREATE OR REPLACE FUNCTION public._assert_customer_branch(p_customer_id UUID, p_branch_id TEXT)\r\nRETURNS VOID LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$\r\nBEGIN\r\n  IF NOT EXISTS (SELECT 1 FROM customers WHERE id = p_customer_id AND branch_id = p_branch_id) THEN\r\n    RAISE EXCEPTION 'Customer not found in this branch.';\r\n  END IF;\r\nEND; $$;\r\nREVOKE ALL ON FUNCTION public._assert_customer_branch(UUID, TEXT) FROM PUBLIC, anon, authenticated;\r\n\r\n-- Move each current body to an internal name, once.\r\nDO $$\r\nDECLARE r RECORD;\r\nBEGIN\r\n  FOR r IN SELECT * FROM (VALUES\r\n      ('pay_order_items',       'TEXT, TEXT[], TEXT, NUMERIC, TEXT, TEXT, TEXT'),\r\n      ('move_order_to_table',   'TEXT, TEXT, TEXT'),\r\n      ('earn_loyalty_points',   'UUID, TEXT, INT, NUMERIC, TEXT'),\r\n      ('redeem_loyalty_points', 'UUID, TEXT, INT, TEXT'),\r\n      ('adjust_loyalty_points', 'UUID, INT, TEXT, TEXT'),\r\n      ('get_product_sales',     'TEXT, TIMESTAMPTZ, TIMESTAMPTZ')\r\n    ) AS f(name, args)\r\n  LOOP\r\n    IF to_regprocedure(format('public._%s_impl(%s)', r.name, r.args)) IS NULL THEN\r\n      EXECUTE format('ALTER FUNCTION public.%I(%s) RENAME TO %I', r.name, r.args, '_' || r.name || '_impl');\r\n    END IF;\r\n    EXECUTE format('REVOKE ALL ON FUNCTION public.%I(%s) FROM PUBLIC, anon, authenticated', '_' || r.name || '_impl', r.args);\r\n  END LOOP;\r\nEND $$;\r\n\r\n-- ── Fix: the split-payment body from 0021 never completed a bill ──\r\n-- Its RETURNS TABLE column names (amount, bill_number …) collide with table\r\n-- columns, so the LAST split of every bill failed with \"column reference\r\n-- \"amount\" is ambiguous\" (0017/0020 failed the same way on bill_number) —\r\n-- found by executing it in the migration tests. Same body, plus the pragma\r\n-- that resolves those names to the table columns.\r\nCREATE OR REPLACE FUNCTION public._pay_order_items_impl(\r\n  p_order_id         TEXT,\r\n  p_item_ids         TEXT[],\r\n  p_method           TEXT,\r\n  p_amount_received  NUMERIC,\r\n  p_cashier_id       TEXT,\r\n  p_cashier_name     TEXT,\r\n  p_branch_id        TEXT\r\n) RETURNS TABLE (payment_id TEXT, amount NUMERIC, order_completed BOOLEAN, bill_number TEXT)\r\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\n#variable_conflict use_column\r\nDECLARE\r\n  v_order       orders%ROWTYPE;\r\n  v_amount      NUMERIC;\r\n  v_matched     INT;\r\n  v_remaining   INT;\r\n  v_payment_id  TEXT;\r\n  v_bill_number TEXT := NULL;\r\n  v_group_id    TEXT;\r\n  v_tax_enabled BOOLEAN := false;\r\n  v_tax_rate    NUMERIC := 0;\r\n  v_tax_incl    BOOLEAN := false;\r\n  v_full_sub    NUMERIC := 0;\r\n  v_collected   NUMERIC := 0;\r\n  v_pretax      NUMERIC := 0;\r\nBEGIN\r\n  SELECT * INTO v_order FROM orders WHERE id = p_order_id AND branch_id = p_branch_id FOR UPDATE;\r\n  IF NOT FOUND THEN RAISE EXCEPTION 'Order not found'; END IF;\r\n  IF v_order.status <> 'open' THEN RAISE EXCEPTION 'This bill has already been paid'; END IF;\r\n  IF p_item_ids IS NULL OR array_length(p_item_ids, 1) IS NULL THEN RAISE EXCEPTION 'No items selected'; END IF;\r\n\r\n  SELECT COALESCE(SUM(subtotal), 0), COUNT(*)\r\n    INTO v_amount, v_matched\r\n    FROM order_items\r\n    WHERE order_id = p_order_id AND id = ANY(p_item_ids)\r\n      AND paid = false AND status IS DISTINCT FROM 'cancelled';\r\n\r\n  IF v_matched <> array_length(p_item_ids, 1) THEN\r\n    RAISE EXCEPTION 'One or more selected items are no longer available to pay (already paid, voided, or not on this order)';\r\n  END IF;\r\n  IF v_amount <= 0 THEN RAISE EXCEPTION 'Nothing to pay'; END IF;\r\n\r\n  SELECT tax_enabled, tax_rate, tax_inclusive INTO v_tax_enabled, v_tax_rate, v_tax_incl\r\n    FROM branch_settings WHERE branch_id = p_branch_id;\r\n  IF v_tax_enabled AND v_tax_rate > 0 AND NOT v_tax_incl THEN\r\n    v_amount := round(v_amount * (1 + v_tax_rate / 100), 2);\r\n  END IF;\r\n\r\n  IF p_method = 'cash' AND p_amount_received IS NOT NULL AND p_amount_received < v_amount THEN\r\n    RAISE EXCEPTION 'Amount received is less than the amount due';\r\n  END IF;\r\n\r\n  v_payment_id := 'opay-' || substr(md5(random()::text || clock_timestamp()::text), 1, 20);\r\n\r\n  UPDATE order_items SET paid = true, paid_at = NOW(), payment_id = v_payment_id\r\n    WHERE order_id = p_order_id AND id = ANY(p_item_ids);\r\n\r\n  INSERT INTO order_payments (id, order_id, amount, method, item_ids, cashier_id, cashier_name, branch_id)\r\n    VALUES (v_payment_id, p_order_id, v_amount, p_method, to_jsonb(p_item_ids), p_cashier_id, p_cashier_name, p_branch_id);\r\n\r\n  SELECT COUNT(*) INTO v_remaining\r\n    FROM order_items WHERE order_id = p_order_id AND paid = false AND status IS DISTINCT FROM 'cancelled';\r\n\r\n  IF v_remaining = 0 THEN\r\n    IF v_order.bill_number IS NULL THEN\r\n      v_bill_number := public.next_bill_number(p_branch_id, v_order.order_type);\r\n    ELSE\r\n      v_bill_number := v_order.bill_number;\r\n    END IF;\r\n\r\n    -- M2: the order total is exactly what was collected across all splits, so\r\n    -- it always reconciles with order_payments (no per-split rounding drift).\r\n    SELECT COALESCE(SUM(amount), 0)   INTO v_collected FROM order_payments WHERE order_id = p_order_id;\r\n    SELECT COALESCE(SUM(subtotal), 0) INTO v_full_sub  FROM order_items\r\n      WHERE order_id = p_order_id AND status IS DISTINCT FROM 'cancelled';\r\n\r\n    IF v_tax_enabled AND v_tax_rate > 0 AND v_tax_incl THEN\r\n      v_pretax := round(v_collected / (1 + v_tax_rate / 100), 2);\r\n      UPDATE orders SET status='completed', completed_at=NOW(), payment_status='paid',\r\n        payment_method='split', bill_number=v_bill_number,\r\n        subtotal=v_pretax, tax=(v_collected - v_pretax), total=v_collected\r\n        WHERE id = p_order_id;\r\n    ELSE\r\n      UPDATE orders SET status='completed', completed_at=NOW(), payment_status='paid',\r\n        payment_method='split', bill_number=v_bill_number,\r\n        subtotal=v_full_sub, tax=round(v_collected - v_full_sub, 2), total=v_collected\r\n        WHERE id = p_order_id;\r\n    END IF;\r\n\r\n    IF v_order.table_id IS NOT NULL THEN\r\n      UPDATE tables SET status='available', current_order_id=NULL, ordering_enabled=false\r\n        WHERE id = v_order.table_id;\r\n      SELECT id INTO v_group_id FROM order_groups WHERE table_id = v_order.table_id AND status = 'active';\r\n      IF v_group_id IS NOT NULL THEN\r\n        UPDATE guest_sessions SET status='closed' WHERE group_id = v_group_id;\r\n        UPDATE order_groups   SET status='closed', closed_at=NOW() WHERE id = v_group_id;\r\n      END IF;\r\n      UPDATE qr_sessions SET active=false, last_activity_at=NOW() WHERE table_id = v_order.table_id;\r\n    END IF;\r\n  END IF;\r\n\r\n  RETURN QUERY SELECT v_payment_id, v_amount, (v_remaining = 0), v_bill_number;\r\nEND; $$;\r\nREVOKE ALL ON FUNCTION public._pay_order_items_impl(TEXT, TEXT[], TEXT, NUMERIC, TEXT, TEXT, TEXT) FROM PUBLIC, anon, authenticated;\r\n\r\n-- ── Wrappers (same names + signatures the app already calls) ──\r\nCREATE OR REPLACE FUNCTION public.pay_order_items(\r\n  p_order_id TEXT, p_item_ids TEXT[], p_method TEXT, p_amount_received NUMERIC,\r\n  p_cashier_id TEXT, p_cashier_name TEXT, p_branch_id TEXT\r\n) RETURNS TABLE (payment_id TEXT, amount NUMERIC, order_completed BOOLEAN, bill_number TEXT)\r\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\nBEGIN\r\n  PERFORM public._assert_device_branch(p_branch_id);\r\n  RETURN QUERY SELECT * FROM public._pay_order_items_impl(\r\n    p_order_id, p_item_ids, p_method, p_amount_received, p_cashier_id, p_cashier_name, p_branch_id);\r\nEND; $$;\r\n\r\nCREATE OR REPLACE FUNCTION public.move_order_to_table(p_order_id TEXT, p_to_table_id TEXT, p_branch_id TEXT)\r\nRETURNS TABLE (from_table_id TEXT, to_table_number INT)\r\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\nBEGIN\r\n  PERFORM public._assert_device_branch(p_branch_id);\r\n  RETURN QUERY SELECT * FROM public._move_order_to_table_impl(p_order_id, p_to_table_id, p_branch_id);\r\nEND; $$;\r\n\r\nCREATE OR REPLACE FUNCTION public.earn_loyalty_points(\r\n  p_customer_id UUID, p_order_id TEXT, p_points INT, p_amount NUMERIC, p_branch_id TEXT\r\n) RETURNS VOID\r\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\nBEGIN\r\n  PERFORM public._assert_device_branch(p_branch_id);\r\n  PERFORM public._assert_customer_branch(p_customer_id, p_branch_id);\r\n  PERFORM public._earn_loyalty_points_impl(p_customer_id, p_order_id, p_points, p_amount, p_branch_id);\r\nEND; $$;\r\n\r\nCREATE OR REPLACE FUNCTION public.redeem_loyalty_points(\r\n  p_customer_id UUID, p_order_id TEXT, p_points INT, p_branch_id TEXT\r\n) RETURNS BOOLEAN\r\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\nBEGIN\r\n  PERFORM public._assert_device_branch(p_branch_id);\r\n  PERFORM public._assert_customer_branch(p_customer_id, p_branch_id);\r\n  RETURN public._redeem_loyalty_points_impl(p_customer_id, p_order_id, p_points, p_branch_id);\r\nEND; $$;\r\n\r\nCREATE OR REPLACE FUNCTION public.adjust_loyalty_points(\r\n  p_customer_id UUID, p_points INT, p_description TEXT, p_branch_id TEXT\r\n) RETURNS INT\r\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\nBEGIN\r\n  PERFORM public._assert_device_branch(p_branch_id);\r\n  PERFORM public._assert_customer_branch(p_customer_id, p_branch_id);\r\n  RETURN public._adjust_loyalty_points_impl(p_customer_id, p_points, p_description, p_branch_id);\r\nEND; $$;\r\n\r\nCREATE OR REPLACE FUNCTION public.get_product_sales(p_branch_id TEXT, p_date_from TIMESTAMPTZ, p_date_to TIMESTAMPTZ)\r\nRETURNS TABLE (product_id TEXT, product_name TEXT, units_sold BIGINT, revenue NUMERIC)\r\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\nBEGIN\r\n  PERFORM public._assert_device_branch(p_branch_id);\r\n  RETURN QUERY SELECT * FROM public._get_product_sales_impl(p_branch_id, p_date_from, p_date_to);\r\nEND; $$;\r\n\r\nCREATE OR REPLACE FUNCTION public.submit_order_items(\r\n  p_order_id TEXT, p_branch_id TEXT, p_added_by TEXT, p_added_by_name TEXT, p_items JSONB\r\n) RETURNS TABLE (\r\n  id TEXT, product_id TEXT, product_name TEXT, quantity INT,\r\n  price NUMERIC, subtotal NUMERIC, station TEXT, status TEXT,\r\n  notes TEXT, modifiers JSONB, added_by_name TEXT\r\n)\r\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\nBEGIN\r\n  PERFORM public._assert_device_branch(p_branch_id);\r\n  RETURN QUERY SELECT * FROM public._add_order_items(p_order_id, p_branch_id, p_added_by, p_added_by_name, p_items);\r\nEND; $$;\r\n\r\nCREATE OR REPLACE FUNCTION public.next_bill_number(p_branch_id TEXT, p_order_type TEXT)\r\nRETURNS TEXT\r\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\nBEGIN\r\n  PERFORM public._assert_device_branch(p_branch_id);\r\n  RETURN public._next_bill_number(p_branch_id, p_order_type);\r\nEND; $$;\r\n\r\n-- ── Grants: signed-in devices only ───────────────────────────\r\nDO $$\r\nDECLARE f TEXT;\r\nBEGIN\r\n  FOREACH f IN ARRAY ARRAY[\r\n    'pay_order_items(TEXT, TEXT[], TEXT, NUMERIC, TEXT, TEXT, TEXT)',\r\n    'move_order_to_table(TEXT, TEXT, TEXT)',\r\n    'earn_loyalty_points(UUID, TEXT, INT, NUMERIC, TEXT)',\r\n    'redeem_loyalty_points(UUID, TEXT, INT, TEXT)',\r\n    'adjust_loyalty_points(UUID, INT, TEXT, TEXT)',\r\n    'get_product_sales(TEXT, TIMESTAMPTZ, TIMESTAMPTZ)',\r\n    'submit_order_items(TEXT, TEXT, TEXT, TEXT, JSONB)',\r\n    'next_bill_number(TEXT, TEXT)']\r\n  LOOP\r\n    EXECUTE 'REVOKE ALL ON FUNCTION public.' || f || ' FROM PUBLIC, anon';\r\n    EXECUTE 'GRANT EXECUTE ON FUNCTION public.' || f || ' TO authenticated';\r\n  END LOOP;\r\nEND $$;\r\n\r\n-- The old \"join table group\" (0008) is replaced by guest_join (0029): close it.\r\nREVOKE ALL ON FUNCTION public.join_table_group(TEXT, TEXT, INT) FROM PUBLIC, anon, authenticated;\r\n\r\nNOTIFY pgrst, 'reload schema';\r\n\r\n-- ============================================================\r\n-- ROLLBACK (manual): re-open the functions to everyone without the check.\r\n--   For each wrapper above: DROP FUNCTION public.<name>(<args>);\r\n--   ALTER FUNCTION public._<name>_impl(<args>) RENAME TO <name>;\r\n--   GRANT EXECUTE ON FUNCTION public.<name>(<args>) TO anon, authenticated;\r\n--   (submit_order_items / next_bill_number: re-run 0029.)\r\n-- ============================================================\r\n"},{"name":"0032_enable_rls.sql","sql":"-- ============================================================\r\n-- 0032_enable_rls.sql   (Batch 2d — audit AUD-01: real tenant isolation)\r\n--\r\n-- Turns Row-Level Security ON for every app table. After this:\r\n--   * A signed-in branch device (website admin login, or the installed app's\r\n--     branch login) sees and changes ONLY rows of its own branch:\r\n--       branch_id = current_device_branch()        (0024)\r\n--   * Anonymous visitors (customers) can read only active menus\r\n--     (products, categories, modifiers) and the branch registry (0028).\r\n--     Everything else they do goes through the token-checked functions (0029).\r\n--   * Bookkeeping tables (bill_counters, pin_attempts) are functions-only.\r\n--   * A row that points at another row (a bill line → its bill, a bill → its\r\n--     table, …) must point at a row of the same branch.\r\n--   * Payment and loyalty history can't be edited from a device; the audit log\r\n--     is append-only; a paid bill and its lines can't be changed or deleted.\r\n--   * Uploads of menu photos / the merchant payment QR need a branch device and\r\n--     its own file name; customers can still upload pickup receipts, but nobody\r\n--     can list the receipts bucket.\r\n-- Functions (SECURITY DEFINER) and the Edge Functions (service role) are not\r\n-- affected: they run as the table owner.\r\n--\r\n-- ⚠️ APPLY LAST, after 0029–0031 AND after the matching client is deployed.\r\n-- Every staff device must be signed in with a branch login.\r\n-- ROLLBACK (instant, at the bottom): disable RLS per table.\r\n-- Idempotent.\r\n-- ============================================================\r\n\r\n-- Same-branch rule for a branch table. `link` (optional) is an extra SQL check on\r\n-- the NEW row: rows that point at a parent (an order, a table, a customer…) must\r\n-- point at a parent of the SAME branch. Without it a device could plant a line on\r\n-- another branch's bill, because foreign-key checks ignore RLS.\r\nCREATE OR REPLACE FUNCTION pg_temp.branch_policy(t TEXT, link TEXT DEFAULT NULL)\r\nRETURNS VOID LANGUAGE plpgsql AS $f$\r\nDECLARE chk TEXT := 'branch_id = (SELECT public.current_device_branch())';\r\nBEGIN\r\n  IF to_regclass('public.' || t) IS NULL THEN RETURN; END IF;     -- a migration not applied yet\r\n  EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);\r\n  EXECUTE format('DROP POLICY IF EXISTS branch_isolation ON public.%I', t);\r\n  EXECUTE format('CREATE POLICY branch_isolation ON public.%I FOR ALL TO authenticated USING (%s) WITH CHECK (%s)',\r\n                 t, chk, chk || COALESCE(' AND ' || link, ''));\r\nEND $f$;\r\n\r\n-- \"col is empty, or names a row of <parent> in the caller's own branch\"\r\nCREATE OR REPLACE FUNCTION pg_temp.same_branch(col TEXT, parent TEXT, pk TEXT DEFAULT 'id')\r\nRETURNS TEXT LANGUAGE sql AS $f$\r\n  SELECT format('(%1$s IS NULL OR EXISTS (SELECT 1 FROM public.%2$I p WHERE p.%3$I = %1$s AND p.branch_id = (SELECT public.current_device_branch())))',\r\n                col, parent, pk);\r\n$f$;\r\n\r\nSELECT pg_temp.branch_policy(t) FROM unnest(ARRAY[\r\n  'users', 'categories', 'tables', 'expenses', 'customers', 'ingredient_orders', 'employees',\r\n  'attendance_logs', 'payroll_summary', 'leave_requests', 'modifier_groups', 'branch_settings',\r\n  'shifts', 'employee_performance_observations']) AS t;\r\n\r\nSELECT pg_temp.branch_policy('products',     pg_temp.same_branch('category_id', 'categories'));\r\nSELECT pg_temp.branch_policy('orders',       pg_temp.same_branch('table_id', 'tables'));\r\nSELECT pg_temp.branch_policy('order_items',  pg_temp.same_branch('order_id', 'orders') || ' AND ' || pg_temp.same_branch('product_id', 'products'));\r\nSELECT pg_temp.branch_policy('qr_sessions',  pg_temp.same_branch('table_id', 'tables'));\r\nSELECT pg_temp.branch_policy('order_groups', pg_temp.same_branch('table_id', 'tables') || ' AND ' || pg_temp.same_branch('order_id', 'orders'));\r\nSELECT pg_temp.branch_policy('guest_sessions', pg_temp.same_branch('group_id', 'order_groups') || ' AND ' || pg_temp.same_branch('table_id', 'tables'));\r\nSELECT pg_temp.branch_policy('pickup_tokens', pg_temp.same_branch('order_id', 'orders'));\r\nSELECT pg_temp.branch_policy('audit_logs');\r\nSELECT pg_temp.branch_policy('order_payments', pg_temp.same_branch('order_id', 'orders'));\r\nSELECT pg_temp.branch_policy('loyalty_transactions', pg_temp.same_branch('customer_id', 'customers') || ' AND ' || pg_temp.same_branch('order_id', 'orders'));\r\n\r\n-- ── History is not rewritable from a device ──────────────────\r\n-- Payments and loyalty history are written only by the server functions; the\r\n-- audit log may be appended to but not edited. A paid bill (and its lines) can no\r\n-- longer be changed or deleted directly — only an OPEN bill can.\r\nDROP POLICY IF EXISTS branch_isolation ON order_payments;\r\nCREATE POLICY branch_read ON order_payments FOR SELECT TO authenticated\r\n  USING (branch_id = (SELECT public.current_device_branch()));\r\nDROP POLICY IF EXISTS branch_isolation ON loyalty_transactions;\r\nCREATE POLICY branch_read ON loyalty_transactions FOR SELECT TO authenticated\r\n  USING (branch_id = (SELECT public.current_device_branch()));\r\nDROP POLICY IF EXISTS branch_isolation ON audit_logs;\r\nCREATE POLICY branch_read ON audit_logs FOR SELECT TO authenticated\r\n  USING (branch_id = (SELECT public.current_device_branch()));\r\nCREATE POLICY branch_append ON audit_logs FOR INSERT TO authenticated\r\n  WITH CHECK (branch_id = (SELECT public.current_device_branch()));\r\n\r\nDROP POLICY IF EXISTS branch_isolation ON orders;\r\nCREATE POLICY branch_read   ON orders FOR SELECT TO authenticated USING (branch_id = (SELECT public.current_device_branch()));\r\nDO $$ BEGIN\r\n  EXECUTE 'CREATE POLICY branch_insert ON orders FOR INSERT TO authenticated WITH CHECK (branch_id = (SELECT public.current_device_branch()) AND '\r\n          || pg_temp.same_branch('table_id', 'tables') || ')';\r\n  EXECUTE 'CREATE POLICY branch_update_open ON orders FOR UPDATE TO authenticated '\r\n          || 'USING (branch_id = (SELECT public.current_device_branch()) AND status = ''open'') '\r\n          || 'WITH CHECK (branch_id = (SELECT public.current_device_branch()) AND ' || pg_temp.same_branch('table_id', 'tables') || ')';\r\n  EXECUTE 'CREATE POLICY branch_delete_open ON orders FOR DELETE TO authenticated '\r\n          || 'USING (branch_id = (SELECT public.current_device_branch()) AND status = ''open'')';\r\n\r\n  EXECUTE 'DROP POLICY IF EXISTS branch_isolation ON order_items';\r\n  EXECUTE 'CREATE POLICY branch_read ON order_items FOR SELECT TO authenticated USING (branch_id = (SELECT public.current_device_branch()))';\r\n  EXECUTE 'CREATE POLICY branch_insert ON order_items FOR INSERT TO authenticated WITH CHECK (branch_id = (SELECT public.current_device_branch()) AND '\r\n          || pg_temp.same_branch('order_id', 'orders') || ' AND ' || pg_temp.same_branch('product_id', 'products') || ')';\r\n  -- lines of an OPEN bill only (kitchen status changes, voids)\r\n  EXECUTE 'CREATE POLICY branch_update_open ON order_items FOR UPDATE TO authenticated '\r\n          || 'USING (branch_id = (SELECT public.current_device_branch()) AND EXISTS (SELECT 1 FROM public.orders o WHERE o.id = order_id AND o.status = ''open'')) '\r\n          || 'WITH CHECK (branch_id = (SELECT public.current_device_branch()) AND ' || pg_temp.same_branch('order_id', 'orders') || ')';\r\n  EXECUTE 'CREATE POLICY branch_delete_open ON order_items FOR DELETE TO authenticated '\r\n          || 'USING (branch_id = (SELECT public.current_device_branch()) AND EXISTS (SELECT 1 FROM public.orders o WHERE o.id = order_id AND o.status = ''open''))';\r\nEND $$;\r\n\r\n-- ── Tables without their own branch_id: scope through the parent row ──\r\nALTER TABLE modifier_options ENABLE ROW LEVEL SECURITY;\r\nDROP POLICY IF EXISTS branch_isolation ON modifier_options;\r\nCREATE POLICY branch_isolation ON modifier_options FOR ALL TO authenticated\r\n  USING      (EXISTS (SELECT 1 FROM modifier_groups g WHERE g.id = group_id AND g.branch_id = (SELECT public.current_device_branch())))\r\n  WITH CHECK (EXISTS (SELECT 1 FROM modifier_groups g WHERE g.id = group_id AND g.branch_id = (SELECT public.current_device_branch())));\r\n\r\nALTER TABLE product_modifier_groups ENABLE ROW LEVEL SECURITY;\r\nDROP POLICY IF EXISTS branch_isolation ON product_modifier_groups;\r\nCREATE POLICY branch_isolation ON product_modifier_groups FOR ALL TO authenticated\r\n  USING      (EXISTS (SELECT 1 FROM products p WHERE p.id = product_id AND p.branch_id = (SELECT public.current_device_branch())))\r\n  WITH CHECK (EXISTS (SELECT 1 FROM products p WHERE p.id = product_id AND p.branch_id = (SELECT public.current_device_branch()))\r\n          AND EXISTS (SELECT 1 FROM modifier_groups g WHERE g.id = group_id AND g.branch_id = (SELECT public.current_device_branch())));\r\n\r\nALTER TABLE employee_fingerprints ENABLE ROW LEVEL SECURITY;\r\nDROP POLICY IF EXISTS branch_isolation ON employee_fingerprints;\r\nCREATE POLICY branch_isolation ON employee_fingerprints FOR ALL TO authenticated\r\n  USING      (EXISTS (SELECT 1 FROM employees e WHERE e.employee_id = employee_fingerprints.employee_id AND e.branch_id = (SELECT public.current_device_branch())))\r\n  WITH CHECK (EXISTS (SELECT 1 FROM employees e WHERE e.employee_id = employee_fingerprints.employee_id AND e.branch_id = (SELECT public.current_device_branch())));\r\n\r\n-- Tables found on production that no migration creates (created by hand earlier).\r\n-- printers carries branch_id; shift_rules hangs off an employee.\r\nSELECT pg_temp.branch_policy('printers');\r\nDO $$ BEGIN\r\n  IF to_regclass('public.shift_rules') IS NOT NULL THEN\r\n    ALTER TABLE shift_rules ENABLE ROW LEVEL SECURITY;\r\n    DROP POLICY IF EXISTS branch_isolation ON shift_rules;\r\n    CREATE POLICY branch_isolation ON shift_rules FOR ALL TO authenticated\r\n      USING      (EXISTS (SELECT 1 FROM employees e WHERE e.employee_id = shift_rules.employee_id AND e.branch_id = (SELECT public.current_device_branch())))\r\n      WITH CHECK (EXISTS (SELECT 1 FROM employees e WHERE e.employee_id = shift_rules.employee_id AND e.branch_id = (SELECT public.current_device_branch())));\r\n  END IF;\r\nEND $$;\r\n\r\n-- ── Functions-only bookkeeping ───────────────────────────────\r\nALTER TABLE bill_counters ENABLE ROW LEVEL SECURITY;      -- no policy\r\nREVOKE ALL ON bill_counters FROM anon, authenticated;\r\nREVOKE ALL ON tenant_invites FROM anon, authenticated;   -- already RLS-on with no policy (0025)\r\n\r\n-- ── Anonymous visitors: menus + branch registry, read-only ───\r\n-- shortcut: any visitor can read any branch's ACTIVE menu (menus are public by\r\n-- nature); narrow to \"the branch of the QR you scanned\" via an RPC if a tenant objects.\r\nREVOKE ALL ON ALL TABLES IN SCHEMA public FROM anon;\r\nALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON TABLES FROM anon;\r\nGRANT SELECT ON products, categories, modifier_groups, modifier_options, product_modifier_groups, branches TO anon;\r\n\r\nDROP POLICY IF EXISTS menu_public_read ON products;\r\nCREATE POLICY menu_public_read ON products FOR SELECT TO anon USING (is_active);\r\nDROP POLICY IF EXISTS menu_public_read ON categories;\r\nCREATE POLICY menu_public_read ON categories FOR SELECT TO anon USING (is_active);\r\nDROP POLICY IF EXISTS menu_public_read ON modifier_groups;\r\nCREATE POLICY menu_public_read ON modifier_groups FOR SELECT TO anon USING (is_active);\r\nDROP POLICY IF EXISTS menu_public_read ON modifier_options;\r\nCREATE POLICY menu_public_read ON modifier_options FOR SELECT TO anon\r\n  USING (EXISTS (SELECT 1 FROM modifier_groups g WHERE g.id = group_id AND g.is_active));\r\nDROP POLICY IF EXISTS menu_public_read ON product_modifier_groups;\r\nCREATE POLICY menu_public_read ON product_modifier_groups FOR SELECT TO anon\r\n  USING (EXISTS (SELECT 1 FROM products p WHERE p.id = product_id AND p.is_active));\r\n\r\n-- ── Storage ──────────────────────────────────────────────────\r\n-- Uploads of menu photos and the payment QR: a branch device, and only into its\r\n-- OWN name (photos under \"<branch>/…\", the QR as \"<branch>.png\") — otherwise one\r\n-- tenant could plant its own payment QR as another tenant's.\r\nDROP POLICY IF EXISTS \"product_images_insert\" ON storage.objects;\r\nCREATE POLICY \"product_images_insert\" ON storage.objects FOR INSERT TO authenticated\r\n  WITH CHECK (bucket_id = 'product-images' AND public.current_device_branch() IS NOT NULL\r\n              AND name LIKE public.current_device_branch() || '/%');\r\nDROP POLICY IF EXISTS \"merchant_qr_write\" ON storage.objects;\r\nCREATE POLICY \"merchant_qr_write\" ON storage.objects FOR INSERT TO authenticated\r\n  WITH CHECK (bucket_id = 'merchant-qr' AND public.current_device_branch() IS NOT NULL\r\n              AND name = public.current_device_branch() || '.png');\r\n-- Receipts: customers may still upload (0007/0012 limit type + size), but nobody\r\n-- may LIST the bucket any more — the list API exposed every branch's customer\r\n-- receipts. The bucket is public, so a receipt still opens from its own URL.\r\nDROP POLICY IF EXISTS \"pickup_receipts_read\" ON storage.objects;\r\n\r\n-- ── Anything else in the schema: locked by default ───────────\r\n-- A table nobody has written a policy for is closed to the API (RLS on, no\r\n-- policy) instead of silently left open.\r\nDO $$\r\nDECLARE t TEXT;\r\nBEGIN\r\n  FOR t IN SELECT tablename FROM pg_tables WHERE schemaname = 'public' AND NOT rowsecurity LOOP\r\n    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);\r\n    RAISE NOTICE 'RLS enabled with no policy (API access closed): %', t;\r\n  END LOOP;\r\nEND $$;\r\n\r\n-- ── Realtime: never broadcast the staff table ─────────────────\r\n-- Its rows carry pin_hash (a 4-digit PIN's hash cracks in seconds), and Supabase\r\n-- does not apply RLS to DELETE events. The app never subscribes to it.\r\nDO $$ BEGIN\r\n  IF EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname = 'supabase_realtime'\r\n             AND schemaname = 'public' AND tablename = 'users') THEN\r\n    ALTER PUBLICATION supabase_realtime DROP TABLE public.users;\r\n  END IF;\r\nEND $$;\r\n\r\nNOTIFY pgrst, 'reload schema';\r\n\r\n-- ============================================================\r\n-- VERIFY (read-only) — every app table should show rowsecurity = true:\r\n--   SELECT tablename, rowsecurity FROM pg_tables WHERE schemaname = 'public' ORDER BY 2, 1;\r\n--\r\n-- ROLLBACK (instant — reopens the database exactly as before this file):\r\n--   DO $$ DECLARE t TEXT; BEGIN\r\n--     FOR t IN SELECT tablename FROM pg_tables WHERE schemaname = 'public'\r\n--              AND tablename NOT IN ('tenant_invites','pin_attempts','bill_counters','super_admins','branch_logins','organizations','branches')\r\n--     LOOP EXECUTE format('ALTER TABLE public.%I DISABLE ROW LEVEL SECURITY', t); END LOOP; END $$;\r\n--   GRANT ALL ON ALL TABLES IN SCHEMA public TO anon;\r\n--   -- keep the staff table's PIN columns hidden (0030) — GRANT ALL above re-opened them:\r\n--   REVOKE SELECT, INSERT, UPDATE ON users FROM anon, authenticated;\r\n--   GRANT SELECT (id, name, employment_number, role, email, status, branch_id, hire_date, hourly_rate, job_role, created_at) ON users TO anon, authenticated;\r\n--   GRANT INSERT (id, name, employment_number, role, pin, email, status, branch_id, hire_date, hourly_rate, job_role, created_at) ON users TO anon, authenticated;\r\n--   GRANT UPDATE (name, employment_number, role, pin, email, status, branch_id, hire_date, hourly_rate, job_role) ON users TO anon, authenticated;\r\n--   REVOKE ALL ON bill_counters, pin_attempts, tenant_invites FROM anon, authenticated;\r\n--   ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON TABLES TO anon;\r\n--   NOTIFY pgrst, 'reload schema';\r\n--   Storage policies changed above can stay (they only narrow uploads).\r\n-- ============================================================\r\n"},{"name":"0033_payments_and_reports.sql","sql":"-- ============================================================\r\n-- 0033_payments_and_reports.sql   (Batch 3 — audit AUD-05/06/19/31)\r\n--\r\n--   pay_order(...)          Whole-bill payment as ONE locked transaction. Until\r\n--                           now the till wrote the totals the browser computed,\r\n--                           with no \"still open?\" guard (two tills could both\r\n--                           take the same bill), wrote no payment rows, and did\r\n--                           loyalty in separate calls whose failure was ignored.\r\n--                           Now the server: refuses a bill that is not open or\r\n--                           already part-paid by item; computes subtotal, tax and\r\n--                           total itself; caps the discount at the subtotal;\r\n--                           redeems loyalty points in the same transaction (no\r\n--                           points, no discount); checks the payments add up;\r\n--                           writes one order_payments row per method; frees the\r\n--                           table; earns loyalty points.\r\n--   void_order_item(...)    Voiding a sent line in one locked transaction (was\r\n--                           three client writes with a client-computed total).\r\n--   get_sales_summary(...)  Revenue / tax / discount / orders / items / expenses\r\n--                           / by payment method / by day for ANY date range,\r\n--                           counted by when the bill was PAID. Reports showed\r\n--                           only \"today\", and Accounting subtracted all-time\r\n--                           expenses from today's revenue.\r\n--   customers: one customer per phone number per branch (digits only).\r\n--\r\n-- All three functions require the caller's own branch (0031's check).\r\n-- Additive & safe. Apply AFTER 0032, BEFORE deploying the matching client.\r\n-- ============================================================\r\n\r\nCREATE OR REPLACE FUNCTION public.pay_order(\r\n  p_order_id      TEXT,\r\n  p_branch_id     TEXT,\r\n  p_payments      JSONB,              -- [{\"method\":\"cash\",\"amount\":12.5}, …]; one entry may omit amount = the whole total\r\n  p_discount      NUMERIC,            -- the till's discount (presets), before loyalty\r\n  p_cashier_id    TEXT,\r\n  p_cashier_name  TEXT,\r\n  p_customer_id   UUID DEFAULT NULL,  -- loyalty customer, if linked\r\n  p_redeem_points INT  DEFAULT 0\r\n) RETURNS JSONB\r\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\n#variable_conflict use_column\r\nDECLARE\r\n  v_order     orders%ROWTYPE;\r\n  v_set       branch_settings%ROWTYPE;\r\n  v_loyal     JSONB;\r\n  v_subtotal  NUMERIC;\r\n  v_redeem_v  NUMERIC := 0;\r\n  v_discount  NUMERIC;\r\n  v_net       NUMERIC;\r\n  v_tax       NUMERIC := 0;\r\n  v_total     NUMERIC;\r\n  v_pay       JSONB;\r\n  v_paid_sum  NUMERIC := 0;\r\n  v_lines     INT;\r\n  v_bill      TEXT;\r\n  v_summary   TEXT;\r\n  v_first_pay TEXT;\r\n  v_pay_id    TEXT;\r\n  v_earned    INT := 0;\r\nBEGIN\r\n  PERFORM public._assert_device_branch(p_branch_id);\r\n\r\n  SELECT * INTO v_order FROM orders WHERE id = p_order_id AND branch_id = p_branch_id FOR UPDATE;\r\n  IF NOT FOUND THEN RAISE EXCEPTION 'Order not found'; END IF;\r\n  IF v_order.status <> 'open' THEN RAISE EXCEPTION 'This bill has already been paid'; END IF;\r\n  IF EXISTS (SELECT 1 FROM order_items WHERE order_id = p_order_id AND paid AND status IS DISTINCT FROM 'cancelled') THEN\r\n    RAISE EXCEPTION 'This bill is partly paid by item — continue paying by item';\r\n  END IF;\r\n\r\n  SELECT COALESCE(SUM(subtotal), 0) INTO v_subtotal\r\n    FROM order_items WHERE order_id = p_order_id AND branch_id = p_branch_id AND status IS DISTINCT FROM 'cancelled';\r\n  IF v_subtotal <= 0 THEN RAISE EXCEPTION 'Nothing to pay on this bill'; END IF;\r\n\r\n  SELECT * INTO v_set FROM branch_settings WHERE branch_id = p_branch_id;\r\n  v_loyal := COALESCE(v_set.loyalty, '{}'::jsonb);\r\n\r\n  -- Loyalty redemption: in this transaction, or not at all.\r\n  IF COALESCE(p_redeem_points, 0) > 0 THEN\r\n    IF p_customer_id IS NULL THEN RAISE EXCEPTION 'Link a customer to redeem points'; END IF;\r\n    IF NOT COALESCE((v_loyal->>'enabled')::boolean, true) THEN RAISE EXCEPTION 'Loyalty is switched off'; END IF;\r\n    IF p_redeem_points < COALESCE((v_loyal->>'minimumRedemption')::int, 100) THEN\r\n      RAISE EXCEPTION 'Need at least % points to redeem', COALESCE((v_loyal->>'minimumRedemption')::int, 100);\r\n    END IF;\r\n    PERFORM public._assert_customer_branch(p_customer_id, p_branch_id);\r\n    IF NOT public._redeem_loyalty_points_impl(p_customer_id, p_order_id, p_redeem_points, p_branch_id) THEN\r\n      RAISE EXCEPTION 'The customer does not have enough points';\r\n    END IF;\r\n    v_redeem_v := round(p_redeem_points::numeric / GREATEST(COALESCE((v_loyal->>'redemptionRate')::numeric, 100), 0.0001), 2);\r\n  END IF;\r\n\r\n  v_discount := LEAST(v_subtotal, round(GREATEST(COALESCE(p_discount, 0), 0) + v_redeem_v, 2));\r\n  v_net      := v_subtotal - v_discount;\r\n  IF COALESCE(v_set.tax_enabled, false) AND COALESCE(v_set.tax_rate, 0) > 0 AND v_net > 0 THEN\r\n    v_tax := round(CASE WHEN v_set.tax_inclusive THEN v_net - v_net / (1 + v_set.tax_rate / 100)\r\n                        ELSE v_net * v_set.tax_rate / 100 END, 2);\r\n  END IF;\r\n  v_total := CASE WHEN COALESCE(v_set.tax_inclusive, false) THEN v_net ELSE v_net + v_tax END;\r\n\r\n  -- Payments must add up to the server's total. A fully discounted bill (total 0)\r\n  -- closes with no payment rows.\r\n  IF v_total > 0 THEN\r\n  IF p_payments IS NULL OR jsonb_typeof(p_payments) <> 'array' THEN RAISE EXCEPTION 'No payment given'; END IF;\r\n  v_lines := jsonb_array_length(p_payments);\r\n  IF v_lines NOT BETWEEN 1 AND 3 THEN RAISE EXCEPTION 'Use one to three payment methods'; END IF;\r\n  IF v_lines = 1 AND (p_payments->0->'amount' IS NULL OR jsonb_typeof(p_payments->0->'amount') = 'null') THEN\r\n    p_payments := jsonb_build_array(jsonb_build_object('method', p_payments->0->>'method', 'amount', v_total));\r\n  END IF;\r\n  FOR v_pay IN SELECT * FROM jsonb_array_elements(p_payments) LOOP\r\n    IF (v_pay->>'method') NOT IN ('cash', 'card', 'qr') THEN RAISE EXCEPTION 'Unknown payment method %', v_pay->>'method'; END IF;\r\n    IF COALESCE((v_pay->>'amount')::numeric, 0) <= 0 THEN RAISE EXCEPTION 'Each payment must be more than zero'; END IF;\r\n    v_paid_sum := v_paid_sum + (v_pay->>'amount')::numeric;\r\n  END LOOP;\r\n  IF abs(v_paid_sum - v_total) > 0.005 THEN\r\n    RAISE EXCEPTION 'Payments add up to % but the bill is %', round(v_paid_sum, 2), v_total;\r\n  END IF;\r\n  END IF;\r\n\r\n  v_bill := COALESCE(v_order.bill_number, public._next_bill_number(p_branch_id, v_order.order_type));\r\n  SELECT CASE WHEN v_total = 0 THEN 'NO CHARGE' WHEN v_lines = 1 THEN upper(p_payments->0->>'method')\r\n              ELSE string_agg(upper(e->>'method') || ' ' || to_char((e->>'amount')::numeric, 'FM999999990.00'), ' + ') END\r\n    INTO v_summary FROM jsonb_array_elements(p_payments) e;\r\n\r\n  FOR v_pay IN SELECT * FROM jsonb_array_elements(CASE WHEN v_total > 0 THEN p_payments ELSE '[]'::jsonb END) LOOP\r\n    v_pay_id := 'opay-' || substr(public._random_token(), 1, 20);\r\n    v_first_pay := COALESCE(v_first_pay, v_pay_id);\r\n    INSERT INTO order_payments (id, order_id, amount, method, item_ids, cashier_id, cashier_name, branch_id)\r\n      VALUES (v_pay_id, p_order_id, round((v_pay->>'amount')::numeric, 2), v_pay->>'method', '[]'::jsonb,\r\n              p_cashier_id, p_cashier_name, p_branch_id);\r\n  END LOOP;\r\n\r\n  UPDATE order_items SET paid = true, paid_at = NOW(), payment_id = v_first_pay\r\n    WHERE order_id = p_order_id AND status IS DISTINCT FROM 'cancelled';\r\n\r\n  UPDATE orders SET status = 'completed', completed_at = NOW(), payment_status = 'paid',\r\n         payment_method = v_summary, bill_number = v_bill,\r\n         subtotal = v_subtotal, discount = v_discount, tax = v_tax, total = v_total,\r\n         pickup_status = CASE WHEN order_type = 'pickup' THEN 'picked' ELSE pickup_status END\r\n    WHERE id = p_order_id;              -- the 0029 trigger closes the table's guest party\r\n\r\n  IF v_order.table_id IS NOT NULL THEN\r\n    UPDATE tables SET status = 'available', current_order_id = NULL, ordering_enabled = false, needs_waiter = false\r\n      WHERE id = v_order.table_id AND branch_id = p_branch_id;\r\n    UPDATE qr_sessions SET active = false, last_activity_at = NOW() WHERE table_id = v_order.table_id;\r\n  END IF;\r\n  IF v_order.order_type = 'pickup' THEN\r\n    UPDATE pickup_tokens SET active = false, status = 'completed' WHERE order_id = p_order_id;\r\n  END IF;\r\n\r\n  IF p_customer_id IS NOT NULL AND COALESCE((v_loyal->>'enabled')::boolean, true) THEN\r\n    PERFORM public._assert_customer_branch(p_customer_id, p_branch_id);\r\n    v_earned := floor(v_total * COALESCE((v_loyal->>'pointsPerDollar')::numeric, 1))::int;\r\n    IF v_earned > 0 THEN\r\n      PERFORM public._earn_loyalty_points_impl(p_customer_id, p_order_id, v_earned, v_total, p_branch_id);\r\n    END IF;\r\n  END IF;\r\n\r\n  RETURN jsonb_build_object(\r\n    'bill_number', v_bill, 'payment_summary', v_summary,\r\n    'subtotal', v_subtotal, 'discount', v_discount, 'tax', v_tax, 'total', v_total,\r\n    'points_redeemed', COALESCE(p_redeem_points, 0), 'points_earned', v_earned);\r\nEND; $$;\r\n\r\nCREATE OR REPLACE FUNCTION public.void_order_item(\r\n  p_item_id TEXT, p_order_id TEXT, p_branch_id TEXT,\r\n  p_reason TEXT, p_actor_id TEXT, p_actor_name TEXT\r\n) RETURNS VOID\r\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\n#variable_conflict use_column\r\nDECLARE v_status TEXT; v_sub NUMERIC;\r\nBEGIN\r\n  PERFORM public._assert_device_branch(p_branch_id);\r\n  SELECT status INTO v_status FROM orders WHERE id = p_order_id AND branch_id = p_branch_id FOR UPDATE;\r\n  IF NOT FOUND THEN RAISE EXCEPTION 'Order not found'; END IF;\r\n  IF v_status <> 'open' THEN RAISE EXCEPTION 'Cannot void an item on a bill that has already been paid'; END IF;\r\n\r\n  UPDATE order_items\r\n     SET status = 'cancelled', cancelled_by = p_actor_id, cancelled_by_name = p_actor_name,\r\n         cancel_reason = NULLIF(left(btrim(p_reason), 300), ''), cancelled_at = NOW()\r\n   WHERE id = p_item_id AND order_id = p_order_id AND branch_id = p_branch_id\r\n     AND NOT paid AND status IS DISTINCT FROM 'cancelled';\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'This item was already paid for or voided — it cannot be voided now.';\r\n  END IF;\r\n\r\n  SELECT COALESCE(SUM(subtotal), 0) INTO v_sub FROM order_items\r\n    WHERE order_id = p_order_id AND branch_id = p_branch_id AND status IS DISTINCT FROM 'cancelled';\r\n  UPDATE orders SET subtotal = v_sub, tax = 0, total = v_sub WHERE id = p_order_id;\r\nEND; $$;\r\n\r\nCREATE OR REPLACE FUNCTION public.get_sales_summary(\r\n  p_branch_id TEXT, p_from TIMESTAMPTZ, p_to TIMESTAMPTZ, p_tz TEXT DEFAULT 'Asia/Kuala_Lumpur'\r\n) RETURNS JSONB\r\nLANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$\r\nDECLARE v_tz TEXT := COALESCE(NULLIF(p_tz, ''), 'Asia/Kuala_Lumpur');\r\nBEGIN\r\n  PERFORM public._assert_device_branch(p_branch_id);\r\n  IF p_to <= p_from THEN RAISE EXCEPTION 'Invalid date range'; END IF;\r\n  IF p_to - p_from > interval '400 days' THEN RAISE EXCEPTION 'Please choose a range of about a year or less'; END IF;\r\n  PERFORM now() AT TIME ZONE v_tz;      -- rejects an unknown timezone name early\r\n\r\n  RETURN (\r\n    WITH done AS (\r\n      SELECT o.id, o.total, o.tax, o.discount, o.order_type, o.completed_at\r\n      FROM orders o\r\n      WHERE o.branch_id = p_branch_id AND o.status = 'completed'\r\n        AND o.completed_at >= p_from AND o.completed_at < p_to\r\n    )\r\n    SELECT jsonb_build_object(\r\n      'revenue',  COALESCE((SELECT SUM(total) FROM done), 0),\r\n      'tax',      COALESCE((SELECT SUM(tax) FROM done), 0),\r\n      'discount', COALESCE((SELECT SUM(discount) FROM done), 0),\r\n      'orders',   (SELECT COUNT(*) FROM done),\r\n      'items',    COALESCE((SELECT SUM(oi.quantity) FROM order_items oi JOIN done d ON d.id = oi.order_id\r\n                            WHERE oi.status IS DISTINCT FROM 'cancelled'), 0),\r\n      'expenses', COALESCE((SELECT SUM(e.amount) FROM expenses e WHERE e.branch_id = p_branch_id\r\n                            AND e.date >= (p_from AT TIME ZONE v_tz)::date\r\n                            AND e.date <= ((p_to - interval '1 millisecond') AT TIME ZONE v_tz)::date), 0),\r\n      'by_type',  COALESCE((SELECT jsonb_object_agg(t, n) FROM (SELECT COALESCE(order_type, 'dine-in') t, COUNT(*) n FROM done GROUP BY 1) x), '{}'::jsonb),\r\n      'by_method', COALESCE((SELECT jsonb_object_agg(m, a) FROM (\r\n                     SELECT op.method m, SUM(op.amount) a FROM order_payments op JOIN done d ON d.id = op.order_id GROUP BY 1) x), '{}'::jsonb),\r\n      'by_day',   COALESCE((SELECT jsonb_agg(jsonb_build_object('day', day, 'revenue', rev, 'orders', n) ORDER BY day) FROM (\r\n                     SELECT to_char(completed_at AT TIME ZONE v_tz, 'YYYY-MM-DD') AS day, SUM(total) rev, COUNT(*) n\r\n                     FROM done GROUP BY 1) x), '[]'::jsonb)\r\n    ));\r\nEND; $$;\r\n\r\n-- One customer per phone number per branch (compared on digits only).\r\nCREATE UNIQUE INDEX IF NOT EXISTS ux_customers_branch_phone\r\n  ON customers (branch_id, regexp_replace(phone, '\\D', '', 'g'));\r\n\r\nREVOKE ALL ON FUNCTION public.pay_order(TEXT, TEXT, JSONB, NUMERIC, TEXT, TEXT, UUID, INT) FROM PUBLIC, anon;\r\nREVOKE ALL ON FUNCTION public.void_order_item(TEXT, TEXT, TEXT, TEXT, TEXT, TEXT) FROM PUBLIC, anon;\r\nREVOKE ALL ON FUNCTION public.get_sales_summary(TEXT, TIMESTAMPTZ, TIMESTAMPTZ, TEXT) FROM PUBLIC, anon;\r\nGRANT EXECUTE ON FUNCTION public.pay_order(TEXT, TEXT, JSONB, NUMERIC, TEXT, TEXT, UUID, INT) TO authenticated;\r\nGRANT EXECUTE ON FUNCTION public.void_order_item(TEXT, TEXT, TEXT, TEXT, TEXT, TEXT) TO authenticated;\r\nGRANT EXECUTE ON FUNCTION public.get_sales_summary(TEXT, TIMESTAMPTZ, TIMESTAMPTZ, TEXT) TO authenticated;\r\n\r\nNOTIFY pgrst, 'reload schema';\r\n\r\n-- ============================================================\r\n-- ROLLBACK (manual; the old client paths still work without these):\r\n--   DROP FUNCTION IF EXISTS public.pay_order(TEXT, TEXT, JSONB, NUMERIC, TEXT, TEXT, UUID, INT);\r\n--   DROP FUNCTION IF EXISTS public.void_order_item(TEXT, TEXT, TEXT, TEXT, TEXT, TEXT);\r\n--   DROP FUNCTION IF EXISTS public.get_sales_summary(TEXT, TIMESTAMPTZ, TIMESTAMPTZ, TEXT);\r\n--   DROP INDEX IF EXISTS ux_customers_branch_phone;\r\n--   NOTIFY pgrst, 'reload schema';\r\n-- ============================================================\r\n"},{"name":"0034_per_branch_keys_and_branding.sql","sql":"-- ============================================================\n-- 0034_per_branch_keys_and_branding.sql   (Batch 4 — audit AUD-07 / AUD-21)\n-- Apply BEFORE deploying the matching client (WorkforceController, HRController).\n-- Safe: only replaces unique constraints with per-branch ones and adds columns.\n--\n-- 1. Keys that were unique across ALL restaurants become unique per branch, so a\n--    second restaurant can have its own EMP-001, SKU or staff e-mail:\n--    employees.employee_id, users.employment_number, users.email, products.sku,\n--    payroll_summary (employee, month, year), attendance_logs (employee, day —\n--    a constraint found only on production).\n-- 2. employee_fingerprints and shift_rules get their own branch_id: their RLS used\n--    to join on employee_id, which is no longer unique across branches.\n-- 3. branch_settings gains business_name, currency and kitchen_whatsapp, and a\n--    public profile function for customer pages (anon can't read branch_settings).\n-- ============================================================\n\n-- 1. Fingerprints / shift rules get their own branch_id, backfilled while\n--    employee_id is still unique.\nALTER TABLE employee_fingerprints ADD COLUMN IF NOT EXISTS branch_id TEXT;\nUPDATE employee_fingerprints f SET branch_id = e.branch_id\n  FROM employees e WHERE e.employee_id = f.employee_id AND f.branch_id IS NULL;\nDO $$ BEGIN\n  IF to_regclass('public.shift_rules') IS NOT NULL THEN\n    ALTER TABLE shift_rules ADD COLUMN IF NOT EXISTS branch_id TEXT;\n    UPDATE shift_rules s SET branch_id = e.branch_id FROM employees e\n      WHERE e.employee_id = s.employee_id AND s.branch_id IS NULL;\n  END IF;\nEND $$;\n\n-- 2. Per-branch unique keys (created before the global ones are dropped).\nCREATE UNIQUE INDEX IF NOT EXISTS ux_employees_branch_emp      ON employees (branch_id, employee_id);\nCREATE UNIQUE INDEX IF NOT EXISTS ux_users_branch_empno        ON users (branch_id, employment_number);\nCREATE UNIQUE INDEX IF NOT EXISTS ux_users_branch_email        ON users (branch_id, lower(email));\nCREATE UNIQUE INDEX IF NOT EXISTS ux_products_branch_sku       ON products (branch_id, sku) WHERE sku IS NOT NULL;\nCREATE UNIQUE INDEX IF NOT EXISTS ux_payroll_branch_emp_period ON payroll_summary (branch_id, employee_id, month, year);\nCREATE UNIQUE INDEX IF NOT EXISTS ux_attendance_branch_emp_day ON attendance_logs (branch_id, employee_id, log_date);\n\n-- 3. Links to an employee by number alone (hand-made on production) become\n--    links by branch + number, keeping their delete behaviour.\nALTER TABLE employee_fingerprints DROP CONSTRAINT IF EXISTS employee_fingerprints_employee_id_fkey;\nALTER TABLE attendance_logs       DROP CONSTRAINT IF EXISTS attendance_logs_employee_id_fkey;\nALTER TABLE payroll_summary       DROP CONSTRAINT IF EXISTS payroll_summary_employee_id_fkey;\nDO $$ BEGIN\n  IF to_regclass('public.shift_rules') IS NOT NULL THEN\n    ALTER TABLE shift_rules DROP CONSTRAINT IF EXISTS shift_rules_employee_id_fkey;\n  END IF;\nEND $$;\n\n-- 4. Drop the all-restaurants unique keys.\nALTER TABLE employees       DROP CONSTRAINT IF EXISTS employees_employee_id_key;\nALTER TABLE users           DROP CONSTRAINT IF EXISTS users_employment_number_key;\nALTER TABLE users           DROP CONSTRAINT IF EXISTS users_email_key;\nALTER TABLE products        DROP CONSTRAINT IF EXISTS products_sku_key;\nALTER TABLE payroll_summary DROP CONSTRAINT IF EXISTS payroll_summary_employee_id_month_year_key;\nALTER TABLE attendance_logs DROP CONSTRAINT IF EXISTS attendance_logs_employee_id_log_date_key;\n\n-- 5. Recreate the employee links per branch (idempotent).\nDO $$ BEGIN\n  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'employee_fingerprints_branch_employee_fkey') THEN\n    ALTER TABLE employee_fingerprints ADD CONSTRAINT employee_fingerprints_branch_employee_fkey\n      FOREIGN KEY (branch_id, employee_id) REFERENCES employees (branch_id, employee_id) ON DELETE CASCADE;\n  END IF;\n  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'attendance_logs_branch_employee_fkey') THEN\n    ALTER TABLE attendance_logs ADD CONSTRAINT attendance_logs_branch_employee_fkey\n      FOREIGN KEY (branch_id, employee_id) REFERENCES employees (branch_id, employee_id);\n  END IF;\n  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'payroll_summary_branch_employee_fkey') THEN\n    ALTER TABLE payroll_summary ADD CONSTRAINT payroll_summary_branch_employee_fkey\n      FOREIGN KEY (branch_id, employee_id) REFERENCES employees (branch_id, employee_id);\n  END IF;\n  IF to_regclass('public.shift_rules') IS NOT NULL\n     AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'shift_rules_branch_employee_fkey') THEN\n    ALTER TABLE shift_rules ADD CONSTRAINT shift_rules_branch_employee_fkey\n      FOREIGN KEY (branch_id, employee_id) REFERENCES employees (branch_id, employee_id) ON DELETE CASCADE;\n  END IF;\nEND $$;\n\n-- 6. RLS for the two tables that now carry their own branch_id.\nDROP POLICY IF EXISTS branch_isolation ON employee_fingerprints;\nCREATE POLICY branch_isolation ON employee_fingerprints FOR ALL TO authenticated\n  USING (branch_id = (SELECT public.current_device_branch()))\n  WITH CHECK (branch_id = (SELECT public.current_device_branch()));\nDO $$ BEGIN\n  IF to_regclass('public.shift_rules') IS NOT NULL THEN\n    DROP POLICY IF EXISTS branch_isolation ON shift_rules;\n    CREATE POLICY branch_isolation ON shift_rules FOR ALL TO authenticated\n      USING (branch_id = (SELECT public.current_device_branch()))\n      WITH CHECK (branch_id = (SELECT public.current_device_branch()));\n  END IF;\nEND $$;\n\n-- Per-branch branding.\nALTER TABLE branch_settings\n  ADD COLUMN IF NOT EXISTS business_name    TEXT,\n  ADD COLUMN IF NOT EXISTS currency         TEXT NOT NULL DEFAULT 'RM',\n  ADD COLUMN IF NOT EXISTS kitchen_whatsapp TEXT,\n  ADD COLUMN IF NOT EXISTS pay_to           TEXT;\n\n-- Public, read-only: the name and currency a customer page shows for a branch.\nCREATE OR REPLACE FUNCTION public.branch_profile(p_branch_id TEXT)\nRETURNS JSONB LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$\n  SELECT jsonb_build_object(\n    'business_name', COALESCE(s.business_name, b.name),\n    'currency', COALESCE(s.currency, 'RM'))\n  FROM branches b LEFT JOIN branch_settings s ON s.branch_id = b.id\n  WHERE b.id = p_branch_id;\n$$;\nREVOKE ALL ON FUNCTION public.branch_profile(TEXT) FROM PUBLIC;\nGRANT EXECUTE ON FUNCTION public.branch_profile(TEXT) TO anon, authenticated;\n\nNOTIFY pgrst, 'reload schema';\n"},{"name":"0035_stock_documents_offline.sql","sql":"-- ============================================================\r\n-- 0035_stock_documents_offline.sql   (Batch 6 — owner decisions of 2026-11-17)\r\n--\r\n-- 1. Stock goes down when an item is sent, for products marked \"track stock\"\r\n--    (products.track_stock, default off so untracked menus are unaffected).\r\n--    Not enough stock = the line is refused (\"Only 2 Mandi left\"). A line that took\r\n--    stock gives it back when it is voided, deleted or its bill is cancelled, however\r\n--    that happens (triggers). guest_state reports tracked items at 0 as sold out.\r\n-- 2. Invoices and quotations are saved with sequential numbers per branch\r\n--    (INV-0001…, QUO-0001…) and can be listed and reprinted (documents table).\r\n-- 3. Offline ordering: a line may carry the device's own id (client_id), so a\r\n--    replay after the connection returns never adds the same line twice.\r\n--\r\n-- Additive (new column, new table, functions replaced with supersets).\r\n-- Apply BEFORE deploying the matching client.\r\n-- ============================================================\r\n\r\nALTER TABLE products ADD COLUMN IF NOT EXISTS track_stock BOOLEAN NOT NULL DEFAULT false;\r\n-- Did this line take stock? (Only those give it back — tracking may be switched on later.)\r\nALTER TABLE order_items ADD COLUMN IF NOT EXISTS stock_taken BOOLEAN NOT NULL DEFAULT false;\r\n\r\nCREATE OR REPLACE FUNCTION public._add_order_items(\r\n  p_order_id      TEXT,\r\n  p_branch_id     TEXT,\r\n  p_added_by      TEXT,\r\n  p_added_by_name TEXT,\r\n  p_items         JSONB\r\n) RETURNS TABLE (\r\n  id TEXT, product_id TEXT, product_name TEXT, quantity INT,\r\n  price NUMERIC, subtotal NUMERIC, station TEXT, status TEXT,\r\n  notes TEXT, modifiers JSONB, added_by_name TEXT\r\n)\r\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\nDECLARE\r\n  v_order   orders%ROWTYPE;\r\n  v_item    JSONB;\r\n  v_pid     TEXT;\r\n  v_qty     INT;\r\n  v_notes   TEXT;\r\n  v_opts    TEXT[];\r\n  v_base    NUMERIC;\r\n  v_pname   TEXT;\r\n  v_station TEXT;\r\n  v_avail   BOOLEAN;\r\n  v_track   BOOLEAN;\r\n  v_stock   INT;\r\n  v_addons  NUMERIC;\r\n  v_mods    JSONB;\r\n  v_found   INT;\r\n  v_price   NUMERIC;\r\n  v_sub     NUMERIC;\r\n  v_new_id  TEXT;\r\n  v_subtotal NUMERIC;\r\nBEGIN\r\n  SELECT * INTO v_order FROM orders o WHERE o.id = p_order_id AND o.branch_id = p_branch_id FOR UPDATE;\r\n  IF NOT FOUND THEN RAISE EXCEPTION 'Order not found'; END IF;\r\n  IF v_order.status <> 'open' THEN RAISE EXCEPTION 'Cannot add items to a bill that is not open'; END IF;\r\n  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN\r\n    RAISE EXCEPTION 'No items to add';\r\n  END IF;\r\n  IF jsonb_array_length(p_items) > 50 THEN RAISE EXCEPTION 'Too many lines in one order (max 50)'; END IF;\r\n\r\n  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP\r\n    v_pid   := v_item->>'product_id';\r\n    v_qty   := COALESCE((v_item->>'quantity')::int, 1);\r\n    IF v_qty < 1 OR v_qty > 99 THEN RAISE EXCEPTION 'Quantity must be between 1 and 99'; END IF;\r\n    v_notes := NULLIF(left(v_item->>'notes', 300), '');\r\n\r\n    SELECT COALESCE(array_agg(val), '{}') INTO v_opts\r\n      FROM jsonb_array_elements_text(COALESCE(v_item->'option_ids', '[]'::jsonb)) AS t(val);\r\n\r\n    -- A line the device already sent (offline replay) is not added twice.\r\n    v_new_id := NULLIF(v_item->>'client_id', '');\r\n    IF v_new_id IS NOT NULL THEN\r\n      IF v_new_id !~ '^item-[0-9a-f-]{36}$' THEN RAISE EXCEPTION 'Invalid line id'; END IF;\r\n      IF EXISTS (SELECT 1 FROM order_items oi WHERE oi.id = v_new_id) THEN\r\n        IF EXISTS (SELECT 1 FROM order_items oi WHERE oi.id = v_new_id AND oi.order_id = p_order_id) THEN CONTINUE; END IF;\r\n        RAISE EXCEPTION 'This line is already on another bill';\r\n      END IF;\r\n    END IF;\r\n\r\n    SELECT p.price, p.name, COALESCE(NULLIF(p.station, ''), 'kitchen'),\r\n           COALESCE(p.kitchen_status, 'available') = 'available'\r\n             AND COALESCE(p.availability_status, 'available') = 'available',\r\n           COALESCE(p.track_stock, false), COALESCE(p.stock, 0)\r\n      INTO v_base, v_pname, v_station, v_avail, v_track, v_stock\r\n      FROM products p WHERE p.id = v_pid AND p.branch_id = p_branch_id AND p.is_active = true;\r\n    IF NOT FOUND THEN RAISE EXCEPTION 'Product % is not on the menu', v_pid; END IF;\r\n    IF NOT v_avail THEN RAISE EXCEPTION '% is not available right now', v_pname; END IF;\r\n    IF v_track THEN\r\n      -- One guarded update (no row lock held for the whole order: two tills can't deadlock).\r\n      UPDATE products p SET stock = p.stock - v_qty\r\n       WHERE p.id = v_pid AND p.branch_id = p_branch_id AND p.stock >= v_qty;\r\n      IF NOT FOUND THEN\r\n        SELECT p.stock INTO v_stock FROM products p WHERE p.id = v_pid;\r\n        RAISE EXCEPTION 'Only % % left', GREATEST(COALESCE(v_stock, 0), 0), v_pname;\r\n      END IF;\r\n    END IF;\r\n\r\n    v_addons := 0;\r\n    v_mods   := '[]'::jsonb;\r\n    IF array_length(v_opts, 1) IS NOT NULL THEN\r\n      SELECT COUNT(*), COALESCE(SUM(mo.add_on_price), 0),\r\n             COALESCE(jsonb_agg(jsonb_build_object(\r\n               'groupId', mo.group_id, 'groupName', mg.name,\r\n               'optionId', mo.id, 'optionName', mo.name, 'price', mo.add_on_price)), '[]'::jsonb)\r\n        INTO v_found, v_addons, v_mods\r\n        FROM modifier_options mo\r\n        JOIN modifier_groups mg ON mg.id = mo.group_id\r\n        JOIN product_modifier_groups pmg ON pmg.group_id = mo.group_id AND pmg.product_id = v_pid\r\n        WHERE mo.id = ANY(v_opts);\r\n      IF v_found <> (SELECT COUNT(DISTINCT x) FROM unnest(v_opts) x) THEN\r\n        RAISE EXCEPTION 'An option chosen for % is not offered for it', v_pname;\r\n      END IF;\r\n    END IF;\r\n\r\n    v_price  := v_base + v_addons;\r\n    v_sub    := v_price * v_qty;\r\n    v_new_id := COALESCE(v_new_id, 'item-' || substr(public._random_token(), 1, 24));\r\n\r\n    INSERT INTO order_items(\r\n      id, order_id, product_id, product_name, quantity, price, subtotal,\r\n      notes, modifiers, status, added_by, added_by_name, station, branch_id, paid, stock_taken)\r\n    VALUES (\r\n      v_new_id, p_order_id, v_pid, v_pname, v_qty, v_price, v_sub,\r\n      v_notes, v_mods, 'pending', p_added_by, p_added_by_name, v_station, p_branch_id, false, v_track);\r\n\r\n    RETURN QUERY SELECT v_new_id, v_pid, v_pname, v_qty, v_price, v_sub,\r\n                        v_station, 'pending'::text, v_notes, v_mods, p_added_by_name;\r\n  END LOOP;\r\n\r\n  -- Tax stays 0 on an open order (applied at payment), as before.\r\n  SELECT COALESCE(SUM(oi.subtotal), 0) INTO v_subtotal\r\n    FROM order_items oi WHERE oi.order_id = p_order_id AND oi.branch_id = p_branch_id\r\n      AND oi.status IS DISTINCT FROM 'cancelled';\r\n  UPDATE orders SET subtotal = v_subtotal, tax = 0, total = v_subtotal WHERE orders.id = p_order_id;\r\nEND; $$;\r\nREVOKE ALL ON FUNCTION public._add_order_items(TEXT, TEXT, TEXT, TEXT, JSONB) FROM PUBLIC, anon, authenticated;\r\n\r\n-- Stock comes back however a line goes away: voided (void_order_item or a direct\r\n-- status change), deleted, its quantity lowered, or its whole bill cancelled/deleted.\r\nCREATE OR REPLACE FUNCTION public._line_returns_stock() RETURNS trigger\r\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\nBEGIN\r\n  IF TG_OP = 'DELETE' THEN\r\n    IF OLD.stock_taken THEN\r\n      UPDATE products SET stock = stock + OLD.quantity WHERE id = OLD.product_id AND branch_id = OLD.branch_id;\r\n    END IF;\r\n    RETURN OLD;\r\n  END IF;\r\n  IF OLD.stock_taken THEN\r\n    IF NEW.status = 'cancelled' AND OLD.status IS DISTINCT FROM 'cancelled' THEN\r\n      UPDATE products SET stock = stock + OLD.quantity WHERE id = OLD.product_id AND branch_id = OLD.branch_id;\r\n      NEW.stock_taken := false;\r\n    ELSIF NEW.quantity <> OLD.quantity THEN\r\n      UPDATE products SET stock = stock + OLD.quantity - NEW.quantity WHERE id = OLD.product_id AND branch_id = OLD.branch_id;\r\n    END IF;\r\n  END IF;\r\n  RETURN NEW;\r\nEND; $$;\r\nREVOKE ALL ON FUNCTION public._line_returns_stock() FROM PUBLIC, anon, authenticated;\r\nDROP TRIGGER IF EXISTS order_items_return_stock ON order_items;\r\nCREATE TRIGGER order_items_return_stock BEFORE UPDATE OF status, quantity OR DELETE ON order_items\r\n  FOR EACH ROW EXECUTE FUNCTION public._line_returns_stock();\r\n\r\nCREATE OR REPLACE FUNCTION public._bill_cancel_returns_stock() RETURNS trigger\r\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\nBEGIN\r\n  WITH back AS (\r\n    UPDATE order_items SET stock_taken = false\r\n     WHERE order_id = NEW.id AND stock_taken AND status IS DISTINCT FROM 'cancelled'\r\n    RETURNING product_id, quantity)\r\n  UPDATE products p SET stock = p.stock + b.qty\r\n    FROM (SELECT product_id, SUM(quantity) AS qty FROM back GROUP BY product_id) b\r\n   WHERE p.id = b.product_id AND p.branch_id = NEW.branch_id;\r\n  RETURN NEW;\r\nEND; $$;\r\nREVOKE ALL ON FUNCTION public._bill_cancel_returns_stock() FROM PUBLIC, anon, authenticated;\r\nDROP TRIGGER IF EXISTS orders_cancel_returns_stock ON orders;\r\nCREATE TRIGGER orders_cancel_returns_stock AFTER UPDATE OF status ON orders\r\n  FOR EACH ROW WHEN (NEW.status = 'cancelled' AND OLD.status IS DISTINCT FROM 'cancelled')\r\n  EXECUTE FUNCTION public._bill_cancel_returns_stock();\r\n\r\n-- The document counters share bill_counters; the public bill-number call must not move them.\r\nCREATE OR REPLACE FUNCTION public.next_bill_number(p_branch_id TEXT, p_order_type TEXT)\r\nRETURNS TEXT\r\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\nBEGIN\r\n  PERFORM public._assert_device_branch(p_branch_id);\r\n  IF p_order_type LIKE 'doc-%' THEN RAISE EXCEPTION 'Unknown order type'; END IF;\r\n  RETURN public._next_bill_number(p_branch_id, p_order_type);\r\nEND; $$;\r\nREVOKE ALL ON FUNCTION public.next_bill_number(TEXT, TEXT) FROM PUBLIC, anon;\r\nGRANT EXECUTE ON FUNCTION public.next_bill_number(TEXT, TEXT) TO authenticated;\r\n\r\n-- Tracked dishes at 0 show as sold out on customer phones.\r\nCREATE OR REPLACE FUNCTION public._sold_out_ids(p_branch_id TEXT)\r\nRETURNS JSONB LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$\r\n  SELECT COALESCE(jsonb_agg(p.id), '[]'::jsonb) FROM products p\r\n  WHERE p.branch_id = p_branch_id AND p.is_active\r\n    AND (COALESCE(p.kitchen_status, 'available') <> 'available'\r\n         OR COALESCE(p.availability_status, 'available') <> 'available'\r\n         OR (p.track_stock AND p.stock <= 0));\r\n$$;\r\nREVOKE ALL ON FUNCTION public._sold_out_ids(TEXT) FROM PUBLIC, anon, authenticated;\r\n\r\nCREATE OR REPLACE FUNCTION public.guest_state(p_session_token TEXT)\r\nRETURNS JSONB\r\nLANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$\r\nDECLARE v_g RECORD;\r\nBEGIN\r\n  SELECT * INTO v_g FROM public._guest(p_session_token);\r\n  IF NOT FOUND THEN RETURN NULL; END IF;\r\n  RETURN jsonb_build_object(\r\n    'guest_label', v_g.guest_label,\r\n    'table_id', v_g.table_id,\r\n    'table_number', v_g.table_number,\r\n    'branch_id', v_g.branch_id,\r\n    'ordering_enabled', v_g.ordering_enabled AND public._branch_open(v_g.branch_id),\r\n    'needs_waiter', v_g.needs_waiter,\r\n    'order_id', v_g.order_id,\r\n    'items', COALESCE((\r\n      SELECT jsonb_agg(jsonb_build_object(\r\n        'id', oi.id, 'product_id', oi.product_id, 'product_name', oi.product_name,\r\n        'quantity', oi.quantity, 'price', oi.price, 'status', oi.status,\r\n        'added_by_name', oi.added_by_name, 'modifiers', oi.modifiers) ORDER BY oi.created_at)\r\n      FROM order_items oi JOIN orders o ON o.id = oi.order_id\r\n      WHERE oi.order_id = v_g.order_id AND oi.branch_id = v_g.branch_id AND o.status = 'open'\r\n        AND oi.status IS DISTINCT FROM 'cancelled'), '[]'::jsonb),\r\n    -- lets the menu grey out dishes the kitchen just marked finished\r\n    'unavailable_product_ids', public._sold_out_ids(v_g.branch_id)\r\n  );\r\nEND; $$;\r\n\r\n-- ── Saved invoices and quotations ────────────────────────────\r\nCREATE TABLE IF NOT EXISTS documents (\r\n  id             TEXT PRIMARY KEY DEFAULT ('doc-' || gen_random_uuid()),\r\n  branch_id      TEXT NOT NULL,\r\n  kind           TEXT NOT NULL CHECK (kind IN ('invoice', 'quotation')),\r\n  number         TEXT NOT NULL,\r\n  customer_name  TEXT,\r\n  customer_phone TEXT,\r\n  total          NUMERIC(12,2) NOT NULL DEFAULT 0,\r\n  data           JSONB NOT NULL,          -- the full printed document (items, notes, discount…)\r\n  created_by     TEXT,\r\n  created_by_name TEXT,\r\n  created_at     TIMESTAMPTZ NOT NULL DEFAULT NOW(),\r\n  UNIQUE (branch_id, kind, number)\r\n);\r\nCREATE INDEX IF NOT EXISTS idx_documents_branch_kind_time ON documents (branch_id, kind, created_at DESC);\r\nALTER TABLE documents ENABLE ROW LEVEL SECURITY;\r\nDROP POLICY IF EXISTS branch_read ON documents;\r\nCREATE POLICY branch_read ON documents FOR SELECT TO authenticated\r\n  USING (branch_id = (SELECT public.current_device_branch()));\r\nREVOKE ALL ON documents FROM anon;\r\nREVOKE INSERT, UPDATE, DELETE ON documents FROM authenticated;   -- saved only through save_document()\r\n\r\nCREATE OR REPLACE FUNCTION public.save_document(\r\n  p_branch_id TEXT, p_kind TEXT, p_data JSONB, p_created_by TEXT, p_created_by_name TEXT\r\n) RETURNS JSONB\r\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\nDECLARE v_num INT; v_number TEXT; v_id TEXT;\r\nBEGIN\r\n  PERFORM public._assert_device_branch(p_branch_id);\r\n  IF p_kind NOT IN ('invoice', 'quotation') THEN RAISE EXCEPTION 'Unknown document type'; END IF;\r\n  IF p_data IS NULL OR jsonb_typeof(p_data) <> 'object' THEN RAISE EXCEPTION 'Nothing to save'; END IF;\r\n  IF length(p_data::text) > 200000 THEN RAISE EXCEPTION 'This document is too large to save'; END IF;\r\n\r\n  INSERT INTO bill_counters (branch_id, order_type, last_number) VALUES (p_branch_id, 'doc-' || p_kind, 1)\r\n  ON CONFLICT (branch_id, order_type) DO UPDATE SET last_number = bill_counters.last_number + 1\r\n  RETURNING last_number INTO v_num;\r\n  v_number := CASE p_kind WHEN 'invoice' THEN 'INV-' ELSE 'QUO-' END || lpad(v_num::text, 4, '0');\r\n\r\n  INSERT INTO documents (branch_id, kind, number, customer_name, customer_phone, total, data, created_by, created_by_name)\r\n  VALUES (p_branch_id, p_kind, v_number,\r\n          left(COALESCE(p_data->'invoiceTo', p_data->'quotationTo')->>'name', 200),\r\n          left(COALESCE(p_data->'invoiceTo', p_data->'quotationTo')->>'phone', 40),\r\n          COALESCE((p_data->>'total')::numeric, 0), p_data, p_created_by, p_created_by_name)\r\n  RETURNING id INTO v_id;\r\n  RETURN jsonb_build_object('id', v_id, 'number', v_number);\r\nEND; $$;\r\nREVOKE ALL ON FUNCTION public.save_document(TEXT, TEXT, JSONB, TEXT, TEXT) FROM PUBLIC, anon;\r\nGRANT EXECUTE ON FUNCTION public.save_document(TEXT, TEXT, JSONB, TEXT, TEXT) TO authenticated;\r\n\r\nNOTIFY pgrst, 'reload schema';\r\n\r\n-- ============================================================\r\n-- ROLLBACK (manual): re-run 0029 (_add_order_items) and 0031 (next_bill_number), then\r\n--   DROP TRIGGER IF EXISTS order_items_return_stock ON order_items;\r\n--   DROP TRIGGER IF EXISTS orders_cancel_returns_stock ON orders;\r\n--   DROP FUNCTION IF EXISTS public._line_returns_stock(), public._bill_cancel_returns_stock();\r\n--   ALTER TABLE order_items DROP COLUMN IF EXISTS stock_taken;\r\n--   DROP FUNCTION IF EXISTS public.save_document(TEXT, TEXT, JSONB, TEXT, TEXT);\r\n--   DROP FUNCTION IF EXISTS public._sold_out_ids(TEXT);\r\n--   DROP TABLE IF EXISTS documents;      -- ⚠ deletes saved invoices/quotations\r\n--   ALTER TABLE products DROP COLUMN IF EXISTS track_stock;\r\n-- ============================================================\r\n"},{"name":"0036_customer_debt_accounts.sql","sql":"-- ============================================================\r\n-- 0036_customer_debt_accounts.sql   (owner decisions of 2026-11-17)\r\n--\r\n-- Customers who pay later (weekly, monthly or \"flexible\"):\r\n--  * debt_accounts   — one per customer: terms, optional credit limit.\r\n--  * debt_entries    — append-only ledger: charge (a bill put on account),\r\n--                      payment (money collected), adjustment (correction, ±).\r\n--  * pay_order accepts the method 'account' (with account_id) for the whole bill\r\n--    or the part not paid in cash/card/QR. The bill counts as a sale on its day\r\n--    (method ACCOUNT); later debt payments are collections, not new sales.\r\n--  * Charging past the account's credit limit is refused.\r\n--  * debt_account_summary(): balance, oldest unpaid charge, due date and\r\n--    overdue flag (weekly = 7 days, monthly = 1 month after the oldest unpaid\r\n--    charge; flexible = no due date).\r\n-- Additive. Apply BEFORE deploying the matching client.\r\n-- ============================================================\r\n\r\nCREATE TABLE IF NOT EXISTS debt_accounts (\r\n  id           TEXT PRIMARY KEY DEFAULT ('debt-' || gen_random_uuid()),\r\n  branch_id    TEXT NOT NULL,\r\n  name         TEXT NOT NULL CHECK (length(btrim(name)) BETWEEN 1 AND 120),\r\n  phone        TEXT CHECK (phone IS NULL OR length(phone) <= 40),\r\n  terms        TEXT NOT NULL DEFAULT 'flexible' CHECK (terms IN ('weekly', 'monthly', 'flexible')),\r\n  credit_limit NUMERIC(12,2) CHECK (credit_limit IS NULL OR credit_limit >= 0),\r\n  notes        TEXT CHECK (notes IS NULL OR length(notes) <= 500),\r\n  is_active    BOOLEAN NOT NULL DEFAULT true,\r\n  created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW()\r\n);\r\nCREATE INDEX IF NOT EXISTS idx_debt_accounts_branch ON debt_accounts (branch_id, name);\r\nALTER TABLE debt_accounts ENABLE ROW LEVEL SECURITY;\r\nDROP POLICY IF EXISTS branch_isolation ON debt_accounts;\r\nCREATE POLICY branch_isolation ON debt_accounts FOR ALL TO authenticated\r\n  USING (branch_id = (SELECT public.current_device_branch()))\r\n  WITH CHECK (branch_id = (SELECT public.current_device_branch()));\r\nREVOKE ALL ON debt_accounts FROM anon;\r\n\r\nCREATE TABLE IF NOT EXISTS debt_entries (\r\n  id              TEXT PRIMARY KEY DEFAULT ('dent-' || gen_random_uuid()),\r\n  branch_id       TEXT NOT NULL,\r\n  account_id      TEXT NOT NULL REFERENCES debt_accounts(id) ON DELETE RESTRICT,  -- an account with history can't be deleted\r\n  kind            TEXT NOT NULL CHECK (kind IN ('charge', 'payment', 'adjustment')),\r\n  amount          NUMERIC(12,2) NOT NULL CHECK (amount <> 0 AND (kind = 'adjustment' OR amount > 0)),\r\n  method          TEXT CHECK (method IS NULL OR method IN ('cash', 'card', 'qr', 'transfer')),\r\n  order_id        TEXT,\r\n  note            TEXT CHECK (note IS NULL OR length(note) <= 300),\r\n  created_by      TEXT,\r\n  created_by_name TEXT,\r\n  created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()\r\n);\r\nCREATE INDEX IF NOT EXISTS idx_debt_entries_account ON debt_entries (account_id, created_at);\r\nCREATE INDEX IF NOT EXISTS idx_debt_entries_branch_time ON debt_entries (branch_id, created_at);\r\nALTER TABLE debt_entries ENABLE ROW LEVEL SECURITY;\r\nDROP POLICY IF EXISTS branch_read ON debt_entries;\r\nCREATE POLICY branch_read ON debt_entries FOR SELECT TO authenticated\r\n  USING (branch_id = (SELECT public.current_device_branch()));\r\nREVOKE ALL ON debt_entries FROM anon;\r\nREVOKE INSERT, UPDATE, DELETE ON debt_entries FROM authenticated;   -- written only by the functions below\r\n\r\n-- What the customer owes now (positive = owes us).\r\nCREATE OR REPLACE FUNCTION public._debt_balance(p_account_id TEXT)\r\nRETURNS NUMERIC LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$\r\n  SELECT COALESCE(SUM(CASE WHEN e.kind = 'payment' THEN -e.amount ELSE e.amount END), 0)\r\n    FROM debt_entries e WHERE e.account_id = p_account_id;\r\n$$;\r\nREVOKE ALL ON FUNCTION public._debt_balance(TEXT) FROM PUBLIC, anon, authenticated;\r\n\r\n-- Locks the account so two tills can't both slip under the limit.\r\nCREATE OR REPLACE FUNCTION public._charge_debt_account(\r\n  p_branch_id TEXT, p_account_id TEXT, p_amount NUMERIC, p_order_id TEXT, p_bill TEXT, p_by TEXT, p_by_name TEXT\r\n) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\nDECLARE v_acc debt_accounts%ROWTYPE; v_bal NUMERIC;\r\nBEGIN\r\n  SELECT * INTO v_acc FROM debt_accounts a WHERE a.id = p_account_id AND a.branch_id = p_branch_id FOR UPDATE;\r\n  IF NOT FOUND THEN RAISE EXCEPTION 'Customer account not found'; END IF;\r\n  IF NOT v_acc.is_active THEN RAISE EXCEPTION 'The account of % is closed', v_acc.name; END IF;\r\n  v_bal := public._debt_balance(p_account_id);\r\n  IF v_acc.credit_limit IS NOT NULL AND v_bal + p_amount > v_acc.credit_limit + 0.005 THEN\r\n    RAISE EXCEPTION '% already owes % — this bill would pass the credit limit of %',\r\n      v_acc.name, to_char(v_bal, 'FM999999990.00'), to_char(v_acc.credit_limit, 'FM999999990.00');\r\n  END IF;\r\n  INSERT INTO debt_entries (branch_id, account_id, kind, amount, order_id, note, created_by, created_by_name)\r\n  VALUES (p_branch_id, p_account_id, 'charge', p_amount, p_order_id, 'Bill ' || p_bill, p_by, p_by_name);\r\nEND; $$;\r\nREVOKE ALL ON FUNCTION public._charge_debt_account(TEXT, TEXT, NUMERIC, TEXT, TEXT, TEXT, TEXT) FROM PUBLIC, anon, authenticated;\r\n\r\nCREATE OR REPLACE FUNCTION public.pay_order(\r\n  p_order_id      TEXT,\r\n  p_branch_id     TEXT,\r\n  p_payments      JSONB,              -- [{\"method\":\"cash\",\"amount\":12.5}, …]; one entry may omit amount = the whole total\r\n  p_discount      NUMERIC,            -- the till's discount (presets), before loyalty\r\n  p_cashier_id    TEXT,\r\n  p_cashier_name  TEXT,\r\n  p_customer_id   UUID DEFAULT NULL,  -- loyalty customer, if linked\r\n  p_redeem_points INT  DEFAULT 0\r\n) RETURNS JSONB\r\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\n#variable_conflict use_column\r\nDECLARE\r\n  v_order     orders%ROWTYPE;\r\n  v_set       branch_settings%ROWTYPE;\r\n  v_loyal     JSONB;\r\n  v_subtotal  NUMERIC;\r\n  v_redeem_v  NUMERIC := 0;\r\n  v_discount  NUMERIC;\r\n  v_net       NUMERIC;\r\n  v_tax       NUMERIC := 0;\r\n  v_total     NUMERIC;\r\n  v_pay       JSONB;\r\n  v_paid_sum  NUMERIC := 0;\r\n  v_lines     INT;\r\n  v_bill      TEXT;\r\n  v_summary   TEXT;\r\n  v_first_pay TEXT;\r\n  v_pay_id    TEXT;\r\n  v_earned    INT := 0;\r\n  v_accounts  INT := 0;\r\nBEGIN\r\n  PERFORM public._assert_device_branch(p_branch_id);\r\n\r\n  SELECT * INTO v_order FROM orders WHERE id = p_order_id AND branch_id = p_branch_id FOR UPDATE;\r\n  IF NOT FOUND THEN RAISE EXCEPTION 'Order not found'; END IF;\r\n  IF v_order.status <> 'open' THEN RAISE EXCEPTION 'This bill has already been paid'; END IF;\r\n  IF EXISTS (SELECT 1 FROM order_items WHERE order_id = p_order_id AND paid AND status IS DISTINCT FROM 'cancelled') THEN\r\n    RAISE EXCEPTION 'This bill is partly paid by item — continue paying by item';\r\n  END IF;\r\n\r\n  SELECT COALESCE(SUM(subtotal), 0) INTO v_subtotal\r\n    FROM order_items WHERE order_id = p_order_id AND branch_id = p_branch_id AND status IS DISTINCT FROM 'cancelled';\r\n  IF v_subtotal <= 0 THEN RAISE EXCEPTION 'Nothing to pay on this bill'; END IF;\r\n\r\n  SELECT * INTO v_set FROM branch_settings WHERE branch_id = p_branch_id;\r\n  v_loyal := COALESCE(v_set.loyalty, '{}'::jsonb);\r\n\r\n  -- Loyalty redemption: in this transaction, or not at all.\r\n  IF COALESCE(p_redeem_points, 0) > 0 THEN\r\n    IF p_customer_id IS NULL THEN RAISE EXCEPTION 'Link a customer to redeem points'; END IF;\r\n    IF NOT COALESCE((v_loyal->>'enabled')::boolean, true) THEN RAISE EXCEPTION 'Loyalty is switched off'; END IF;\r\n    IF p_redeem_points < COALESCE((v_loyal->>'minimumRedemption')::int, 100) THEN\r\n      RAISE EXCEPTION 'Need at least % points to redeem', COALESCE((v_loyal->>'minimumRedemption')::int, 100);\r\n    END IF;\r\n    PERFORM public._assert_customer_branch(p_customer_id, p_branch_id);\r\n    IF NOT public._redeem_loyalty_points_impl(p_customer_id, p_order_id, p_redeem_points, p_branch_id) THEN\r\n      RAISE EXCEPTION 'The customer does not have enough points';\r\n    END IF;\r\n    v_redeem_v := round(p_redeem_points::numeric / GREATEST(COALESCE((v_loyal->>'redemptionRate')::numeric, 100), 0.0001), 2);\r\n  END IF;\r\n\r\n  v_discount := LEAST(v_subtotal, round(GREATEST(COALESCE(p_discount, 0), 0) + v_redeem_v, 2));\r\n  v_net      := v_subtotal - v_discount;\r\n  IF COALESCE(v_set.tax_enabled, false) AND COALESCE(v_set.tax_rate, 0) > 0 AND v_net > 0 THEN\r\n    v_tax := round(CASE WHEN v_set.tax_inclusive THEN v_net - v_net / (1 + v_set.tax_rate / 100)\r\n                        ELSE v_net * v_set.tax_rate / 100 END, 2);\r\n  END IF;\r\n  v_total := CASE WHEN COALESCE(v_set.tax_inclusive, false) THEN v_net ELSE v_net + v_tax END;\r\n\r\n  -- Payments must add up to the server's total. A fully discounted bill (total 0)\r\n  -- closes with no payment rows.\r\n  IF v_total > 0 THEN\r\n  IF p_payments IS NULL OR jsonb_typeof(p_payments) <> 'array' THEN RAISE EXCEPTION 'No payment given'; END IF;\r\n  v_lines := jsonb_array_length(p_payments);\r\n  IF v_lines NOT BETWEEN 1 AND 3 THEN RAISE EXCEPTION 'Use one to three payment methods'; END IF;\r\n  IF v_lines = 1 AND (p_payments->0->'amount' IS NULL OR jsonb_typeof(p_payments->0->'amount') = 'null') THEN\r\n    p_payments := jsonb_build_array((p_payments->0) || jsonb_build_object('amount', v_total));  -- keeps account_id\r\n  END IF;\r\n  FOR v_pay IN SELECT * FROM jsonb_array_elements(p_payments) LOOP\r\n    IF (v_pay->>'method') NOT IN ('cash', 'card', 'qr', 'account') THEN RAISE EXCEPTION 'Unknown payment method %', v_pay->>'method'; END IF;\r\n    IF v_pay->>'method' = 'account' THEN\r\n      v_accounts := v_accounts + 1;\r\n      IF v_accounts > 1 THEN RAISE EXCEPTION 'Only one customer account per bill'; END IF;\r\n      IF NULLIF(v_pay->>'account_id', '') IS NULL THEN RAISE EXCEPTION 'Choose the customer account'; END IF;\r\n    END IF;\r\n    IF COALESCE((v_pay->>'amount')::numeric, 0) <= 0 THEN RAISE EXCEPTION 'Each payment must be more than zero'; END IF;\r\n    v_paid_sum := v_paid_sum + (v_pay->>'amount')::numeric;\r\n  END LOOP;\r\n  IF abs(v_paid_sum - v_total) > 0.005 THEN\r\n    RAISE EXCEPTION 'Payments add up to % but the bill is %', round(v_paid_sum, 2), v_total;\r\n  END IF;\r\n  END IF;\r\n\r\n  v_bill := COALESCE(v_order.bill_number, public._next_bill_number(p_branch_id, v_order.order_type));\r\n  SELECT CASE WHEN v_total = 0 THEN 'NO CHARGE' WHEN v_lines = 1 THEN upper(p_payments->0->>'method')\r\n              ELSE string_agg(upper(e->>'method') || ' ' || to_char((e->>'amount')::numeric, 'FM999999990.00'), ' + ') END\r\n    INTO v_summary FROM jsonb_array_elements(p_payments) e;\r\n\r\n  FOR v_pay IN SELECT * FROM jsonb_array_elements(CASE WHEN v_total > 0 THEN p_payments ELSE '[]'::jsonb END) LOOP\r\n    v_pay_id := 'opay-' || substr(public._random_token(), 1, 20);\r\n    v_first_pay := COALESCE(v_first_pay, v_pay_id);\r\n    INSERT INTO order_payments (id, order_id, amount, method, item_ids, cashier_id, cashier_name, branch_id)\r\n      VALUES (v_pay_id, p_order_id, round((v_pay->>'amount')::numeric, 2), v_pay->>'method', '[]'::jsonb,\r\n              p_cashier_id, p_cashier_name, p_branch_id);\r\n    IF v_pay->>'method' = 'account' THEN\r\n      PERFORM public._charge_debt_account(p_branch_id, v_pay->>'account_id', round((v_pay->>'amount')::numeric, 2),\r\n                                          p_order_id, v_bill, p_cashier_id, p_cashier_name);\r\n    END IF;\r\n  END LOOP;\r\n\r\n  UPDATE order_items SET paid = true, paid_at = NOW(), payment_id = v_first_pay\r\n    WHERE order_id = p_order_id AND status IS DISTINCT FROM 'cancelled';\r\n\r\n  UPDATE orders SET status = 'completed', completed_at = NOW(), payment_status = 'paid',\r\n         payment_method = v_summary, bill_number = v_bill,\r\n         subtotal = v_subtotal, discount = v_discount, tax = v_tax, total = v_total,\r\n         pickup_status = CASE WHEN order_type = 'pickup' THEN 'picked' ELSE pickup_status END\r\n    WHERE id = p_order_id;              -- the 0029 trigger closes the table's guest party\r\n\r\n  IF v_order.table_id IS NOT NULL THEN\r\n    UPDATE tables SET status = 'available', current_order_id = NULL, ordering_enabled = false, needs_waiter = false\r\n      WHERE id = v_order.table_id AND branch_id = p_branch_id;\r\n    UPDATE qr_sessions SET active = false, last_activity_at = NOW() WHERE table_id = v_order.table_id;\r\n  END IF;\r\n  IF v_order.order_type = 'pickup' THEN\r\n    UPDATE pickup_tokens SET active = false, status = 'completed' WHERE order_id = p_order_id;\r\n  END IF;\r\n\r\n  IF p_customer_id IS NOT NULL AND COALESCE((v_loyal->>'enabled')::boolean, true) THEN\r\n    PERFORM public._assert_customer_branch(p_customer_id, p_branch_id);\r\n    v_earned := floor(v_total * COALESCE((v_loyal->>'pointsPerDollar')::numeric, 1))::int;\r\n    IF v_earned > 0 THEN\r\n      PERFORM public._earn_loyalty_points_impl(p_customer_id, p_order_id, v_earned, v_total, p_branch_id);\r\n    END IF;\r\n  END IF;\r\n\r\n  RETURN jsonb_build_object(\r\n    'bill_number', v_bill, 'payment_summary', v_summary,\r\n    'subtotal', v_subtotal, 'discount', v_discount, 'tax', v_tax, 'total', v_total,\r\n    'points_redeemed', COALESCE(p_redeem_points, 0), 'points_earned', v_earned);\r\nEND; $$;\r\nREVOKE ALL ON FUNCTION public.pay_order(TEXT, TEXT, JSONB, NUMERIC, TEXT, TEXT, UUID, INT) FROM PUBLIC, anon;\r\nGRANT EXECUTE ON FUNCTION public.pay_order(TEXT, TEXT, JSONB, NUMERIC, TEXT, TEXT, UUID, INT) TO authenticated;\r\n\r\n-- Money collected against a debt. Returns the new balance.\r\nCREATE OR REPLACE FUNCTION public.record_debt_payment(\r\n  p_branch_id TEXT, p_account_id TEXT, p_amount NUMERIC, p_method TEXT, p_note TEXT, p_by TEXT, p_by_name TEXT\r\n) RETURNS NUMERIC LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\nDECLARE v_bal NUMERIC; v_amt NUMERIC := round(COALESCE(p_amount, 0), 2);\r\nBEGIN\r\n  PERFORM public._assert_device_branch(p_branch_id);\r\n  PERFORM 1 FROM debt_accounts a WHERE a.id = p_account_id AND a.branch_id = p_branch_id FOR UPDATE;\r\n  IF NOT FOUND THEN RAISE EXCEPTION 'Customer account not found'; END IF;\r\n  IF v_amt <= 0 THEN RAISE EXCEPTION 'Enter an amount above zero'; END IF;\r\n  IF p_method NOT IN ('cash', 'card', 'qr', 'transfer') THEN RAISE EXCEPTION 'Unknown payment method %', p_method; END IF;\r\n  v_bal := public._debt_balance(p_account_id);\r\n  IF v_amt > v_bal + 0.005 THEN\r\n    RAISE EXCEPTION 'The customer owes only %', to_char(GREATEST(v_bal, 0), 'FM999999990.00');\r\n  END IF;\r\n  INSERT INTO debt_entries (branch_id, account_id, kind, amount, method, note, created_by, created_by_name)\r\n  VALUES (p_branch_id, p_account_id, 'payment', v_amt, p_method, NULLIF(left(btrim(p_note), 300), ''), p_by, p_by_name);\r\n  RETURN v_bal - v_amt;\r\nEND; $$;\r\nREVOKE ALL ON FUNCTION public.record_debt_payment(TEXT, TEXT, NUMERIC, TEXT, TEXT, TEXT, TEXT) FROM PUBLIC, anon;\r\nGRANT EXECUTE ON FUNCTION public.record_debt_payment(TEXT, TEXT, NUMERIC, TEXT, TEXT, TEXT, TEXT) TO authenticated;\r\n\r\n-- Correction (+ adds to the debt, − forgives part of it). A reason is required.\r\nCREATE OR REPLACE FUNCTION public.adjust_debt(\r\n  p_branch_id TEXT, p_account_id TEXT, p_amount NUMERIC, p_note TEXT, p_by TEXT, p_by_name TEXT\r\n) RETURNS NUMERIC LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\r\nDECLARE v_amt NUMERIC := round(COALESCE(p_amount, 0), 2);\r\nBEGIN\r\n  PERFORM public._assert_device_branch(p_branch_id);\r\n  PERFORM 1 FROM debt_accounts a WHERE a.id = p_account_id AND a.branch_id = p_branch_id FOR UPDATE;\r\n  IF NOT FOUND THEN RAISE EXCEPTION 'Customer account not found'; END IF;\r\n  IF v_amt = 0 THEN RAISE EXCEPTION 'Enter an amount'; END IF;\r\n  IF NULLIF(btrim(p_note), '') IS NULL THEN RAISE EXCEPTION 'Write the reason for the correction'; END IF;\r\n  INSERT INTO debt_entries (branch_id, account_id, kind, amount, note, created_by, created_by_name)\r\n  VALUES (p_branch_id, p_account_id, 'adjustment', v_amt, left(btrim(p_note), 300), p_by, p_by_name);\r\n  RETURN public._debt_balance(p_account_id);\r\nEND; $$;\r\nREVOKE ALL ON FUNCTION public.adjust_debt(TEXT, TEXT, NUMERIC, TEXT, TEXT, TEXT) FROM PUBLIC, anon;\r\nGRANT EXECUTE ON FUNCTION public.adjust_debt(TEXT, TEXT, NUMERIC, TEXT, TEXT, TEXT) TO authenticated;\r\n\r\n-- One row per account: balance, oldest unpaid charge (payments settle the oldest first),\r\n-- due date by terms, overdue flag.\r\nCREATE OR REPLACE FUNCTION public.debt_account_summary(p_branch_id TEXT, p_tz TEXT DEFAULT 'Asia/Kuala_Lumpur')\r\nRETURNS TABLE (\r\n  id TEXT, name TEXT, phone TEXT, terms TEXT, credit_limit NUMERIC, notes TEXT, is_active BOOLEAN,\r\n  balance NUMERIC, oldest_unpaid_at TIMESTAMPTZ, due_date DATE, overdue BOOLEAN, last_payment_at TIMESTAMPTZ\r\n) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$\r\n#variable_conflict use_column\r\nBEGIN\r\n  PERFORM public._assert_device_branch(p_branch_id);\r\n  RETURN QUERY\r\n  WITH e AS (SELECT * FROM debt_entries de WHERE de.branch_id = p_branch_id),\r\n  credit AS (\r\n    SELECT e.account_id, SUM(CASE WHEN e.kind = 'payment' THEN e.amount ELSE -e.amount END) AS paid\r\n      FROM e WHERE e.kind = 'payment' OR (e.kind = 'adjustment' AND e.amount < 0) GROUP BY e.account_id),\r\n  debit AS (\r\n    SELECT e.account_id, e.created_at,\r\n           SUM(e.amount) OVER (PARTITION BY e.account_id ORDER BY e.created_at, e.id) AS running\r\n      FROM e WHERE e.kind = 'charge' OR (e.kind = 'adjustment' AND e.amount > 0)),\r\n  oldest AS (\r\n    SELECT d.account_id, MIN(d.created_at) AS at FROM debit d LEFT JOIN credit c ON c.account_id = d.account_id\r\n     WHERE d.running > COALESCE(c.paid, 0) + 0.005 GROUP BY d.account_id),\r\n  s AS (\r\n    SELECT a.*, public._debt_balance(a.id) AS bal, o.at AS oldest_at,\r\n           (SELECT MAX(x.created_at) FROM e x WHERE x.account_id = a.id AND x.kind = 'payment') AS last_pay\r\n      FROM debt_accounts a LEFT JOIN oldest o ON o.account_id = a.id\r\n     WHERE a.branch_id = p_branch_id)\r\n  SELECT s.id, s.name, s.phone, s.terms, s.credit_limit, s.notes, s.is_active, s.bal,\r\n         CASE WHEN s.bal > 0.005 THEN s.oldest_at END,\r\n         CASE WHEN s.bal > 0.005 AND s.oldest_at IS NOT NULL THEN\r\n           ((s.oldest_at AT TIME ZONE p_tz) + CASE s.terms WHEN 'weekly' THEN interval '7 days' WHEN 'monthly' THEN interval '1 month' END)::date END,\r\n         COALESCE(s.bal > 0.005 AND s.terms <> 'flexible' AND s.oldest_at IS NOT NULL AND\r\n           ((s.oldest_at AT TIME ZONE p_tz) + CASE s.terms WHEN 'weekly' THEN interval '7 days' ELSE interval '1 month' END)::date\r\n             < (NOW() AT TIME ZONE p_tz)::date, false),\r\n         s.last_pay\r\n    FROM s ORDER BY s.name;\r\nEND; $$;\r\nREVOKE ALL ON FUNCTION public.debt_account_summary(TEXT, TEXT) FROM PUBLIC, anon;\r\nGRANT EXECUTE ON FUNCTION public.debt_account_summary(TEXT, TEXT) TO authenticated;\r\n\r\nNOTIFY pgrst, 'reload schema';\r\n\r\n-- ============================================================\r\n-- ROLLBACK (manual): re-run 0033 (pay_order), then\r\n--   DROP FUNCTION IF EXISTS public.debt_account_summary(TEXT, TEXT), public.adjust_debt(TEXT, TEXT, NUMERIC, TEXT, TEXT, TEXT),\r\n--     public.record_debt_payment(TEXT, TEXT, NUMERIC, TEXT, TEXT, TEXT, TEXT),\r\n--     public._charge_debt_account(TEXT, TEXT, NUMERIC, TEXT, TEXT, TEXT, TEXT), public._debt_balance(TEXT);\r\n--   DROP TABLE IF EXISTS debt_entries, debt_accounts;   -- ⚠ deletes every customer debt record\r\n-- ============================================================\r\n"},{"name":"0037_shared_printers.sql","sql":"-- ============================================================\n-- 0037_shared_printers.sql   (2026-11-21)\n--\n-- Printer settings are kept per branch in the database (they were saved only on\n-- each tablet), so a new or reset device picks them up. Each device keeps a local\n-- copy for printing offline. Adds the paper width (58 / 80 mm) that sets the size\n-- of the printed image (Arabic is printed as an image).\n--\n-- The printers table already exists in production (made by hand, same columns);\n-- CREATE TABLE IF NOT EXISTS brings fresh installs and the tests to the same state.\n-- Additive. Apply BEFORE deploying the matching client.\n-- ============================================================\n\nCREATE TABLE IF NOT EXISTS printers (\n  id         TEXT PRIMARY KEY,\n  name       TEXT NOT NULL,\n  type       TEXT NOT NULL,\n  ip_address TEXT,\n  port       INT,\n  usb_path   TEXT,\n  stations   TEXT[] DEFAULT '{}'::text[],\n  is_active  BOOLEAN DEFAULT true,\n  branch_id  TEXT NOT NULL,\n  created_at TIMESTAMPTZ DEFAULT NOW()\n);\nALTER TABLE printers ADD COLUMN IF NOT EXISTS paper_width INT NOT NULL DEFAULT 80;\nDO $$ BEGIN\n  ALTER TABLE printers ADD CONSTRAINT printers_paper_width_check CHECK (paper_width IN (58, 80));\nEXCEPTION WHEN duplicate_object THEN NULL; END $$;\n\nALTER TABLE printers ENABLE ROW LEVEL SECURITY;\nDROP POLICY IF EXISTS branch_isolation ON printers;\nCREATE POLICY branch_isolation ON printers FOR ALL TO authenticated\n  USING (branch_id = (SELECT public.current_device_branch()))\n  WITH CHECK (branch_id = (SELECT public.current_device_branch()));\nREVOKE ALL ON printers FROM anon;\nGRANT SELECT, INSERT, UPDATE, DELETE ON printers TO authenticated;\n\nNOTIFY pgrst, 'reload schema';\n\n-- ROLLBACK (manual): ALTER TABLE printers DROP COLUMN IF EXISTS paper_width;\n"},{"name":"0038_free_plan_tuning.sql","sql":"-- ============================================================\r\n-- 0038_free_plan_tuning.sql   (2026-11-21)\r\n--\r\n-- Keeps the project comfortably inside the Supabase Free plan:\r\n--  * Removes leftover hand-made policies on the HR tables; the per-branch\r\n--    policies from 0032 remain the only rules there.\r\n--  * current_device_branch() is STABLE (same answer within a statement), so\r\n--    calls inside functions are evaluated once.\r\n--  * Adds indexes for the hot paths (sales summary, open bill per table,\r\n--    bill close, reports) and drops 16 duplicate indexes that cost space and\r\n--    write time on every row.\r\n--  * debt_account_summary() computes balances in one pass.\r\n-- Safe to re-run. Apply BEFORE deploying the matching client.\r\n-- ============================================================\r\n\r\nDROP POLICY IF EXISTS \"Allow all for employees\"    ON employees;\r\nDROP POLICY IF EXISTS \"Allow all for fingerprints\" ON employee_fingerprints;\r\nDROP POLICY IF EXISTS \"Allow all for attendance\"   ON attendance_logs;\r\nDROP POLICY IF EXISTS \"Allow all for shift_rules\"  ON shift_rules;\r\nDROP POLICY IF EXISTS \"Allow all for payroll\"      ON payroll_summary;\r\n\r\nALTER FUNCTION public.current_device_branch() STABLE;\r\n\r\n-- Indexes (each skipped quietly where a table/column doesn't exist on an older install).\r\nDO $$\r\nDECLARE stmt TEXT;\r\nBEGIN\r\n  FOREACH stmt IN ARRAY ARRAY[\r\n    'CREATE INDEX IF NOT EXISTS idx_orders_branch_completed ON orders (branch_id, completed_at) WHERE status = ''completed''',\r\n    'CREATE INDEX IF NOT EXISTS idx_orders_open_table ON orders (table_id) WHERE status = ''open''',\r\n    'CREATE INDEX IF NOT EXISTS idx_order_groups_active_order ON order_groups (order_id) WHERE status = ''active''',\r\n    'CREATE INDEX IF NOT EXISTS idx_order_payments_branch_time ON order_payments (branch_id, created_at)',\r\n    'CREATE INDEX IF NOT EXISTS idx_expenses_branch_date ON expenses (branch_id, date)',\r\n    'CREATE INDEX IF NOT EXISTS idx_loyalty_branch_time ON loyalty_transactions (branch_id, created_at)',\r\n    'CREATE INDEX IF NOT EXISTS idx_loyalty_order ON loyalty_transactions (order_id)',\r\n    'CREATE INDEX IF NOT EXISTS idx_audit_branch_time ON audit_logs (branch_id, created_at)']\r\n  LOOP\r\n    BEGIN EXECUTE stmt;\r\n    EXCEPTION WHEN undefined_table OR undefined_column THEN NULL;\r\n    END;\r\n  END LOOP;\r\nEND $$;\r\n\r\n-- Duplicates: each repeats another index exactly, or the leading columns of a unique one.\r\nDROP INDEX IF EXISTS idx_audit_logs_branch, idx_order_items_order_id, idx_guest_sessions_token,\r\n  idx_pickup_tokens_token, idx_qr_sessions_token, idx_qr_sessions_active_table, idx_tables_qr_token,\r\n  idx_att_date, idx_att_employee, idx_att_branch, idx_fp_employee, idx_pay_employee, idx_pay_period,\r\n  idx_customers_phone_branch, idx_customers_branch, idx_emp_branch, idx_pmg_product;\r\n\r\nCREATE OR REPLACE FUNCTION public.debt_account_summary(p_branch_id TEXT, p_tz TEXT DEFAULT 'Asia/Kuala_Lumpur')\r\nRETURNS TABLE (\r\n  id TEXT, name TEXT, phone TEXT, terms TEXT, credit_limit NUMERIC, notes TEXT, is_active BOOLEAN,\r\n  balance NUMERIC, oldest_unpaid_at TIMESTAMPTZ, due_date DATE, overdue BOOLEAN, last_payment_at TIMESTAMPTZ\r\n) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$\r\n#variable_conflict use_column\r\nBEGIN\r\n  PERFORM public._assert_device_branch(p_branch_id);\r\n  RETURN QUERY\r\n  WITH e AS (SELECT * FROM debt_entries de WHERE de.branch_id = p_branch_id),\r\n  -- One pass per account: balance, money paid/forgiven, last payment.\r\n  agg AS (\r\n    SELECT e.account_id,\r\n           SUM(CASE WHEN e.kind = 'payment' THEN -e.amount ELSE e.amount END) AS bal,\r\n           SUM(CASE WHEN e.kind = 'payment' THEN e.amount WHEN e.kind = 'adjustment' AND e.amount < 0 THEN -e.amount ELSE 0 END) AS paid,\r\n           MAX(e.created_at) FILTER (WHERE e.kind = 'payment') AS last_pay\r\n      FROM e GROUP BY e.account_id),\r\n  debit AS (\r\n    SELECT e.account_id, e.created_at,\r\n           SUM(e.amount) OVER (PARTITION BY e.account_id ORDER BY e.created_at, e.id) AS running\r\n      FROM e WHERE e.kind = 'charge' OR (e.kind = 'adjustment' AND e.amount > 0)),\r\n  oldest AS (\r\n    SELECT d.account_id, MIN(d.created_at) AS at FROM debit d LEFT JOIN agg c ON c.account_id = d.account_id\r\n     WHERE d.running > COALESCE(c.paid, 0) + 0.005 GROUP BY d.account_id),\r\n  s AS (\r\n    SELECT a.*, COALESCE(g.bal, 0) AS bal, o.at AS oldest_at, g.last_pay\r\n      FROM debt_accounts a LEFT JOIN agg g ON g.account_id = a.id LEFT JOIN oldest o ON o.account_id = a.id\r\n     WHERE a.branch_id = p_branch_id)\r\n  SELECT s.id, s.name, s.phone, s.terms, s.credit_limit, s.notes, s.is_active, s.bal,\r\n         CASE WHEN s.bal > 0.005 THEN s.oldest_at END,\r\n         CASE WHEN s.bal > 0.005 AND s.oldest_at IS NOT NULL THEN\r\n           ((s.oldest_at AT TIME ZONE p_tz) + CASE s.terms WHEN 'weekly' THEN interval '7 days' WHEN 'monthly' THEN interval '1 month' END)::date END,\r\n         COALESCE(s.bal > 0.005 AND s.terms <> 'flexible' AND s.oldest_at IS NOT NULL AND\r\n           ((s.oldest_at AT TIME ZONE p_tz) + CASE s.terms WHEN 'weekly' THEN interval '7 days' ELSE interval '1 month' END)::date\r\n             < (NOW() AT TIME ZONE p_tz)::date, false),\r\n         s.last_pay\r\n    FROM s ORDER BY s.name;\r\nEND; $$;\r\nREVOKE ALL ON FUNCTION public.debt_account_summary(TEXT, TEXT) FROM PUBLIC, anon;\r\nGRANT EXECUTE ON FUNCTION public.debt_account_summary(TEXT, TEXT) TO authenticated;\r\n\r\nNOTIFY pgrst, 'reload schema';\r\n\r\n-- ROLLBACK (manual): indexes can be recreated from pg_indexes history; re-run 0036 for\r\n-- debt_account_summary; ALTER FUNCTION public.current_device_branch() VOLATILE;\r\n"},{"name":"0039_cleanup_and_archive.sql","sql":"-- ============================================================\n-- 0039_cleanup_and_archive.sql   (owner decisions of 2026-11-21)\n--\n-- Keeps the database inside the Supabase Free plan (500 MB) for years:\n--  1. cleanup_temporary_data(), nightly: failed-PIN records > 1 day, customer QR\n--     sessions > 30 days, closed QR parties > 90 days, finished pickup links\n--     > 30 days, used/expired invites > 30 days, activity log > 24 months.\n--     Never touches orders, payments, debts, documents, attendance or payroll.\n--  2. archive_if_needed(), monthly: only when the database is over 400 MB (80%),\n--     every full month older than the last 6 months is archived: its bills\n--     (with lines and payments) are stored compressed in order_archive (one row\n--     per branch and month, downloadable), its daily and per-product totals go\n--     to sales_daily / product_sales_daily (so reports keep showing them), and\n--     the original rows are removed — all in one transaction.\n--  3. get_sales_summary and product sales include the archived totals; product\n--     sales now count a bill on the day it was paid (as the sales summary does).\n--  4. db_usage(): database and file storage use against the free limits.\n-- The schedules use pg_cron (free); they are skipped where pg_cron is unavailable.\n-- ============================================================\n\nDO $$ BEGIN\n  CREATE EXTENSION IF NOT EXISTS pg_cron;\nEXCEPTION WHEN OTHERS THEN RAISE NOTICE 'pg_cron is not available here; schedules skipped';\nEND $$;\n\n-- ── 1. Temporary data ────────────────────────────────────────\nCREATE OR REPLACE FUNCTION public.cleanup_temporary_data() RETURNS JSONB\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\nDECLARE r JSONB := '{}'::jsonb; n INT; s RECORD;\nBEGIN\n  FOR s IN SELECT * FROM (VALUES\n    ('pin_attempts',   $q$DELETE FROM pin_attempts WHERE attempted_at < now() - interval '1 day'$q$),\n    ('guest_sessions', $q$DELETE FROM guest_sessions WHERE COALESCE(last_seen, created_at) < now() - interval '30 days'$q$),\n    ('order_groups',   $q$DELETE FROM order_groups g WHERE g.status = 'closed' AND COALESCE(g.closed_at, g.created_at) < now() - interval '90 days'\n                          AND NOT EXISTS (SELECT 1 FROM guest_sessions gs WHERE gs.group_id = g.id)$q$),\n    ('pickup_tokens',  $q$DELETE FROM pickup_tokens WHERE created_at < now() - interval '30 days' AND (NOT active OR expires_at < now())$q$),\n    ('tenant_invites', $q$DELETE FROM tenant_invites WHERE COALESCE(used_at, expires_at) < now() - interval '30 days'$q$),\n    ('audit_logs',     $q$DELETE FROM audit_logs WHERE created_at < now() - interval '24 months'$q$)\n  ) AS t(name, stmt) LOOP\n    BEGIN\n      EXECUTE s.stmt; GET DIAGNOSTICS n = ROW_COUNT;\n      r := r || jsonb_build_object(s.name, n);\n    EXCEPTION WHEN undefined_table OR undefined_column THEN NULL;   -- older install\n    END;\n  END LOOP;\n  RETURN r;\nEND; $$;\nREVOKE ALL ON FUNCTION public.cleanup_temporary_data() FROM PUBLIC, anon, authenticated;\n\n-- ── 2. Archive ───────────────────────────────────────────────\nCREATE TABLE IF NOT EXISTS sales_daily (\n  branch_id TEXT NOT NULL,\n  day       DATE NOT NULL,                     -- the restaurant's local day\n  revenue   NUMERIC(14,2) NOT NULL DEFAULT 0,\n  tax       NUMERIC(14,2) NOT NULL DEFAULT 0,\n  discount  NUMERIC(14,2) NOT NULL DEFAULT 0,\n  orders    INT NOT NULL DEFAULT 0,\n  items     INT NOT NULL DEFAULT 0,\n  by_type   JSONB NOT NULL DEFAULT '{}'::jsonb,   -- {\"dine-in\": 12, …}\n  by_method JSONB NOT NULL DEFAULT '{}'::jsonb,   -- {\"cash\": 120.50, …}\n  PRIMARY KEY (branch_id, day)\n);\nCREATE TABLE IF NOT EXISTS product_sales_daily (\n  branch_id    TEXT NOT NULL,\n  day          DATE NOT NULL,\n  product_id   TEXT NOT NULL,\n  product_name TEXT NOT NULL,\n  quantity     INT NOT NULL DEFAULT 0,\n  revenue      NUMERIC(14,2) NOT NULL DEFAULT 0,\n  PRIMARY KEY (branch_id, day, product_id, product_name)\n);\nCREATE TABLE IF NOT EXISTS order_archive (\n  branch_id   TEXT NOT NULL,\n  month       DATE NOT NULL,                   -- first day of the month\n  order_count INT NOT NULL,\n  revenue     NUMERIC(14,2) NOT NULL DEFAULT 0,\n  data        JSONB NOT NULL,                  -- every bill with its lines and payments (stored compressed)\n  archived_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  PRIMARY KEY (branch_id, month)\n);\nDO $$ BEGIN\n  ALTER TABLE order_archive ALTER COLUMN data SET COMPRESSION lz4;\nEXCEPTION WHEN OTHERS THEN NULL;   -- default compression where lz4 isn't built in\nEND $$;\n\nDO $$\nDECLARE t TEXT;\nBEGIN\n  FOREACH t IN ARRAY ARRAY['sales_daily', 'product_sales_daily', 'order_archive'] LOOP\n    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);\n    EXECUTE format('DROP POLICY IF EXISTS branch_read ON %I', t);\n    EXECUTE format('CREATE POLICY branch_read ON %I FOR SELECT TO authenticated USING (branch_id = (SELECT public.current_device_branch()))', t);\n    EXECUTE format('REVOKE ALL ON %I FROM anon', t);\n    EXECUTE format('REVOKE INSERT, UPDATE, DELETE ON %I FROM authenticated', t);   -- written only by the archive\n    EXECUTE format('GRANT SELECT ON %I TO authenticated', t);\n  END LOOP;\nEND $$;\n\n-- One branch, one month: totals + compressed copy + removal, in the caller's transaction.\nCREATE OR REPLACE FUNCTION public._archive_month(p_branch_id TEXT, p_month DATE, p_tz TEXT DEFAULT 'Asia/Kuala_Lumpur')\nRETURNS INT LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\n#variable_conflict use_column\nDECLARE v_from TIMESTAMPTZ; v_to TIMESTAMPTZ; v_n INT;\nBEGIN\n  v_from := (date_trunc('month', p_month)::timestamp) AT TIME ZONE p_tz;\n  v_to   := ((date_trunc('month', p_month) + interval '1 month')::timestamp) AT TIME ZONE p_tz;\n\n  CREATE TEMP TABLE IF NOT EXISTS _arch (id TEXT PRIMARY KEY) ON COMMIT DROP;\n  TRUNCATE _arch;\n  -- Paid bills by the day they were paid; cancelled ones by the day they were opened. Never open bills.\n  INSERT INTO _arch SELECT o.id FROM orders o\n   WHERE o.branch_id = p_branch_id AND o.status <> 'open'\n     AND COALESCE(CASE WHEN o.status = 'completed' THEN o.completed_at END, o.created_at) >= v_from\n     AND COALESCE(CASE WHEN o.status = 'completed' THEN o.completed_at END, o.created_at) <  v_to;\n  SELECT count(*) INTO v_n FROM _arch;\n  IF v_n = 0 THEN RETURN 0; END IF;\n\n  -- Daily totals (completed bills only), added to any already there.\n  INSERT INTO sales_daily AS sd (branch_id, day, revenue, tax, discount, orders, items, by_type, by_method)\n  SELECT p_branch_id, d.day, d.revenue, d.tax, d.discount, d.orders,\n         COALESCE(i.items, 0), COALESCE(t.by_type, '{}'::jsonb), COALESCE(m.by_method, '{}'::jsonb)\n    FROM (SELECT (o.completed_at AT TIME ZONE p_tz)::date AS day, SUM(o.total) revenue, SUM(o.tax) tax,\n                 SUM(o.discount) discount, COUNT(*) orders\n            FROM orders o JOIN _arch a ON a.id = o.id WHERE o.status = 'completed' GROUP BY 1) d\n    LEFT JOIN (SELECT (o.completed_at AT TIME ZONE p_tz)::date AS day, SUM(oi.quantity) items\n                 FROM order_items oi JOIN orders o ON o.id = oi.order_id JOIN _arch a ON a.id = o.id\n                WHERE o.status = 'completed' AND oi.status IS DISTINCT FROM 'cancelled' GROUP BY 1) i ON i.day = d.day\n    LEFT JOIN (SELECT day, jsonb_object_agg(t, n) by_type FROM (\n                 SELECT (o.completed_at AT TIME ZONE p_tz)::date AS day, COALESCE(o.order_type, 'dine-in') t, COUNT(*) n\n                   FROM orders o JOIN _arch a ON a.id = o.id WHERE o.status = 'completed' GROUP BY 1, 2) x GROUP BY day) t ON t.day = d.day\n    LEFT JOIN (SELECT day, jsonb_object_agg(m, amt) by_method FROM (\n                 SELECT (o.completed_at AT TIME ZONE p_tz)::date AS day, op.method m, SUM(op.amount) amt\n                   FROM order_payments op JOIN orders o ON o.id = op.order_id JOIN _arch a ON a.id = o.id\n                  WHERE o.status = 'completed' GROUP BY 1, 2) x GROUP BY day) m ON m.day = d.day\n  ON CONFLICT (branch_id, day) DO UPDATE SET\n    revenue = sd.revenue + EXCLUDED.revenue, tax = sd.tax + EXCLUDED.tax, discount = sd.discount + EXCLUDED.discount,\n    orders = sd.orders + EXCLUDED.orders, items = sd.items + EXCLUDED.items,\n    by_type = (SELECT COALESCE(jsonb_object_agg(k, v), '{}'::jsonb) FROM (\n                 SELECT k, SUM(v::numeric) v FROM (SELECT * FROM jsonb_each_text(sd.by_type) UNION ALL SELECT * FROM jsonb_each_text(EXCLUDED.by_type)) e(k, v) GROUP BY k) z),\n    by_method = (SELECT COALESCE(jsonb_object_agg(k, v), '{}'::jsonb) FROM (\n                 SELECT k, SUM(v::numeric) v FROM (SELECT * FROM jsonb_each_text(sd.by_method) UNION ALL SELECT * FROM jsonb_each_text(EXCLUDED.by_method)) e(k, v) GROUP BY k) z);\n\n  INSERT INTO product_sales_daily AS ps (branch_id, day, product_id, product_name, quantity, revenue)\n  SELECT p_branch_id, (o.completed_at AT TIME ZONE p_tz)::date, COALESCE(oi.product_id, ''), COALESCE(oi.product_name, ''),\n         SUM(oi.quantity), SUM(oi.subtotal)\n    FROM order_items oi JOIN orders o ON o.id = oi.order_id JOIN _arch a ON a.id = o.id\n   WHERE o.status = 'completed' AND oi.status IS DISTINCT FROM 'cancelled'\n   GROUP BY 2, 3, 4\n  ON CONFLICT (branch_id, day, product_id, product_name) DO UPDATE SET\n    quantity = ps.quantity + EXCLUDED.quantity, revenue = ps.revenue + EXCLUDED.revenue;\n\n  -- The full bills, compressed (appended if this month was partly archived before).\n  INSERT INTO order_archive AS oa (branch_id, month, order_count, revenue, data)\n  SELECT p_branch_id, date_trunc('month', p_month)::date, v_n,\n         COALESCE(SUM(o.total) FILTER (WHERE o.status = 'completed'), 0),\n         jsonb_agg(to_jsonb(o) || jsonb_build_object(\n           'items',    COALESCE((SELECT jsonb_agg(to_jsonb(oi) ORDER BY oi.id) FROM order_items oi WHERE oi.order_id = o.id), '[]'::jsonb),\n           'payments', COALESCE((SELECT jsonb_agg(to_jsonb(op) ORDER BY op.id) FROM order_payments op WHERE op.order_id = o.id), '[]'::jsonb))\n           ORDER BY o.created_at)\n    FROM orders o JOIN _arch a ON a.id = o.id\n  ON CONFLICT (branch_id, month) DO UPDATE SET\n    order_count = oa.order_count + EXCLUDED.order_count, revenue = oa.revenue + EXCLUDED.revenue,\n    data = oa.data || EXCLUDED.data, archived_at = NOW();\n\n  -- Remove the originals. Lines of a sold bill must not give stock back on delete (0035 trigger).\n  UPDATE order_items oi SET stock_taken = false FROM _arch a WHERE oi.order_id = a.id AND oi.stock_taken;\n  UPDATE pickup_tokens pt SET order_id = NULL FROM _arch a WHERE pt.order_id = a.id;\n  UPDATE tables t SET current_order_id = NULL FROM _arch a WHERE t.current_order_id = a.id;\n  DELETE FROM order_payments op USING _arch a WHERE op.order_id = a.id;\n  DELETE FROM order_items oi USING _arch a WHERE oi.order_id = a.id;\n  DELETE FROM orders o USING _arch a WHERE o.id = a.id;\n  RETURN v_n;\nEND; $$;\nREVOKE ALL ON FUNCTION public._archive_month(TEXT, DATE, TEXT) FROM PUBLIC, anon, authenticated;\n\n-- Monthly: only above p_limit_bytes; archives every full month older than the last p_keep_months.\nCREATE OR REPLACE FUNCTION public.archive_if_needed(\n  p_limit_bytes BIGINT DEFAULT 400 * 1024 * 1024, p_keep_months INT DEFAULT 6, p_tz TEXT DEFAULT 'Asia/Kuala_Lumpur'\n) RETURNS INT LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\nDECLARE v_cut DATE; v_total INT := 0; r RECORD;\nBEGIN\n  IF pg_database_size(current_database()) < p_limit_bytes THEN RETURN 0; END IF;\n  v_cut := (date_trunc('month', now() AT TIME ZONE p_tz) - make_interval(months => GREATEST(p_keep_months, 3)))::date;\n  FOR r IN\n    SELECT DISTINCT o.branch_id, date_trunc('month', COALESCE(CASE WHEN o.status = 'completed' THEN o.completed_at END, o.created_at) AT TIME ZONE p_tz)::date AS m\n      FROM orders o\n     WHERE o.status <> 'open'\n       AND COALESCE(CASE WHEN o.status = 'completed' THEN o.completed_at END, o.created_at) < (v_cut::timestamp AT TIME ZONE p_tz)\n     ORDER BY 2, 1\n  LOOP\n    v_total := v_total + public._archive_month(r.branch_id, r.m, p_tz);\n  END LOOP;\n  RETURN v_total;\nEND; $$;\nREVOKE ALL ON FUNCTION public.archive_if_needed(BIGINT, INT, TEXT) FROM PUBLIC, anon, authenticated;\n\n-- ── 3. Reports include archived totals ───────────────────────\nCREATE OR REPLACE FUNCTION public.get_sales_summary(\n  p_branch_id TEXT, p_from TIMESTAMPTZ, p_to TIMESTAMPTZ, p_tz TEXT DEFAULT 'Asia/Kuala_Lumpur'\n) RETURNS JSONB\nLANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$\nDECLARE v_tz TEXT := COALESCE(NULLIF(p_tz, ''), 'Asia/Kuala_Lumpur'); v_d1 DATE; v_d2 DATE;\nBEGIN\n  PERFORM public._assert_device_branch(p_branch_id);\n  IF p_to <= p_from THEN RAISE EXCEPTION 'Invalid date range'; END IF;\n  IF p_to - p_from > interval '400 days' THEN RAISE EXCEPTION 'Please choose a range of about a year or less'; END IF;\n  PERFORM now() AT TIME ZONE v_tz;      -- rejects an unknown timezone name early\n  v_d1 := (p_from AT TIME ZONE v_tz)::date;\n  v_d2 := ((p_to - interval '1 millisecond') AT TIME ZONE v_tz)::date;\n\n  RETURN (\n    WITH done AS (\n      SELECT o.id, o.total, o.tax, o.discount, o.order_type, o.completed_at\n      FROM orders o\n      WHERE o.branch_id = p_branch_id AND o.status = 'completed'\n        AND o.completed_at >= p_from AND o.completed_at < p_to\n    ),\n    arch AS (SELECT * FROM sales_daily s WHERE s.branch_id = p_branch_id AND s.day BETWEEN v_d1 AND v_d2)\n    SELECT jsonb_build_object(\n      'revenue',  COALESCE((SELECT SUM(total) FROM done), 0) + COALESCE((SELECT SUM(revenue) FROM arch), 0),\n      'tax',      COALESCE((SELECT SUM(tax) FROM done), 0) + COALESCE((SELECT SUM(tax) FROM arch), 0),\n      'discount', COALESCE((SELECT SUM(discount) FROM done), 0) + COALESCE((SELECT SUM(discount) FROM arch), 0),\n      'orders',   (SELECT COUNT(*) FROM done) + COALESCE((SELECT SUM(orders) FROM arch), 0),\n      'items',    COALESCE((SELECT SUM(oi.quantity) FROM order_items oi JOIN done d ON d.id = oi.order_id\n                            WHERE oi.status IS DISTINCT FROM 'cancelled'), 0) + COALESCE((SELECT SUM(items) FROM arch), 0),\n      'expenses', COALESCE((SELECT SUM(e.amount) FROM expenses e WHERE e.branch_id = p_branch_id\n                            AND e.date >= v_d1 AND e.date <= v_d2), 0),\n      'by_type',  COALESCE((SELECT jsonb_object_agg(t, n) FROM (SELECT t, SUM(n) n FROM (\n                     SELECT COALESCE(order_type, 'dine-in') t, COUNT(*)::numeric n FROM done GROUP BY 1\n                     UNION ALL SELECT k, v::numeric FROM arch, jsonb_each_text(arch.by_type) AS j(k, v)) u GROUP BY t) x), '{}'::jsonb),\n      'by_method', COALESCE((SELECT jsonb_object_agg(m, a) FROM (SELECT m, SUM(a) a FROM (\n                     SELECT op.method m, SUM(op.amount) a FROM order_payments op JOIN done d ON d.id = op.order_id GROUP BY 1\n                     UNION ALL SELECT k, v::numeric FROM arch, jsonb_each_text(arch.by_method) AS j(k, v)) u GROUP BY m) x), '{}'::jsonb),\n      'by_day',   COALESCE((SELECT jsonb_agg(jsonb_build_object('day', day, 'revenue', rev, 'orders', n) ORDER BY day) FROM (\n                     SELECT day, SUM(rev) rev, SUM(n) n FROM (\n                       SELECT to_char(completed_at AT TIME ZONE v_tz, 'YYYY-MM-DD') AS day, SUM(total) rev, COUNT(*) n FROM done GROUP BY 1\n                       UNION ALL SELECT to_char(arch.day, 'YYYY-MM-DD'), arch.revenue, arch.orders FROM arch) u GROUP BY day) x), '[]'::jsonb)\n    ));\nEND; $$;\n\nCREATE OR REPLACE FUNCTION public._get_product_sales_impl(p_branch_id TEXT, p_date_from TIMESTAMPTZ, p_date_to TIMESTAMPTZ)\nRETURNS TABLE (product_id TEXT, product_name TEXT, units_sold BIGINT, revenue NUMERIC)\nLANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$\n  SELECT u.product_id, u.product_name, SUM(u.q)::BIGINT AS units_sold, SUM(u.r)::NUMERIC AS revenue\n  FROM (\n    SELECT oi.product_id, oi.product_name, oi.quantity AS q, oi.subtotal AS r\n      FROM order_items oi JOIN orders o ON o.id = oi.order_id\n     WHERE o.branch_id = p_branch_id AND o.status = 'completed'\n       AND o.completed_at >= p_date_from AND o.completed_at < p_date_to\n       AND oi.status IS DISTINCT FROM 'cancelled'\n    UNION ALL\n    SELECT ps.product_id, ps.product_name, ps.quantity, ps.revenue\n      FROM product_sales_daily ps\n     WHERE ps.branch_id = p_branch_id\n       AND ps.day BETWEEN (p_date_from AT TIME ZONE 'Asia/Kuala_Lumpur')::date\n                      AND ((p_date_to - interval '1 millisecond') AT TIME ZONE 'Asia/Kuala_Lumpur')::date\n  ) u\n  GROUP BY u.product_id, u.product_name\n  ORDER BY units_sold DESC;\n$$;\nREVOKE ALL ON FUNCTION public._get_product_sales_impl(TEXT, TIMESTAMPTZ, TIMESTAMPTZ) FROM PUBLIC, anon, authenticated;\n\n-- ── 4. Usage against the free limits ─────────────────────────\nCREATE OR REPLACE FUNCTION public.db_usage() RETURNS JSONB\nLANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$\nDECLARE v_storage BIGINT := 0;\nBEGIN\n  IF public.current_device_branch() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF;\n  BEGIN\n    SELECT COALESCE(SUM((metadata->>'size')::bigint), 0) INTO v_storage FROM storage.objects;\n  EXCEPTION WHEN OTHERS THEN v_storage := 0;\n  END;\n  RETURN jsonb_build_object(\n    'db_bytes', pg_database_size(current_database()), 'db_limit', 500 * 1024 * 1024,\n    'storage_bytes', v_storage, 'storage_limit', 1024 * 1024 * 1024);\nEND; $$;\nREVOKE ALL ON FUNCTION public.db_usage() FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION public.db_usage() TO authenticated;\n\n-- ── Schedules (UTC; Malaysia is UTC+8) ───────────────────────\nDO $$ BEGIN\n  IF to_regnamespace('cron') IS NOT NULL THEN\n    PERFORM cron.schedule('pos-cleanup', '30 20 * * *', 'SELECT public.cleanup_temporary_data()');   -- 04:30 daily\n    PERFORM cron.schedule('pos-archive', '40 20 1 * *', 'SELECT public.archive_if_needed()');        -- 04:40 on the 1st\n  END IF;\nEND $$;\n\nNOTIFY pgrst, 'reload schema';\n\n-- ROLLBACK (manual): SELECT cron.unschedule('pos-cleanup'); SELECT cron.unschedule('pos-archive');\n--   re-run 0033 (get_sales_summary) and 0031 (_get_product_sales_impl);\n--   DROP FUNCTION public.db_usage(), public.archive_if_needed(BIGINT, INT, TEXT),\n--     public._archive_month(TEXT, DATE, TEXT), public.cleanup_temporary_data();\n--   (keep sales_daily / product_sales_daily / order_archive — they hold archived history)\n"},{"name":"0040_invoice_header.sql","sql":"-- 0040: each restaurant's own invoice / quotation header.\n-- Invoices used to print one restaurant's name, address and logo for everyone.\n-- Now the \"From\" lines and the logo live in the branch's settings, like pay_to.\n\nALTER TABLE public.branch_settings\n  ADD COLUMN IF NOT EXISTS invoice_from TEXT,\n  ADD COLUMN IF NOT EXISTS logo_url     TEXT;\n\n-- The logo is shown as an image on printed documents: only https addresses, kept short.\nALTER TABLE public.branch_settings DROP CONSTRAINT IF EXISTS branch_settings_logo_url_https;\nALTER TABLE public.branch_settings ADD CONSTRAINT branch_settings_logo_url_https\n  CHECK (logo_url IS NULL OR (logo_url ~ '^https://' AND length(logo_url) <= 500));\nALTER TABLE public.branch_settings DROP CONSTRAINT IF EXISTS branch_settings_invoice_from_len;\nALTER TABLE public.branch_settings ADD CONSTRAINT branch_settings_invoice_from_len\n  CHECK (invoice_from IS NULL OR length(invoice_from) <= 1000);\n"},{"name":"0041_fix_staff_pin_hire_date.sql","sql":"-- 0041: staff PIN sign-in failed for every PIN on the live project with\n-- \"structure of query does not match function result type\": there users.hire_date\n-- is timestamptz (schema drift from before 0001), while verify_staff_pin returns\n-- hire_date DATE. Cast it, which is correct for either column type. Same\n-- signature, so CREATE OR REPLACE keeps the existing grants.\n\nCREATE OR REPLACE FUNCTION public.verify_staff_pin(p_pin text, p_device text DEFAULT NULL::text)\n RETURNS TABLE(id text, name text, employment_number text, role text, email text, status text, branch_id text, created_at timestamp with time zone, hire_date date, hourly_rate numeric, job_role text)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'extensions'\nAS $function$\r\nDECLARE\r\n  v_login  TEXT := auth.uid()::text;\r\n  v_device TEXT;\r\n  v_branch TEXT := public.current_device_branch();\r\nBEGIN\r\n  IF v_login IS NULL OR v_branch IS NULL THEN\r\n    RAISE EXCEPTION 'This device is not signed in to a branch. Ask an admin to sign it in.';\r\n  END IF;\r\n  v_device := v_login || ':' || left(COALESCE(p_device, '?'), 64);\r\n  PERFORM pg_advisory_xact_lock(hashtext('pinlogin:' || v_login));   -- count + insert as one step\r\n\r\n  DELETE FROM pin_attempts WHERE attempted_at < NOW() - interval '1 hour';\r\n  IF (SELECT COUNT(*) FROM pin_attempts WHERE device_uid = v_device\r\n        AND attempted_at > NOW() - interval '1 minute') >= 5 THEN\r\n    RAISE EXCEPTION 'Too many wrong PINs on this terminal. Please wait a minute and try again.';\r\n  END IF;\r\n  IF (SELECT COUNT(*) FROM pin_attempts WHERE device_uid LIKE v_login || ':%'\r\n        AND attempted_at > NOW() - interval '1 minute') >= 30 THEN\r\n    RAISE EXCEPTION 'Too many wrong PINs at this branch. Please wait a minute and try again.';\r\n  END IF;\r\n\r\n  RETURN QUERY\r\n    SELECT u.id, u.name, u.employment_number, u.role, u.email, u.status,\r\n           u.branch_id, u.created_at, u.hire_date::date, u.hourly_rate::numeric, u.job_role\r\n    FROM users u\r\n    WHERE u.branch_id = v_branch AND u.status = 'active'\r\n      AND u.pin_hash IS NOT NULL AND u.pin_hash = extensions.crypt(p_pin, u.pin_hash)\r\n    LIMIT 1;\r\n\r\n  IF NOT FOUND THEN\r\n    INSERT INTO pin_attempts(device_uid) VALUES (v_device);\r\n  END IF;\r\nEND;\r\n$function$;\n"},{"name":"0042_invoice_numbers_from_1000.sql","sql":"-- 0042: invoice numbers start at 1000 (INV-1000, INV-1001 ...), for every restaurant.\n-- A branch that already printed lower numbers jumps to INV-1000 next; numbers\n-- already printed are not changed. Quotations keep starting at QUO-0001.\n-- Same signature, so CREATE OR REPLACE keeps the existing grants.\n\nCREATE OR REPLACE FUNCTION public.save_document(p_branch_id text, p_kind text, p_data jsonb, p_created_by text, p_created_by_name text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nDECLARE v_num INT; v_number TEXT; v_id TEXT;\nBEGIN\n  PERFORM public._assert_device_branch(p_branch_id);\n  IF p_kind NOT IN ('invoice', 'quotation') THEN RAISE EXCEPTION 'Unknown document type'; END IF;\n  IF p_data IS NULL OR jsonb_typeof(p_data) <> 'object' THEN RAISE EXCEPTION 'Nothing to save'; END IF;\n  IF length(p_data::text) > 200000 THEN RAISE EXCEPTION 'This document is too large to save'; END IF;\n\n  INSERT INTO bill_counters (branch_id, order_type, last_number) VALUES (p_branch_id, 'doc-' || p_kind, CASE p_kind WHEN 'invoice' THEN 1000 ELSE 1 END)  -- invoices start at INV-1000\n  ON CONFLICT (branch_id, order_type) DO UPDATE SET last_number = GREATEST(bill_counters.last_number + 1, CASE p_kind WHEN 'invoice' THEN 1000 ELSE 1 END)\n  RETURNING last_number INTO v_num;\n  v_number := CASE p_kind WHEN 'invoice' THEN 'INV-' ELSE 'QUO-' END || lpad(v_num::text, 4, '0');\n\n  INSERT INTO documents (branch_id, kind, number, customer_name, customer_phone, total, data, created_by, created_by_name)\n  VALUES (p_branch_id, p_kind, v_number,\n          left(COALESCE(p_data->'invoiceTo', p_data->'quotationTo')->>'name', 200),\n          left(COALESCE(p_data->'invoiceTo', p_data->'quotationTo')->>'phone', 40),\n          COALESCE((p_data->>'total')::numeric, 0), p_data, p_created_by, p_created_by_name)\n  RETURNING id INTO v_id;\n  RETURN jsonb_build_object('id', v_id, 'number', v_number);\nEND; $function$;\n"},{"name":"0043_reconcile_live_drift.sql","sql":"-- 0043: bring every database to what the migrations and the app expect.\n--\n-- The live project had hand-made schema changes from before 0001 that the\n-- migrations never had, and some broke features there (found by comparing the\n-- live catalog with a database built from the migrations, 2026-11-22):\n--   * orders.waiters was text[]; guest_submit, pickup_submit and join_table_group\n--     write '[]'::jsonb, so every customer QR / group / pickup order failed.\n--   * customers.id had no default; the app adds customers without an id.\n--   * loyalty_transactions.customer_name was NOT NULL but is never written, so\n--     earning and redeeming points failed.\n--   * payroll_summary.monthly_salary / employee_fingerprints.enrolled_by were\n--     required without a default (the migrations never required them).\n-- A fresh project (a one-time customer's own Supabase) has none of that drift but\n-- also no realtime tables, which were switched on by hand on the live project.\n--\n-- Every step checks first, so this is safe to run on any database, any number of times.\n\nDO $$\nDECLARE t TEXT;\nBEGIN\n  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public'\n             AND table_name = 'orders' AND column_name = 'waiters' AND udt_name = '_text') THEN\n    ALTER TABLE public.orders ALTER COLUMN waiters DROP DEFAULT;\n    ALTER TABLE public.orders ALTER COLUMN waiters TYPE jsonb USING to_jsonb(waiters);\n    ALTER TABLE public.orders ALTER COLUMN waiters SET DEFAULT '[]'::jsonb;\n  END IF;\n\n  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public'\n             AND table_name = 'customers' AND column_name = 'id' AND column_default IS NULL) THEN\n    EXECUTE format('ALTER TABLE public.customers ALTER COLUMN id SET DEFAULT gen_random_uuid()%s',\n      CASE WHEN (SELECT udt_name FROM information_schema.columns WHERE table_schema = 'public'\n                 AND table_name = 'customers' AND column_name = 'id') = 'text' THEN '::text' ELSE '' END);\n  END IF;\n\n  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public'\n             AND table_name = 'loyalty_transactions' AND column_name = 'customer_name' AND is_nullable = 'NO') THEN\n    ALTER TABLE public.loyalty_transactions ALTER COLUMN customer_name DROP NOT NULL;\n  END IF;\n\n  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public'\n             AND table_name = 'payroll_summary' AND column_name = 'monthly_salary' AND column_default IS NULL) THEN\n    ALTER TABLE public.payroll_summary ALTER COLUMN monthly_salary SET DEFAULT 0;\n  END IF;\n\n  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public'\n             AND table_name = 'employee_fingerprints' AND column_name = 'enrolled_by' AND is_nullable = 'NO') THEN\n    ALTER TABLE public.employee_fingerprints ALTER COLUMN enrolled_by DROP NOT NULL;\n  END IF;\n\n  -- Live updates (RealtimeSyncEngine, kitchen display, attendance) need these tables\n  -- in Supabase's realtime publication. Not users: 0032 keeps it out on purpose.\n  IF EXISTS (SELECT 1 FROM pg_publication WHERE pubname = 'supabase_realtime') THEN\n    FOREACH t IN ARRAY ARRAY['orders', 'order_items', 'tables', 'products', 'categories', 'attendance_logs'] LOOP\n      IF NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname = 'supabase_realtime'\n                     AND schemaname = 'public' AND tablename = t) THEN\n        EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I', t);\n      END IF;\n    END LOOP;\n  END IF;\nEND $$;\n"},{"name":"0044_staff_extra_roles.sql","sql":"-- 0044: an employee can do more than one job (a cashier who is also HR, the\n-- accountant, and sometimes a waiter). `role` stays their main job; extra_roles\n-- lists the others, and the app grants the combined permissions. Kept on both\n-- users (what sign-in reads) and employees (the HR record), like `role`.\n\nALTER TABLE public.users     ADD COLUMN IF NOT EXISTS extra_roles text[] NOT NULL DEFAULT '{}';\nALTER TABLE public.employees ADD COLUMN IF NOT EXISTS extra_roles text[] NOT NULL DEFAULT '{}';\n\n-- Only real, assignable roles (never admin) may be added.\nALTER TABLE public.users DROP CONSTRAINT IF EXISTS users_extra_roles_valid;\nALTER TABLE public.users ADD CONSTRAINT users_extra_roles_valid CHECK (extra_roles <@ ARRAY[\n  'cashier','waiter','swaiter','kitchen','hr','juice','staff','accounting','manager','supervisor']::text[]);\nALTER TABLE public.employees DROP CONSTRAINT IF EXISTS employees_extra_roles_valid;\nALTER TABLE public.employees ADD CONSTRAINT employees_extra_roles_valid CHECK (extra_roles <@ ARRAY[\n  'cashier','waiter','swaiter','kitchen','hr','juice','staff','accounting','manager','supervisor']::text[]);\n\n-- users has column-level grants (0030 hides the PIN columns): allow this one too.\nGRANT SELECT (extra_roles), INSERT (extra_roles), UPDATE (extra_roles) ON public.users TO authenticated;\n\nNOTIFY pgrst, 'reload schema';\n"},{"name":"0045_one_time_licences.sql","sql":"-- 0045: one-time-purchase customers on their own Supabase project.\n--\n-- smartpos_license   On a CUSTOMER's project: the licence the main server signed for\n--                    that project (written by the setup function with the service\n--                    key). Readable by anyone: it is not secret, only signed.\n-- onetime_tenants    On the MAIN project: the register of one-time customers. Only\n--                    the super-admin can read it; the setup function writes it.\n-- find_server(email) On the MAIN project: which server a branch email belongs to, so\n--                    a device signs in to the right project without a setup code.\n--                    Returns only the project address and its public (anon) key.\n\nCREATE TABLE IF NOT EXISTS public.smartpos_license (\n  id         boolean PRIMARY KEY DEFAULT true CHECK (id),   -- one row\n  payload    text NOT NULL,\n  sig        text NOT NULL,\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\nALTER TABLE public.smartpos_license ENABLE ROW LEVEL SECURITY;\nDROP POLICY IF EXISTS smartpos_license_read ON public.smartpos_license;\nCREATE POLICY smartpos_license_read ON public.smartpos_license FOR SELECT TO anon, authenticated USING (true);\nREVOKE ALL ON public.smartpos_license FROM anon, authenticated;\nGRANT SELECT ON public.smartpos_license TO anon, authenticated;\n\nCREATE TABLE IF NOT EXISTS public.onetime_tenants (\n  id          text PRIMARY KEY,\n  name        text NOT NULL,\n  email       text NOT NULL UNIQUE CHECK (email = lower(email)),\n  project_ref text NOT NULL UNIQUE CHECK (project_ref ~ '^[a-z0-9]{20}$'),\n  project_url text NOT NULL CHECK (project_url ~ '^https://[a-z0-9]{20}\\.supabase\\.co$'),\n  anon_key    text NOT NULL,\n  license     jsonb NOT NULL,\n  created_at  timestamptz NOT NULL DEFAULT now()\n);\nALTER TABLE public.onetime_tenants ENABLE ROW LEVEL SECURITY;\nDROP POLICY IF EXISTS onetime_tenants_super_admin ON public.onetime_tenants;\nCREATE POLICY onetime_tenants_super_admin ON public.onetime_tenants FOR SELECT TO authenticated\n  USING (public.is_current_user_super_admin());\nREVOKE ALL ON public.onetime_tenants FROM anon, authenticated;\nGRANT SELECT ON public.onetime_tenants TO authenticated;\n\nCREATE OR REPLACE FUNCTION public.find_server(p_email text)\nRETURNS TABLE (project_url text, anon_key text)\nLANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$\n  SELECT t.project_url, t.anon_key FROM public.onetime_tenants t\n   WHERE t.email = lower(btrim(p_email)) LIMIT 1;\n$$;\nREVOKE ALL ON FUNCTION public.find_server(text) FROM PUBLIC;\nGRANT EXECUTE ON FUNCTION public.find_server(text) TO anon, authenticated;\n\nNOTIFY pgrst, 'reload schema';\n"}];
